  Duration _media3StartupErrorGraceForSource(PlaybackSource? source) {
    if (source == null) return const Duration(seconds: 10);
    if (_isLiveTvMode || _isPublicIptvSource(source)) {
      return const Duration(seconds: 12);
    }
    if (source.sourceClass == PlaybackSourceClass.p2p) {
      return const Duration(seconds: 16);
    }
    if (_isHlsSource(source)) return const Duration(seconds: 16);
    return const Duration(seconds: 10);
  }

  bool _media3StartupGraceActive(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration? elapsed,
  ) {
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (source == null || elapsed == null) return false;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (elapsed >= _media3StartupErrorGraceForSource(source)) return false;
    final nearStartup = controller.position < const Duration(seconds: 5) &&
        _lastKnownPlaybackPosition < const Duration(seconds: 5);
    if (!nearStartup) return false;
    return controller.duration <= Duration.zero ||
        controller.size == Size.zero ||
        controller.isBuffering;
  }

  bool get _libVlcContinuousTsActive {
    return (_libVlcHlsRelay != null || _mobileLibVlcRelayActive) &&
        _controller?.engine == _NativePlaybackEngine.libvlc;
  }

  bool get _libVlcContinuousTsRelayProofReady {
    return _libVlcContinuousTsActive &&
        _libVlcContinuousTsDurationAccepted &&
        _libVlcContinuousTsStreamedSegments > 0 &&
        _libVlcContinuousTsStreamedBytes >=
            _libVlcContinuousTsMediaProofBytes &&
        _libVlcContinuousTsUpstreamErrors == 0;
  }

  bool _libVlcContinuousTsTransportRecentlyActive(DateTime now) {
    if (!_libVlcContinuousTsActive) return false;
    final lastActivityAt = _libVlcContinuousTsLastTransportActivityAt;
    if (lastActivityAt == null) return false;
    return now.difference(lastActivityAt) <=
        _libVlcContinuousTsTransportFreshness;
  }

  Duration _libVlcContinuousTsRemainingLead(Duration position) {
    if (!_libVlcContinuousTsActive ||
        _libVlcContinuousTsBufferedPosition <= position) {
      return Duration.zero;
    }
    return _libVlcContinuousTsBufferedPosition - position;
  }

  Duration _libVlcRelayPlaybackPosition(Duration fallback) {
    final controller = _controller;
    if (controller == null ||
        controller.engine != _NativePlaybackEngine.libvlc ||
        !controller.isInitialized ||
        controller.hasError) {
      return _heldPlaybackAnchor(fallback: fallback);
    }
    return _resumeAnchoredPlaybackPosition(controller);
  }

  bool get _libVlcContinuousTsStartupProofReady {
    return _libVlcContinuousTsActive &&
        _libVlcContinuousTsDurationAccepted &&
        _libVlcContinuousTsStartupLeadReady;
  }

  bool _shouldHoldLibVlcContinuousTsStartupLead(
    _NativePlaybackController controller,
    PlaybackSource? source, {
    DateTime? now,
  }) {
    if (controller.engine != _NativePlaybackEngine.libvlc) return false;
    if (source == null || !_isHlsSource(source)) return false;
    if (!_libVlcContinuousTsActive ||
        _libVlcContinuousTsStartupLeadReady ||
        _libVlcContinuousTsUpstreamErrors > 0 ||
        controller.hasError) {
      return false;
    }
    final startedAt = _nativeWallClockStartedAt;
    if (startedAt == null) return true;
    return (now ?? DateTime.now()).difference(startedAt) <
        _libVlcContinuousTsStartupProofBudget(
          source,
          _NativePlaybackEngine.libvlc,
        );
  }

  Duration get _libVlcReleaseSettle {
    final settings = AppState.playerBehaviorSettings.value;
    final milliseconds = settings.experimentalControlsEnabled
        ? settings.libVlcReleaseSettleMs
        : const PlayerBehaviorSettings().libVlcReleaseSettleMs;
    return Duration(milliseconds: milliseconds);
  }

  Duration get _stallWatchdogInterval {
    final settings = AppState.playerBehaviorSettings.value;
    final seconds = settings.experimentalControlsEnabled
        ? settings.stallWatchdogSeconds
        : const PlayerBehaviorSettings().stallWatchdogSeconds;
    return Duration(seconds: seconds);
  }

  Duration get _transientPlaybackRecoveryGrace {
    return const Duration(milliseconds: 4500);
  }

  Duration get _deadPauseRecoveryGrace {
    return const Duration(milliseconds: 3500);
  }

  int _bufferingRecoveryTickLimitForSource(PlaybackSource? source) {
    if (source == null) return 6;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return 8;
    if (source.sourceClass == PlaybackSourceClass.p2p) return 10;
    if (_isHlsSource(source) &&
        _resumeProgressAnchorPosition >= const Duration(seconds: 30)) {
      return 4;
    }
    if (_isHlsSource(source)) return 8;
    return 6;
  }

  int _bufferingRecoveryTickLimitForSourceAtPosition(
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    final regularLimit = _bufferingRecoveryTickLimitForSource(source);
    if (source == null) return regularLimit;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return regularLimit;
    if (source.sourceClass == PlaybackSourceClass.p2p) return regularLimit;
    if (_isHlsSource(source) &&
        recoveryPosition >= const Duration(seconds: 30)) {
      return math.min(regularLimit, 4);
    }
    return regularLimit;
  }

  int _zeroVisualStartupRecoveryTickLimitForSource(PlaybackSource? source) {
    final regularLimit = _bufferingRecoveryTickLimitForSource(source);
    if (source == null) return math.min(regularLimit, 4);
    if (_isLiveTvMode || _isPublicIptvSource(source)) return regularLimit;
    if (source.sourceClass == PlaybackSourceClass.p2p) return regularLimit;
    if (_isHlsSource(source)) return math.min(regularLimit, 4);
    return regularLimit;
  }

  int _stallRecoveryTickLimitForSource(PlaybackSource? source) {
    if (source == null) return 6;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return 8;
    if (source.sourceClass == PlaybackSourceClass.p2p) return 10;
    if (_isHlsSource(source)) return 8;
    return 6;
  }

  int _persistentBufferingAnchorRepairLimitForSource(PlaybackSource? source) {
    if (source == null) return 2;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return 4;
    if (source.sourceClass == PlaybackSourceClass.p2p) return 4;
    if (_isHlsSource(source)) return 3;
    return 2;
  }

  int _persistentBufferingAnchorEscapeTickLimitForSource(
    PlaybackSource? source,
  ) {
    final baseLimit = _bufferingRecoveryTickLimitForSource(source) *
        (_persistentBufferingAnchorRepairLimitForSource(source) + 1);
    if (source != null &&
        source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _resumeProgressAnchorPosition >= const Duration(seconds: 30)) {
      return math.min(
        baseLimit,
        _bufferingRecoveryTickLimitForSource(source) + 2,
      );
    }
    if (source != null &&
        _isHlsSource(source) &&
        _media3ResumeAnchorHadStartupVisualProof &&
        _resumeProgressAnchorPosition >= const Duration(seconds: 30)) {
      return math.min(
        baseLimit,
        _bufferingRecoveryTickLimitForSource(source) + 2,
      );
    }
    if (source != null &&
        _sourceHasMedia3DirectHlsRendererDriftRepair(source)) {
      return math.min(
        baseLimit,
        _bufferingRecoveryTickLimitForSource(source) + 2,
      );
    }
    if (source != null &&
        _media3PersistentBufferingNudgeSourceKey ==
            _playbackSourceRuntimeKey(source)) {
      return math.min(
        baseLimit,
        _bufferingRecoveryTickLimitForSource(source) + 4,
      );
    }
    return baseLimit;
  }

  int _persistentBufferingAnchorEscapeTickLimitForSourceAtPosition(
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    final regularLimit =
        _persistentBufferingAnchorEscapeTickLimitForSource(source);
    if (source == null) return regularLimit;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return regularLimit;
    if (source.sourceClass == PlaybackSourceClass.p2p) return regularLimit;
    if (_isHlsSource(source) &&
        recoveryPosition >= const Duration(seconds: 30)) {
      return math.min(
        regularLimit,
        _bufferingRecoveryTickLimitForSourceAtPosition(
              source,
              recoveryPosition,
            ) +
            2,
      );
    }
    return regularLimit;
  }

  int _verifiedZeroVisualEscalationTickLimitForSource(PlaybackSource? source) {
    if (source == null) return 8;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return 12;
    if (source.sourceClass == PlaybackSourceClass.p2p) return 12;
    if (_isHlsSource(source)) return 12;
    return 8;
  }

  _NativePlaybackEngine _engineForSource(PlaybackSource source) {
    final configured = _effectivePlaybackEngine;
    if (configured == 'libvlc') return _NativePlaybackEngine.libvlc;
    if (configured == 'exoplayer') return _NativePlaybackEngine.exoplayer;
    if (configured == 'ksplayer') {
      DiagnosticLog.add(
        'native engine fallback requested=ksplayer reason=platform engine unavailable',
      );
      return _NativePlaybackEngine.exoplayer;
    }
    final type = (source.type ?? '').toLowerCase();
    final url = source.url.toLowerCase();
    if (type == 'dash' || url.contains('.mpd')) {
      return _NativePlaybackEngine.exoplayer;
    }
    if (type == 'hls' || url.contains('.m3u8')) {
      return _NativePlaybackEngine.exoplayer;
    }
    return _NativePlaybackEngine.exoplayer;
  }

  List<PlaybackSource> _prepareProviderSourcesForPlaybackPass(
    List<PlaybackSource> sources, {
    required _QualityPass qualityPass,
    required _NativePlaybackEngine engine,
    required List<_NativePlaybackEngine> enginePasses,
    bool bypassQualityPass = false,
  }) {
    var prepared = _prioritizePreferredQuality(sources);
    prepared = _deprioritizeFailedSources(prepared);
    if (engine == _NativePlaybackEngine.exoplayer) {
      prepared = _excludeFailedMidplayRecoverySources(prepared);
    }
    final effectiveQualityPass =
        bypassQualityPass ? _QualityPass.autoPass : qualityPass;
    if (bypassQualityPass && qualityPass.target != null) {
      DiagnosticLog.add(
        'native verified source cache bypassed saved quality pass=${qualityPass.label} reason=startup_fallback',
      );
    }
    prepared = _filterSourcesForQualityPass(prepared, effectiveQualityPass);
    prepared = _preferStableHlsOrderingForAutoPass(
      prepared,
      effectiveQualityPass,
      engine: engine,
    );
    prepared = mobilePrioritizeExplicitLibVlcSourcesByTransport(
      prepared,
      explicitLibVlc:
          engine == _NativePlaybackEngine.libvlc && _manualLibVlcConfigured,
    );
    prepared =
        _filterRiskyP2pSourcesForQualityPass(prepared, effectiveQualityPass);
    prepared = _limitBaselineP2pSmartStartSources(
      prepared,
      effectiveQualityPass,
    );
    if (prepared.isEmpty) return prepared;
    final ranked = _rankSourcesForEnginePass(
      prepared,
      engine,
      enginePasses,
      qualityPass: effectiveQualityPass,
    );
    return _preferUntriedAdaptiveMedia3RecoverySource(
      ranked,
      engine: engine,
      qualityPass: effectiveQualityPass,
    );
  }

  List<PlaybackSource> _preferUntriedAdaptiveMedia3RecoverySource(
    List<PlaybackSource> sources, {
    required _NativePlaybackEngine engine,
    required _QualityPass qualityPass,
  }) {
    final preferPersistentBufferingAdaptive = qualityPass.target == null &&
        _media3RecoveryQualityCeilingReason ==
            'persistent_buffering_quality_floor';
    if (sources.length < 2 ||
        engine != _NativePlaybackEngine.exoplayer ||
        !preferPersistentBufferingAdaptive) {
      return sources;
    }
    final adaptive = [
      for (final source in sources)
        if (_isAdaptiveHlsAutoSource(source) &&
            _failedSourceAttemptCount(source) == 0)
          source,
    ];
    if (adaptive.isEmpty ||
        adaptive.any((source) => source.url == sources.first.url)) {
      return sources;
    }
    final adaptiveUrls = adaptive.map((source) => source.url).toSet();
    final remaining = [
      for (final source in sources)
        if (!adaptiveUrls.contains(source.url)) source,
    ];
    DiagnosticLog.add(
      'native adaptive hls recovery order restored adaptive=${adaptive.length} remaining=${remaining.length} reason=persistent_buffering_quality_floor',
    );
    return <PlaybackSource>[...adaptive, ...remaining];
  }

  bool _deferFixedHlsAutoProviderIfNeeded(
    NativePlaybackRequest request,
    List<PlaybackSource> preparedSources,
    _QualityPass qualityPass,
    bool bypassQualityPass,
    _NativePlaybackEngine engine,
  ) {
    if (bypassQualityPass) return false;
    if (engine != _NativePlaybackEngine.exoplayer) return false;
    if (widget.liveMode) return false;
    if (!_hasSavedResumeProgressForRoute) return false;
    if (qualityPass.isHighestAvailable || qualityPass.isUnknownQuality) {
      return false;
    }
    if (_providerIndex >= _requests.length - 1) return false;
    if (_deferredFixedHlsAutoProviders.contains(request.providerId)) {
      return false;
    }
    if (preparedSources.isEmpty) return false;
    if (preparedSources.any(_isAdaptiveHlsAutoSource)) return false;
    var knownFixedHls = 0;
    for (final source in preparedSources) {
      if (source.sourceClass != PlaybackSourceClass.direct ||
          !_isHlsSource(source)) {
        return false;
      }
      final rank = _qualityRank(_qualityLabel(source));
      if (rank <= 0) return false;
      knownFixedHls += 1;
    }
    if (knownFixedHls <= 0) return false;
    final deferredRequest = _requests.removeAt(_providerIndex);
    _requests.add(deferredRequest);
    _sourceIndex = 0;
    _deferredFixedHlsAutoProviders.add(request.providerId);
    DiagnosticLog.add(
      'native provider deferred provider=${request.providerId} reason=auto_fixed_hls_wait_for_adaptive_or_later_provider fixedHls=$knownFixedHls remaining=${_requests.length - _providerIndex - 1} ${_qualityDiagnosticContext(qualityPass)}',
    );
    return true;
  }

  bool _deferAdaptiveHlsAutoProviderIfNeeded(
    NativePlaybackRequest request,
    List<PlaybackSource> preparedSources,
    _QualityPass qualityPass,
    bool bypassQualityPass,
    _NativePlaybackEngine engine,
  ) {
    if (bypassQualityPass) return false;
    if (engine != _NativePlaybackEngine.exoplayer) return false;
    if (widget.liveMode) return false;
    if (qualityPass.isHighestAvailable || qualityPass.isUnknownQuality) {
      return false;
    }
    if (_providerIndex >= _requests.length - 1) return false;
    if (_deferredFixedHlsAutoProviders.contains(request.providerId)) {
      return false;
    }
    if (preparedSources.isEmpty) return false;
    final onlyAdaptiveDirectHls = preparedSources.every(
      (source) =>
          source.sourceClass == PlaybackSourceClass.direct &&
          _isAdaptiveHlsAutoSource(source),
    );
    if (!onlyAdaptiveDirectHls) return false;
    final deferredRequest = _requests.removeAt(_providerIndex);
    _requests.add(deferredRequest);
    _sourceIndex = 0;
    _deferredFixedHlsAutoProviders.add(request.providerId);
    DiagnosticLog.add(
      'native provider deferred provider=${request.providerId} reason=media3_resume_adaptive_hls_wait_for_fixed_or_later_provider remaining=${_requests.length - _providerIndex - 1} ${_qualityDiagnosticContext(qualityPass)}',
    );
    return true;
  }

  List<PlaybackSource> _limitBaselineP2pSmartStartSources(
    List<PlaybackSource> sources,
    _QualityPass qualityPass,
  ) {
    const _baselineP2pSmartStartCandidateLimit = 4;
    if (sources.length <= _baselineP2pSmartStartCandidateLimit) {
      return sources;
    }
    final p2pConfig = _p2pPriorityConfigFromSettings();
    if (p2pConfig.enabled) return sources;
    if (!_isP2pOnlySourceRoute) return sources;
    if (qualityPass.isHighestAvailable) return sources;
    final ranked = rankedNativePlaybackSources(
      sources,
      sourceClassAllowed: AppState.playbackSourceClassAllowedForNative,
      p2pConfig: const P2pPriorityConfig(
        enabled: true,
        mode: p2pPriorityModeSmartStart,
        resultsPerQuality: 2,
        avoidRiskyFormats: true,
      ),
    );
    final limited = ranked
        .take(_baselineP2pSmartStartCandidateLimit)
        .toList(growable: false);
    if (limited.length >= sources.length) return sources;
    DiagnosticLog.add(
      'native source filter reason=baseline_p2p_smart_start sourceClass=p2p skipped=${sources.length - limited.length} kept=${limited.length} ${_qualityDiagnosticContext(qualityPass)}',
    );
    return limited;
  }

  List<PlaybackSource> _filterRiskyP2pSourcesForQualityPass(
    List<PlaybackSource> sources,
    _QualityPass qualityPass,
  ) {
    if (sources.isEmpty) return sources;
    final p2pConfig = _p2pPriorityConfigFromSettings();
    if (!_shouldHonorAdvancedP2pRiskFilter(p2pConfig, qualityPass)) {
      return sources;
    }
    var skipped = 0;
    final filtered = <PlaybackSource>[];
    final riskFallbackCandidates = <PlaybackSource>[];
    for (final source in sources) {
      if (source.sourceClass != PlaybackSourceClass.p2p) {
        filtered.add(source);
        continue;
      }
      final riskRank = p2pPlaybackRiskRank(source, config: p2pConfig);
      if (riskRank > 0 || _looksHighEfficiencySource(source)) {
        skipped += 1;
        riskFallbackCandidates.add(source);
        continue;
      }
      filtered.add(source);
    }
    if (skipped <= 0) return sources;
    var fallbackKept = 0;
    if (filtered.length < _advancedP2pAvoidRiskSoftFallbackMinimum &&
        riskFallbackCandidates.isNotEmpty) {
      final rankedFallback = riskFallbackCandidates.toList(growable: false)
        ..sort((a, b) {
          final riskCompare = p2pPlaybackRiskRank(
            a,
            config: p2pConfig,
          ).compareTo(p2pPlaybackRiskRank(b, config: p2pConfig));
          if (riskCompare != 0) return riskCompare;
          return compareP2pSources(a, b, p2pConfig);
        });
      final needed = _advancedP2pAvoidRiskSoftFallbackMinimum - filtered.length;
      final fallback = rankedFallback.take(needed).toList(growable: false);
      fallbackKept = fallback.length;
      filtered.addAll(fallback);
    }
    DiagnosticLog.add(
      'native source filter reason=${fallbackKept > 0 ? 'advanced_p2p_avoid_risk_soft_fallback' : 'advanced_p2p_avoid_risk'} sourceClass=p2p skipped=$skipped kept=${filtered.length} fallbackKept=$fallbackKept ${_qualityDiagnosticContext(qualityPass)}',
    );
    return filtered;
  }

  bool _shouldHonorAdvancedP2pRiskFilter(
    P2pPriorityConfig p2pConfig,
    _QualityPass qualityPass,
  ) {
    if (!p2pConfig.enabled || !p2pConfig.avoidRiskyFormats) return false;
    if (_usingGlobalOverrides && _qualityPreferenceMode == 'higher') {
      return false;
    }
    if (qualityPass.isHighestAvailable) return false;
    final targetRank = qualityPass.target?.rank;
    if (targetRank != null && targetRank >= 2160) return false;
    return true;
  }

  List<PlaybackSource> _rankSourcesForEnginePass(
    List<PlaybackSource> sources,
    _NativePlaybackEngine engine,
    List<_NativePlaybackEngine> enginePasses, {
    required _QualityPass qualityPass,
  }) {
    if (sources.length < 2 ||
        !_shouldApplySourceCompatibilityLadder(
          engine,
          enginePasses,
          qualityPass,
        )) {
      return sources;
    }
    final originalIndexByUrl = <String, int>{};
    for (var index = 0; index < sources.length; index += 1) {
      originalIndexByUrl.putIfAbsent(sources[index].url, () => index);
    }
    final sorted = sources.toList(growable: false)
      ..sort((a, b) {
        final classCompare = _nativeSourceClassRank(
          a,
        ).compareTo(_nativeSourceClassRank(b));
        if (classCompare != 0) return classCompare;

        final failureCompare = _failedSourceAttemptCount(
          a,
        ).compareTo(_failedSourceAttemptCount(b));
        if (failureCompare != 0) return failureCompare;

        final compatibilityCompare = _sourceEngineCompatibilityRank(
          a,
          engine,
        ).compareTo(_sourceEngineCompatibilityRank(b, engine));
        if (compatibilityCompare != 0) return compatibilityCompare;

        return (originalIndexByUrl[a.url] ?? 0).compareTo(
          originalIndexByUrl[b.url] ?? 0,
        );
      });
    final changed = sources.asMap().entries.any(
          (entry) => sorted[entry.key].url != entry.value.url,
        );
    if (changed) {
      final reason = engine == _NativePlaybackEngine.exoplayer
          ? 'media3_compatibility_ladder'
          : 'advanced_source_avoid_risk_ladder';
      DiagnosticLog.add(
        'native source order adjusted reason=$reason engine=${engine.id} count=${sources.length} ${_qualityDiagnosticContext(qualityPass)}',
      );
    }
    _logRankedSourceOrderSnapshot(
      sorted,
      engine: engine,
      reason: changed ? 'adjusted' : 'unchanged',
      qualityPass: qualityPass,
    );
    return sorted;
  }

  void _logRankedSourceOrderSnapshot(
    List<PlaybackSource> sources, {
    required _NativePlaybackEngine engine,
    required String reason,
    required _QualityPass qualityPass,
  }) {
    if (sources.isEmpty) return;
    final entries = <String>[];
    for (var index = 0; index < sources.length && index < 6; index += 1) {
      final source = sources[index];
      entries.add(
        '#${index + 1}:${source.sourceClass.wireName}:rank=${_sourceEngineCompatibilityRank(source, engine)}:${_sourceDiagnosticProfile(source)}',
      );
    }
    final truncated = sources.length > entries.length ? ':truncated' : '';
    DiagnosticLog.add(
      'native source order snapshot reason=$reason engine=${engine.id} count=${sources.length}$truncated entries=${entries.join('|')} ${_qualityDiagnosticContext(qualityPass)}',
    );
  }

  bool _shouldApplySourceCompatibilityLadder(
    _NativePlaybackEngine engine,
    List<_NativePlaybackEngine> enginePasses,
    _QualityPass qualityPass,
  ) {
    return _shouldApplyMedia3CompatibilityLadder(engine, enginePasses) ||
        _shouldHonorAdvancedSourceRiskOrdering(qualityPass);
  }

  bool _shouldApplyMedia3CompatibilityLadder(
    _NativePlaybackEngine engine,
    List<_NativePlaybackEngine> enginePasses,
  ) {
    return engine == _NativePlaybackEngine.exoplayer;
  }

  bool _shouldHonorAdvancedSourceRiskOrdering(_QualityPass qualityPass) {
    return _shouldHonorAdvancedP2pRiskFilter(
      _p2pPriorityConfigFromSettings(),
      qualityPass,
    );
  }

  int _sourceEngineCompatibilityRank(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    final descriptor = _sourceDiagnosticDescriptor(source);
    final container = _containerHintFor(source, descriptor);
    final video = _videoCodecHintFor(descriptor);
    final audio = _audioCodecHintFor(descriptor);
    final hdr = _hdrHintFor(descriptor);
    final strictDeviceCodec = engine == _NativePlaybackEngine.exoplayer;
    var rank = 0;
    if (container == 'hls' || container == 'dash') rank -= 3;
    if (strictDeviceCodec && _isAdaptiveHlsAutoSource(source)) {
      rank += 6;
    }
    if (container == 'mp4') rank -= 2;
    if (strictDeviceCodec &&
        _hasSavedResumeProgressForRoute &&
        !_isLiveTvMode &&
        _isUnknownDirectMp4AutoSource(source)) {
      rank += 8;
    }
    if (container == 'mkv') rank += strictDeviceCodec ? 4 : 2;
    if (container == 'webm' || container == 'avi') rank += 2;
    if (video == 'h264') rank -= 4;
    if (video == 'hevc') rank += strictDeviceCodec ? 5 : 3;
    if (video == 'av1' || video == 'vp9') rank += strictDeviceCodec ? 3 : 2;
    if (hdr == 'dolby-vision') {
      rank += strictDeviceCodec ? 6 : 4;
    } else if (hdr != 'sdr-or-unknown') {
      rank += 3;
    }
    if (audio == 'truehd' || audio == 'dts-hd' || audio == 'dts') {
      rank += strictDeviceCodec ? 4 : 2;
    }
    if (audio == 'eac3' || audio == 'ac3') rank += 1;
    if (_qualityRank(_qualityLabel(source)) >= 2160) rank += 3;
    rank += _media3DirectHlsRouteRiskRank(source, engine);
    return rank;
  }

  int _media3DirectHlsRouteRiskRank(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (!_directHlsRouteRiskGuardsEnabled ||
        engine != _NativePlaybackEngine.exoplayer ||
        source.sourceClass != PlaybackSourceClass.direct ||
        !_isHlsSource(source)) {
      return 0;
    }
    final providerKey = _routeHlsProviderTimeoutKey(source, engine);
    final qualityKey = _routeHlsQualityTimeoutKey(source, engine);
    final providerRendererDrifts =
        _routeHlsProviderRendererDrifts[providerKey] ?? 0;
    final qualityRendererDrifts =
        _routeHlsQualityRendererDrifts[qualityKey] ?? 0;
    if (providerRendererDrifts <= 0 && qualityRendererDrifts <= 0) return 0;
    final qualityRank = _qualityRank(_qualityLabel(source));
    var rank = qualityRendererDrifts * 12;
    if (qualityRank >= 720) {
      rank += providerRendererDrifts * 8;
    }
    return rank;
  }

  void _recordSourceOpenFailure(PlaybackSource source, Object error) {
    final message = error.toString().toLowerCase();
    final unsupportedByDevice = message.contains('no_exceeds_capabilities') ||
        message.contains('mediacodecvideorenderer error') ||
        message.contains('format_supported=no_exceeds_capabilities') ||
        message.contains('error_code_decoding_failed') ||
        message.contains('error_code_decoder_init_failed');
    final highEfficiencyError = message.contains('video/hevc') ||
        message.contains('hvc1') ||
        message.contains('x265') ||
        message.contains('hevc');
    if (!unsupportedByDevice ||
        (!highEfficiencyError && !_looksRiskyForMedia3(source))) {
      return;
    }
    if (_skipUnsupportedHighEfficiencyForSession) return;
    _skipUnsupportedHighEfficiencyForSession = true;
    DiagnosticLog.add(
      'native source capability learned provider=${source.providerId} action=skip high-efficiency sources for session',
    );
  }

  void _recordControllerRuntimeFailureHint(
    _NativePlaybackController controller, {
    required String reason,
  }) {
    if (controller.engine != _NativePlaybackEngine.exoplayer) return;
    final source = _activeSource;
    if (source == null) return;
    final error = controller.errorDescription;
    if (error.trim().isEmpty) return;
    DiagnosticLog.add(
      'native runtime failure hint provider=${source.providerId} engine=${controller.engine.id} reason=$reason',
    );
    _recordSourceOpenFailure(source, error);
  }

  bool _shouldSkipSourceForSession(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (engine == _NativePlaybackEngine.exoplayer &&
        _media3TerminalFailedUrlsForSession.contains(source.url)) {
      DiagnosticLog.add(
        'native source skipped provider=${source.providerId} reason=session media3 terminal failure quality=${_qualityLabel(source)}',
      );
      return true;
    }
    if (engine == _NativePlaybackEngine.exoplayer &&
        _shouldSkipMedia3DirectHlsAfterRendererDrift(source)) {
      return true;
    }
    return engine == _NativePlaybackEngine.exoplayer &&
        _skipUnsupportedHighEfficiencyForSession &&
        _looksRiskyForMedia3(source);
  }

  bool _shouldSkipP2pSourceForEngine(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    return engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.p2p &&
        p2pPlaybackRiskRank(source) >= 9 &&
        _looksHighEfficiencySource(source);
  }

  bool _nativePlaybackSupportsSourceClass(PlaybackSource source) {
    if (source.sourceClass == PlaybackSourceClass.p2p &&
        (_p2pRuntimeUnavailableForRoute || _p2pBridgeBufferingForRoute)) {
      return false;
    }
    return _nativeSourceClassIsPlayable(source);
  }

  void _recordNativeSourceClassSkip(PlaybackSource source) {
    final sourceClass = source.sourceClass.wireName;
    _nativeSourceClassSkipCounts[sourceClass] =
        (_nativeSourceClassSkipCounts[sourceClass] ?? 0) + 1;
  }

  String _nativeSourceClassSkipSummary() {
    if (_nativeSourceClassSkipCounts.isEmpty) return 'none';
    const order = <String>['external', 'p2p', 'unsupported'];
    final parts = <String>[];
    for (final sourceClass in order) {
      final count = _nativeSourceClassSkipCounts[sourceClass] ?? 0;
      if (count <= 0) continue;
      final label = switch (sourceClass) {
        'external' => 'external',
        'p2p' => 'P2P',
        _ => 'unsupported',
      };
      parts.add('$count $label');
    }
    return parts.isEmpty ? 'none' : parts.join(', ');
  }

  bool _looksHighEfficiencySource(PlaybackSource source) {
    final descriptor = _sourceDiagnosticDescriptor(source);
    if (descriptor.contains('hevc') ||
        descriptor.contains('h265') ||
        descriptor.contains('h.265') ||
        descriptor.contains('x265') ||
        descriptor.contains('hvc1') ||
        descriptor.contains('10bit') ||
        descriptor.contains('10-bit')) {
      return true;
    }
    return descriptor.contains('2160p') ||
        descriptor.contains('4k') ||
        _qualityRank(_qualityLabel(source)) >= 2160;
  }

  bool _looksRiskyForMedia3(PlaybackSource source) {
    return _looksHighEfficiencySource(source) ||
        _sourceEngineCompatibilityRank(
              source,
              _NativePlaybackEngine.exoplayer,
            ) >=
            4;
  }

  String _sourceDiagnosticProfile(PlaybackSource source) {
    final descriptor = _sourceDiagnosticDescriptor(source);
    final traits = <String>[
      'quality=${_qualityLabel(source)}',
      'qualityBucket=${_sourceQualityBucketForDiagnostics(source)}',
      'container=${_containerHintFor(source, descriptor)}',
      'video=${_videoCodecHintFor(descriptor)}',
      'audio=${_audioCodecHintFor(descriptor)}',
      'hdr=${_hdrHintFor(descriptor)}',
    ];
    final language = _sourceLanguageLabel(source);
    if (language != null) traits.add('language=$language');
    if (descriptor.contains('atmos')) traits.add('spatial=atmos');
    if (descriptor.contains('dolby')) traits.add('brand=dolby');
    return traits.join(',');
  }

  String _sourceQualityBucketForDiagnostics(PlaybackSource? source) {
    if (source == null) return 'unknown';
    final rank = _qualityRank(_qualityLabel(source));
    if (rank >= 2160) return '4k-or-higher';
    if (rank > 1080) return 'above-1080';
    if (rank >= 1080) return '1080-or-lower';
    if (rank >= 720) return '720';
    if (rank >= 480) return '480';
    if (rank > 0) return 'sub-480';
    return 'unknown';
  }

  String _sourceDiagnosticDescriptor(PlaybackSource source) {
    return '${source.name} ${source.url} ${source.type ?? ''} ${source.quality ?? ''}'
        .toLowerCase();
  }

  String _containerHintFor(PlaybackSource source, String descriptor) {
    final type = (source.type ?? '').toLowerCase();
    if (type == 'hls' || descriptor.contains('.m3u8')) return 'hls';
    if (type == 'dash' || descriptor.contains('.mpd')) return 'dash';
    if (descriptor.contains('.mkv') || descriptor.contains('matroska'))
      return 'mkv';
    if (descriptor.contains('.mp4')) return 'mp4';
    if (descriptor.contains('.webm')) return 'webm';
    if (descriptor.contains('.avi')) return 'avi';
    return type.isEmpty ? 'unknown' : type;
  }

  String _videoCodecHintFor(String descriptor) {
    if (descriptor.contains('av1')) return 'av1';
    if (descriptor.contains('hevc') ||
        descriptor.contains('x265') ||
        descriptor.contains('h265') ||
        descriptor.contains('h.265') ||
        descriptor.contains('hvc1')) {
      return 'hevc';
    }
    if (descriptor.contains('avc') ||
        descriptor.contains('x264') ||
        descriptor.contains('h264') ||
        descriptor.contains('h.264')) {
      return 'h264';
    }
    if (descriptor.contains('vp9')) return 'vp9';
    return 'unknown';
  }

  String _audioCodecHintFor(String descriptor) {
    if (descriptor.contains('truehd')) return 'truehd';
    if (descriptor.contains('dts-hd') || descriptor.contains('dts hd'))
      return 'dts-hd';
    if (descriptor.contains('dts')) return 'dts';
    if (descriptor.contains('ddp') ||
        descriptor.contains('eac3') ||
        descriptor.contains('e-ac3')) {
      return 'eac3';
    }
    if (descriptor.contains('dolby') || descriptor.contains('ac3'))
      return 'ac3';
    if (descriptor.contains('aac')) return 'aac';
    if (descriptor.contains('opus')) return 'opus';
    return 'unknown';
  }

  String _hdrHintFor(String descriptor) {
    if (descriptor.contains('dolby vision') ||
        descriptor.contains('dovi') ||
        descriptor.contains('dv ')) {
      return 'dolby-vision';
    }
    if (descriptor.contains('hdr10+')) return 'hdr10+';
    if (descriptor.contains('hdr10')) return 'hdr10';
    if (descriptor.contains('hdr')) return 'hdr';
    return 'sdr-or-unknown';
  }

  void _startOpeningGuard(
    PlaybackSource source,
    int openingToken,
    Duration timeout,
  ) {
    _openingGuardTimer?.cancel();
    _openingGuardTimer = Timer(timeout, () {
      if (!mounted || !_openingSource || openingToken != _openingSourceToken)
        return;
      final controller = _controller;
      if (controller?.isInitialized == true) return;
      DiagnosticLog.add(
        'native open guard timed out provider=${source.providerId} sourceIndex=$_sourceIndex',
      );
      final resumePosition = _currentPlaybackResumeAnchor();
      _anchorNativeRecoveryProgress(
        resumePosition,
        reason: 'open_guard_timeout',
      );
      _openingSourceToken += 1;
      _openingSource = false;
      _incrementFailedSourceAttempt(source);
      AppState.recordNativeProviderFailure(
        mediaKey: _playbackKey,
        providerId: source.providerId,
        sourceCount: _activeSources.isEmpty
            ? null
            : visiblePlaybackSourceCount(_activeSources),
        updateHealth: _shouldUpdateProviderHealthFromPlaybackFailure,
      );
      unawaited(
        _disposeCurrentController(updateUi: false, awaitLibVlcRelease: true),
      );
      _activeSource = null;
      _sourceIndex += 1;
      final status = _nextSourceStatusFor();
      _pauseActivePlaybackForLoading('open_guard_timeout');
      _logPlaybackStatus(status, reason: 'open_guard_timeout');
      setState(() {
        _loading = true;
        _controlsVisible = true;
        _statusMessage = status;
      });
      unawaited(
        _openNextAvailableSource(resumePositionOverride: resumePosition),
      );
    });
  }

  void _logPlaybackStatus(
    String status, {
    required String reason,
    int? sourceIndex,
  }) {
    DiagnosticLog.add(
      'native playback status reason=$reason providerIndex=$_providerIndex sourceIndex=${sourceIndex ?? _sourceIndex} status="$status"',
    );
  }

  void _updateP2pWarmupStatus({
    required PlaybackSource source,
    required String detail,
    required String label,
  }) {
    if (label != 'preflight' ||
        source.sourceClass != PlaybackSourceClass.p2p ||
        _playerClosing ||
        !mounted) {
      return;
    }
    final status = _p2pWarmupStatusFromDetail(detail);
    if (_statusMessage == status) return;
    _logPlaybackStatus(status, reason: 'p2p_preflight_status');
    setState(() {
      _loading = true;
      _controlsVisible = true;
      _statusMessage = status;
    });
  }

  void _showP2pLocalStreamReadyStatus(PlaybackSource source) {
    if (source.sourceClass != PlaybackSourceClass.p2p ||
        _playerClosing ||
        !mounted) {
      return;
    }
    const status = 'Starting P2P source...\nBuffer is ready. Opening player.';
    _logPlaybackStatus(status, reason: 'p2p_preflight_ready');
    setState(() {
      _loading = true;
      _controlsVisible = true;
      _statusMessage = status;
    });
  }

  String _p2pWarmupStatusFromDetail(String detail) {
    final firstPieces = _p2pBridgeDetailInt(detail, 'firstPiecesReady') ??
        _p2pReadyPieceCount(_p2pBridgeDetailValue(detail, 'firstPieces') ?? '');
    final progressBytes = _p2pBridgeDetailInt(detail, 'fileProgressBytes') ??
        _p2pBridgeDetailInt(detail, 'bufferedBytes') ??
        0;
    if ((firstPieces ?? 0) > 0 || progressBytes > 0) {
      return 'Starting P2P source...\nBuffer is almost ready.';
    }
    final metadataKnown = _p2pBridgeDetailBool(detail, 'metadata') == true;
    if (metadataKnown) {
      return 'Warming P2P source...\nPeers found. Waiting for first video pieces.';
    }
    final peerSignals = (_p2pBridgeDetailInt(detail, 'peers') ?? 0) +
        (_p2pBridgeDetailInt(detail, 'seeds') ?? 0) +
        (_p2pBridgeDetailInt(detail, 'candidates') ?? 0) +
        (_p2pBridgeDetailInt(detail, 'listPeers') ?? 0);
    if (peerSignals > 0) {
      return 'Connecting P2P peers...\nThis can take 20-40 seconds.';
    }
    return 'Finding P2P peers...\nThis can take 20-40 seconds.';
  }

  String _resolveStatusFor(String providerId) {
    return _requests.length <= 1
        ? 'Finding a playable source...'
        : 'Finding playable sources...';
  }

  bool get _shouldUpdateProviderHealthFromPlaybackFailure {
    return _requests.length == 1;
  }

  String _providerProgressLabel(String providerId, {required String prefix}) {
    final total = _requests.length;
    if (total <= 1) {
      return '$prefix - ${_providerLabel(providerId)}';
    }
    final position = total <= 0 ? 0 : (_providerIndex + 1).clamp(1, total);
    return '$prefix $position/$total - ${_providerLabel(providerId)}';
  }

  String _qualityPassStatusFor(List<_QualityPass> passes) {
    if (passes.isEmpty || _qualityPassIndex >= passes.length) {
      return 'All quality options checked.';
    }
    final pass = passes[_qualityPassIndex];
    return 'Preparing ${_loadingStatusQualityLabel(pass.label)} sources ${_qualityPassIndex + 1}/${passes.length}...';
  }

  String _enginePassStatusFor(List<_NativePlaybackEngine> engines) {
    if (engines.isEmpty || _enginePassIndex >= engines.length) {
      return 'All playback engines checked.';
    }
    return engines.length <= 1
        ? 'Opening playback...'
        : 'Trying playback engine ${_enginePassIndex + 1}/${engines.length}...';
  }

  String _nextEngineStatusAfterUnavailable(
    List<_NativePlaybackEngine> engines,
  ) {
    for (var index = _enginePassIndex + 1; index < engines.length; index += 1) {
      final engine = engines[index];
      if (engine == _NativePlaybackEngine.libvlc &&
          _libvlcUnavailableForCurrentPass) {
        continue;
      }
      return engines.length <= 1
          ? 'Opening playback...'
          : 'Trying playback engine ${index + 1}/${engines.length}...';
    }
    return 'All playback engines checked.';
  }

  String _engineLabel(_NativePlaybackEngine engine) {
    return switch (engine) {
      _NativePlaybackEngine.exoplayer => 'Media3',
      _NativePlaybackEngine.libvlc => 'libVLC',
    };
  }

  String _openStatusFor(String providerId) {
    if (_activeSources.isNotEmpty)
      return _checkingSourceStatusFor(_sourceIndex);
    return _resolveStatusFor(providerId);
  }

  String _providerReadyStatusFor(
    String providerId,
    List<PlaybackSource> sources,
  ) {
    final sourceCount = _displaySourceEntries(sources).length;
    final publicIptvProvider = providerId.trim().toLowerCase() == 'public-iptv';
    final sourceLabel = publicIptvProvider
        ? sourceCount == 1
            ? '1 public stream candidate to check'
            : '$sourceCount public stream candidates to check'
        : sourceCount == 1
            ? '1 source'
            : '$sourceCount sources';
    final qualityPasses = _qualityPassesForCurrentAttempt();
    final qualityLabel =
        _qualityPassIndex >= 0 && _qualityPassIndex < qualityPasses.length
            ? _loadingStatusQualityLabel(qualityPasses[_qualityPassIndex].label)
            : null;
    final qualitySuffix = qualityLabel == null ? '' : ' [$qualityLabel]';
    return publicIptvProvider
        ? 'Preparing live TV $sourceLabel$qualitySuffix.'
        : sourceCount == 1
            ? 'Preparing 1 playable source$qualitySuffix.'
            : 'Preparing $sourceCount playable sources$qualitySuffix.';
  }

  String _loadingStatusQualityLabel(String quality) {
    return _displayQualityLabel(quality);
  }

  String _nextSourceStatusFor({bool skipProvider = false}) {
    if (skipProvider) {
      if (_resolverTemporarilyBlocked) {
        return 'Finding sources is taking longer than usual. Try again in a few seconds.';
      }
      final nextProviderIndex = _providerIndex + 1;
      if (nextProviderIndex < _requests.length) {
        final total = _requests.length;
        if (total <= 1) {
          return 'Trying another source...';
        }
        return 'Trying source group ${nextProviderIndex + 1}/$total...';
      }
      return _limitToFirstQualityPass
          ? 'Video is currently unavailable. Sending you back.'
          : "Couldn't open this one. Sending you back.";
    }
    final nextSourceIndex =
        _nextSourceIndexInCurrentVisibleGroup(_activeSources, _sourceIndex) ??
            _nextSourceIndexAfterCurrentVisibleGroup(
              _activeSources,
              _sourceIndex,
            ) ??
            (_sourceIndex + 1);
    return _checkingSourceStatusFor(nextSourceIndex);
  }

  String _checkingSourceStatusFor(int sourceIndex) {
    if (_activeSources.isEmpty ||
        sourceIndex < 0 ||
        sourceIndex >= _activeSources.length) {
      return _nextSourceStatusFor(skipProvider: true);
    }
    final source = _activeSources[sourceIndex];
    final quality = _qualityLabel(source);
    final livePrefix = _isPublicIptvSource(source)
        ? 'Opening live stream'
        : source.sourceClass == PlaybackSourceClass.p2p
            ? 'Opening source'
            : 'Opening source';
    final suffix = source.sourceClass == PlaybackSourceClass.p2p
        ? '\nP2P beta can take 20-40 seconds.'
        : '';
    final groups = _displaySourceEntries(_activeSources);
    final groupIndex = groups.indexWhere(
      (group) => group.variants.any((candidate) => candidate.url == source.url),
    );
    if (groupIndex < 0)
      return '$livePrefix ${sourceIndex + 1}/${_activeSources.length} [$quality]...$suffix';
    final group = groups[groupIndex];
    final mirrorIndex = group.variants.indexWhere(
      (candidate) => candidate.url == source.url,
    );
    if (group.variants.length > 1 && mirrorIndex >= 0) {
      return '$livePrefix ${groupIndex + 1}/${groups.length} - mirror ${mirrorIndex + 1}/${group.variants.length} [$quality]...$suffix';
    }
    return '$livePrefix ${groupIndex + 1}/${groups.length} [$quality]...$suffix';
  }

  String _refreshingSourceStatusFor() {
    final status = _checkingSourceStatusFor(_sourceIndex);
    if (status.startsWith('Checking ')) {
      return status.replaceFirst('Checking ', 'Refreshing ');
    }
    if (status.startsWith('Trying ')) {
      return status.replaceFirst('Trying ', 'Refreshing ');
    }
    if (status.startsWith('Opening ')) {
      return status.replaceFirst('Opening ', 'Refreshing ');
    }
    return 'Refreshing source...';
  }

  Future<void> _closeMobileLibVlcCoordinatorSession(String reason) async {
    final coordinator = _mobileLibVlcCoordinator;
    _mobileLibVlcCoordinator = null;
    _stagedMobileLibVlcTransportMetadata.clear();
    _stagedMobileLibVlcControllers.clear();
    _activeMobileLibVlcSessionTimeline = null;
    _mobileLibVlcSeekAbsoluteFloor = Duration.zero;
    _mobileLibVlcSeekOwnerGeneration = -1;
    _mobileLibVlcCandidateSources = null;
    final transportSubscription = _mobileLibVlcTransportSubscription;
    _mobileLibVlcTransportSubscription = null;
    _mobileLibVlcRelayActive = false;
    await transportSubscription?.cancel();
    if (coordinator == null) return;
    try {
      await coordinator.close().timeout(const Duration(seconds: 4));
      DiagnosticLog.add(
        'native libvlc coordinator closed reason=$reason',
      );
    } catch (error) {
      DiagnosticLog.add(
        'native libvlc coordinator close failed '
        'reason=$reason error=${_safeDiagnosticError(error)}',
      );
    } finally {
      _resetLibVlcContinuousTsProof();
    }
  }

  void _removeStagedMobileLibVlcController(
    int generation, [
    _NativePlaybackController? expected,
  ]) {
    final staged = _stagedMobileLibVlcControllers[generation];
    if (staged == null || (expected != null && !identical(staged, expected))) {
      return;
    }
    _stagedMobileLibVlcControllers.remove(generation);
    if (mounted) setState(() {});
  }

  void _removeStaleMobileLibVlcSeekSurfaces(int ownerGeneration) {
    _stagedMobileLibVlcControllers.removeWhere(
      (generation, _) => generation != ownerGeneration,
    );
    _stagedMobileLibVlcTransportMetadata.removeWhere(
      (key, _) => key.$2 != ownerGeneration,
    );
  }

  Future<void> _disposeCurrentController({
    bool updateUi = true,
    bool awaitLibVlcRelease = false,
    bool saveProgress = true,
  }) async {
    _stopStallWatchdog();
    _cancelDeferredResumeSeek();
    _media3DirectHlsStartupProofPending = false;
    final controller = _controller;
    if (controller == null) {
      await _closeMobileLibVlcCoordinatorSession(
        'controller_missing',
      );
      return;
    }
    if (saveProgress) {
      _trackLastKnownPlaybackPosition();
      _saveNativeProgress(force: true);
    }
    _controller = null;
    _detachControllerUpdateListener(controller);
    final isLibVlc = controller.engine == _NativePlaybackEngine.libvlc;
    final coordinatorOwnsController =
        isLibVlc && _mobileLibVlcCoordinator != null;
    if (!controller.isInitialized) {
      DiagnosticLog.add(
        'native controller pause skipped engine=${controller.engine.id} reason=controller_not_initialized',
      );
    } else if (isLibVlc) {
      final stop = controller.stop().timeout(const Duration(milliseconds: 700));
      if (awaitLibVlcRelease) {
        try {
          await stop;
        } catch (error) {
          DiagnosticLog.add(
            'native libvlc controller stop skipped error=${_safeDiagnosticError(error)}',
          );
        }
      } else {
        unawaited(
          stop.catchError((error) {
            DiagnosticLog.add(
              'native libvlc controller stop skipped error=${_safeDiagnosticError(error)}',
            );
          }),
        );
      }
    } else {
      try {
        await controller.pause().timeout(const Duration(milliseconds: 700));
      } catch (_) {}
    }
    if (mounted && updateUi) {
      setState(() {});
      try {
        await WidgetsBinding.instance.endOfFrame.timeout(
          const Duration(seconds: 1),
        );
        if (isLibVlc) {
          DiagnosticLog.add(
            'native libvlc lifecycle reason=platform_view_unmounted_before_dispose',
          );
        }
      } catch (error) {
        DiagnosticLog.add(
          'native controller unmount frame skipped engine=${controller.engine.id} error=${_safeDiagnosticError(error)}',
        );
      }
    }
    if (isLibVlc && awaitLibVlcRelease) {
      final settle = _libVlcReleaseSettle;
      final preReleaseSettle = settle <= Duration.zero
          ? const Duration(milliseconds: 180)
          : Duration(
              milliseconds: math.min(settle.inMilliseconds, 350).toInt(),
            );
      DiagnosticLog.add(
        'native libvlc pre-release settle delay=${preReleaseSettle.inMilliseconds}ms reason=stop_before_dispose',
      );
      await Future<void>.delayed(preReleaseSettle);
    }
    final releaseStopwatch = Stopwatch()..start();
    final releaseTimeout = isLibVlc && awaitLibVlcRelease
        ? const Duration(seconds: 4)
        : const Duration(seconds: 2);
    final release = coordinatorOwnsController
        ? _closeMobileLibVlcCoordinatorSession(
            'controller_disposed',
          ).timeout(releaseTimeout)
        : controller.dispose().timeout(releaseTimeout);
    if (isLibVlc && !awaitLibVlcRelease && !coordinatorOwnsController) {
      DiagnosticLog.add('native libvlc controller release detached');
      unawaited(
        release.then((_) {
          unawaited(
            DiagnosticLog.clearNativeEngineActive(
              engineId: controller.engine.id,
              reason: 'controller_disposed_detached',
            ),
          );
          DiagnosticLog.add(
            'native controller disposed engine=${controller.engine.id} elapsed=${releaseStopwatch.elapsedMilliseconds}ms detached=true',
          );
        }).catchError((error) {
          DiagnosticLog.add(
            'native controller dispose timed out/failed engine=${controller.engine.id} elapsed=${releaseStopwatch.elapsedMilliseconds}ms error=${_safeDiagnosticError(error)}',
          );
        }),
      );
    } else {
      try {
        await release;
        if (isLibVlc) {
          unawaited(
            DiagnosticLog.clearNativeEngineActive(
              engineId: controller.engine.id,
              reason: 'controller_disposed',
            ),
          );
        }
        DiagnosticLog.add(
          'native controller disposed engine=${controller.engine.id} elapsed=${releaseStopwatch.elapsedMilliseconds}ms detached=false',
        );
      } catch (error) {
        DiagnosticLog.add(
          'native controller dispose timed out/failed engine=${controller.engine.id} elapsed=${releaseStopwatch.elapsedMilliseconds}ms error=${_safeDiagnosticError(error)}',
        );
      }
    }
    _activeSourceHasZeroClockMetadata = false;
    _nativeWallClockStartedAt = null;
    _lastSavedSecond = -1;
    _resetPlaybackIntegritySample();
    final stopRelay = _stopLibVlcHlsRelay('controller_disposed');
    if (isLibVlc && !awaitLibVlcRelease) {
      unawaited(stopRelay);
    } else {
      await stopRelay;
    }
  }

  bool _detachLibVlcControllerForAsyncRelease(String reason) {
    final controller = _controller;
    if (controller == null ||
        controller.engine != _NativePlaybackEngine.libvlc) {
      return false;
    }
    _stopStallWatchdog();
    _cancelDeferredResumeSeek();
    _controller = null;
    _detachControllerUpdateListener(controller);
    _activeSourceHasZeroClockMetadata = false;
    _nativeWallClockStartedAt = null;
    _lastSavedSecond = -1;
    _resetPlaybackIntegritySample();
    DiagnosticLog.add(
      'native libvlc controller detached before native release reason=$reason',
    );
    unawaited(
      _stopLibVlcHlsRelay('${reason}_detached').then((_) async {
        await Future<void>.delayed(const Duration(milliseconds: 350));
        final releaseStopwatch = Stopwatch()..start();
        try {
          await controller.dispose().timeout(const Duration(seconds: 2));
          unawaited(
            DiagnosticLog.clearNativeEngineActive(
              engineId: controller.engine.id,
              reason: 'controller_disposed_detached_$reason',
            ),
          );
          DiagnosticLog.add(
            'native controller disposed engine=${controller.engine.id} elapsed=${releaseStopwatch.elapsedMilliseconds}ms detached=true reason=$reason',
          );
        } catch (error) {
          DiagnosticLog.add(
            'native controller dispose timed out/failed engine=${controller.engine.id} elapsed=${releaseStopwatch.elapsedMilliseconds}ms detached=true reason=$reason error=${_safeDiagnosticError(error)}',
          );
        }
      }).catchError((error) {
        DiagnosticLog.add(
          'native libvlc detached cleanup failed reason=$reason error=${_safeDiagnosticError(error)}',
        );
      }),
    );
    return true;
  }

  Future<void> _stopLibVlcHlsRelay(String reason) async {
    _libVlcHlsRelayGeneration += 1;
    final relay = _libVlcHlsRelay;
    if (relay == null) return;
    _libVlcHlsRelay = null;
    _resetLibVlcContinuousTsProof();
    final summary = relay.summary;
    try {
      await relay.stop();
      DiagnosticLog.add(
        'native libvlc hls relay stopped reason=$reason $summary',
      );
    } catch (error) {
      DiagnosticLog.add(
        'native libvlc hls relay stop failed reason=$reason error=${_safeDiagnosticError(error)}',
      );
    }
  }

  void _resetLibVlcContinuousTsProof({
    bool preserveSeekSettlement = false,
  }) {
    if (!preserveSeekSettlement) {
      _libVlcSeekSettlementBarrier.clear();
      _libVlcSeekSettlementLoggedGeneration = -1;
    }
    _libVlcContinuousTsDurationAccepted = false;
    _libVlcContinuousTsStartupLeadReady = false;
    _libVlcContinuousTsStreamedSegments = 0;
    _libVlcContinuousTsStreamedBytes = 0;
    _libVlcContinuousTsBufferedPosition = Duration.zero;
    _libVlcContinuousTsLastTransportActivityAt = null;
    _libVlcContinuousTsUpstreamErrors = 0;
    _libVlcContinuousTsLastStatusBucket = 'none';
    _libVlcContinuousTsTimelineOffset = Duration.zero;
  }

  void _maybeClearLibVlcContinuousTsWaitMessage({required String reason}) {
    if (!_libVlcContinuousTsRelayProofReady) return;
    final message = _playbackWaitMessage;
    if (message != 'Getting stream details...' &&
        message != 'Resuming playback...' &&
        message != 'Buffering stream...') {
      return;
    }
    DiagnosticLog.add(
      'native libvlc continuous-ts relay proof accepted reason=$reason streamed=${_countDiagnosticBucket(_libVlcContinuousTsStreamedSegments)} bytes=$_libVlcContinuousTsStreamedBytes durationKnown=$_libVlcContinuousTsDurationAccepted',
    );
    _clearPlaybackWaitMessage(reason: reason);
  }

  bool _bufferingWaitMessageReady(int ticks, int recoveryTickLimit) {
    final visibleGraceTicks = math.min(3, math.max(1, recoveryTickLimit - 1));
    return ticks >= visibleGraceTicks;
  }

  void _clearTransientBufferingWaitMessage({required String reason}) {
    if (_playbackWaitMessage != 'Buffering stream...') return;
    _clearPlaybackWaitMessage(reason: reason);
  }

  Future<void> _loadPipSupport() async {
    try {
      final supported =
          await _pipChannel.invokeMethod<bool>('isSupported') ?? false;
      if (mounted) setState(() => _pipSupported = supported);
      if (supported) unawaited(_syncAndroidAutoPipOnUserLeave());
      DiagnosticLog.add('native system PiP supported=$supported');
    } catch (_) {
      if (mounted) setState(() => _pipSupported = false);
      DiagnosticLog.add('native system PiP support check failed');
    }
  }

  Future<dynamic> _handlePipChannelCall(MethodCall call) async {
    if (call.method == 'prepareForSystemPip') {
      _prepareForSystemPip();
      return null;
    }
    if (call.method == 'enteredSystemPip') {
      DiagnosticLog.add('native system PiP entered');
      _pictureInPictureActive = true;
      return null;
    }
    if (call.method == 'exitedSystemPip') {
      DiagnosticLog.add('native system PiP exited');
      _pictureInPictureActive = false;
      _systemPipHandoffActive = false;
      if (mounted) setState(() {});
      return null;
    }
    if (call.method != 'action') return null;
    final action = call.arguments?.toString();
    DiagnosticLog.add('native pip action=$action');
    switch (action) {
      case 'skipBack':
        if (_isLiveTvMode) break;
        await _seekBy(Duration(seconds: -_seekStepSeconds.round()));
        break;
      case 'playPause':
        _togglePlayback(ignoreOptionSheet: true);
        await _syncPipActions();
        break;
      case 'skipForward':
        if (_isLiveTvMode) break;
        await _seekBy(Duration(seconds: _seekStepSeconds.round()));
        break;
      case 'fullscreen':
        if (!mounted) return null;
        setState(() {
          _pictureInPictureActive = false;
          _optionSheetOpen = false;
          _controlsVisible = true;
        });
        break;
      case 'close':
        await _requestClose();
        break;
    }
    return null;
  }

  Future<void> _syncPipActions() async {
    if (!_pictureInPictureActive || !_pipSupported) return;
    try {
      await _pipChannel.invokeMethod<void>('updateActions', {
        'playing': _controller?.isPlaying == true,
        'seekSeconds': _seekStepSeconds.round(),
        'liveMode': _isLiveTvMode,
      });
    } catch (error) {
      DiagnosticLog.add(
        'native pip action sync failed error=${_safeDiagnosticError(error)}',
      );
    }
  }

  void _restoreNativePreferences() {
    _usingGlobalOverrides = false;
    _settingsExpanded = false;
    _settingsPausedPlayback = false;
    final item = _progressItem;
    final key = _playbackKey;
    final prefs = item == null || key == null
        ? null
        : AppState.progressFor(item, playbackKey: key)?.nativePreferences;
    if (prefs != null) {
      _hasRestoredNativePreferences = true;
      final restoredQuality = prefs.quality?.trim() ?? '';
      final normalizedQuality = _normalizeSavedQuality(restoredQuality);
      _preferredQuality =
          normalizedQuality.isEmpty || normalizedQuality.toLowerCase() == 'auto'
              ? null
              : normalizedQuality;
      _qualityPreferenceMode =
          _preferredQuality == null ? 'recommended' : 'advanced';
      _playbackSpeed = prefs.speed;
      _preferredSubtitleId = prefs.subtitleId;
      _subtitleDelaySeconds = prefs.subtitleDelaySeconds;
      _subtitleDelayCustomized = prefs.subtitleDelayCustomized;
      _subtitleFontSize = prefs.subtitleFontSize;
      _subtitleBackgroundOpacity = prefs.subtitleBackgroundOpacity;
      _subtitleBackgroundColor = Color(prefs.subtitleBackgroundColor);
      _subtitleBackgroundRadius = prefs.subtitleBackgroundRadius;
      _subtitleTextColor = Color(prefs.subtitleTextColor);
      _subtitleBottomOffset = prefs.subtitleBottomOffset;
      _fitMode = VideoFitMode.fromName(prefs.videoFitMode);
      DiagnosticLog.add(
        'native preferences restored key=[redacted] qualityMode=${_preferredQuality == null ? 'auto' : 'saved'} speedSaved=${prefs.speed != 1} fitSaved=${_fitMode != VideoFitMode.fit}',
      );
    }

    if (AppState.nativePlaybackOverridesEnabled.value) {
      _usingGlobalOverrides = true;
      final overrides = AppState.nativePlaybackOverrides.value;
      _qualityPreferenceMode = overrides.qualityMode;
      _preferredQuality = overrides.qualityMode == 'advanced'
          ? _normalizeSavedQuality(overrides.advancedQuality)
          : null;
      _seekStepSeconds = overrides.seekStepSeconds;
      _playbackSpeed = overrides.speed;
      if (!_subtitleDelayCustomized) {
        _subtitleDelaySeconds = overrides.subtitleDelaySeconds;
      }
      _subtitleFontSize = overrides.subtitleFontSize;
      _subtitleBackgroundOpacity = overrides.subtitleBackgroundOpacity;
      _subtitleBackgroundColor = Color(overrides.subtitleBackgroundColor);
      _subtitleBackgroundRadius = overrides.subtitleBackgroundRadius;
      _subtitleTextColor = Color(overrides.subtitleTextColor);
      _subtitleBottomOffset = overrides.subtitleBottomOffset;
      _fitMode = VideoFitMode.fromName(overrides.videoFitMode);
      DiagnosticLog.add(
        'native overrides applied qualityMode=${overrides.qualityMode} advancedQuality=${overrides.advancedQuality} normalized=${_preferredQuality ?? 'Auto'} seek=${overrides.seekStepSeconds} fit=${_fitMode.name}',
      );
    }
    if (_batterySaverPlaybackActive && _qualityPreferenceMode != 'dataSaver') {
      _usingGlobalOverrides = true;
      _qualityPreferenceMode = 'dataSaver';
      _preferredQuality = null;
      DiagnosticLog.add(
        'native battery data policy applied playbackQuality=dataSaver',
      );
    }
  }

  void _restoreNativeSurfaceLevels() {
    _volumePreview =
        AppState.nativePlayerVolume.value.clamp(0.0, 1.0).toDouble();
    _brightnessPreview =
        AppState.nativePlayerBrightness.value.clamp(0.0, 1.0).toDouble();
    _displayChannel.invokeMethod<void>(
        'setBrightness', {'value': _brightnessPreview}).catchError((_) {});
  }

  String _normalizeSavedQuality(String quality) {
    return _displayQualityLabel(quality);
  }

  void _ensureSubtitlesLoading() {
    if (_subtitlesLoadStarted) return;
    _subtitlesLoadStarted = true;
    unawaited(_loadSubtitles());
  }

  Future<void> _loadSubtitles() async {
    final resolver = _resolveSubtitles;
    if (_playerClosing) return;
    final seededSubtitles = _subtitles;
    List<PlaybackSubtitle> resolvedSubtitles = const <PlaybackSubtitle>[];
    if (resolver != null) {
      try {
        resolvedSubtitles = await resolver();
      } catch (error) {
        DiagnosticLog.add(
          'native subtitles resolver failed error=${_safeDiagnosticError(error)}',
        );
      }
    }
    if (!mounted || _playerClosing) return;
    final subtitles = _mergePlaybackSubtitles(
      seededSubtitles,
      resolvedSubtitles,
    );
    if (subtitles.isEmpty) {
      setState(() {
        _subtitles = const <PlaybackSubtitle>[];
      });
      return;
    }
    final behavior = AppState.playerBehaviorSettings.value;
    final autoSelect = behavior.subtitleAutoSelect;
    PlaybackSubtitle? preferredSubtitle;
    if (autoSelect != 'off' &&
        (autoSelect == 'last' || _hasRestoredNativePreferences) &&
        _preferredSubtitleId != null) {
      for (final subtitle in subtitles) {
        if (subtitle.id == _preferredSubtitleId) {
          preferredSubtitle = subtitle;
          break;
        }
      }
    }
    if (preferredSubtitle == null && autoSelect == 'forced') {
      for (final subtitle in subtitles) {
        if (subtitle.isForced) {
          preferredSubtitle = subtitle;
          break;
        }
      }
    }
    if (preferredSubtitle == null && autoSelect == 'default') {
      final preferredLanguage = behavior.subtitleLanguage.toLowerCase();
      for (final subtitle in subtitles) {
        final language = subtitle.language.toLowerCase();
        if (subtitle.isDefault ||
            preferredLanguage == 'auto' ||
            (preferredLanguage == 'en' && language == 'english') ||
            (preferredLanguage == 'es' && language == 'spanish') ||
            (preferredLanguage == 'fr' && language == 'french') ||
            (preferredLanguage == 'de' && language == 'german') ||
            (preferredLanguage == 'pt' && language == 'portuguese') ||
            language == preferredLanguage ||
            language.startsWith('$preferredLanguage-')) {
          preferredSubtitle = subtitle;
          break;
        }
      }
    }
    setState(() {
      _subtitles = subtitles;
    });
    if (preferredSubtitle != null && autoSelect != 'off') {
      await _selectSubtitle(preferredSubtitle);
    }
  }

  List<PlaybackSubtitle> _mergePlaybackSubtitles(
    List<PlaybackSubtitle> seeded,
    List<PlaybackSubtitle> resolved,
  ) {
    final seen = <String>{};
    final merged = <PlaybackSubtitle>[];
    for (final subtitle in [...seeded, ...resolved]) {
      final key =
          subtitle.url.trim().isNotEmpty ? subtitle.url.trim() : subtitle.id;
      if (key.trim().isEmpty || !seen.add(key)) continue;
      merged.add(subtitle);
    }
    return merged;
  }

  void _attachControllerUpdateListener(_NativePlaybackController controller) {
    _detachControllerUpdateListener(controller);
    final callbackGeneration = _controllerCallbackGeneration;
    void listener() {
      if (!identical(_controller, controller) ||
          !_terminalCallbackGate.permits(callbackGeneration)) {
        widget.lifecycleHarness?.recordCallback(accepted: false);
        return;
      }
      widget.lifecycleHarness?.recordCallback(accepted: true);
      _handleControllerUpdate();
    }

    _controllerUpdateListeners[controller] = listener;
    controller.addListener(listener);
    widget.lifecycleHarness?.recordAttach();
  }

  void _detachControllerUpdateListener(_NativePlaybackController controller) {
    final listener = _controllerUpdateListeners.remove(controller);
    if (listener != null) {
      controller.removeListener(listener);
      widget.lifecycleHarness?.recordDetach();
      return;
    }
    controller.removeListener(_handleControllerUpdate);
  }

  void _handleControllerUpdate() {
    if (_playerClosing ||
        _terminalOpeningCallbackQuarantined ||
        !_terminalCallbackGate.permits(_controllerCallbackGeneration)) {
      return;
    }
    final controller = _controller;
    if (controller != null &&
        controller.hasError &&
        !_openingSource &&
        !_recoveringFromStall) {
      if (!AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
        DiagnosticLog.add(
          'native playback error detected but auto-switch on stall is disabled',
        );
        return;
      }
      if (_shouldDeferControllerErrorRecovery(controller, reason: 'listener')) {
        return;
      }
      final recoveryPosition = _effectiveRecoveryPosition(controller.position);
      if (_controllerErrorRecoveryAlreadyQueued(
        controller,
        recoveryPosition: recoveryPosition,
        reason: 'listener',
      )) {
        return;
      }
      final shouldRepairAtAnchor = _shouldRepairExoControllerErrorAtAnchor(
        controller,
        recoveryPosition,
      );
      DiagnosticLog.add(
        'native playback error listener provider=${_activeSource?.providerId} reportedPosition=${controller.position.inSeconds}s recoveryPosition=${recoveryPosition.inSeconds}s action=${shouldRepairAtAnchor ? 'repair_exoplayer_at_anchor' : 'failover_source'} error=${controller.errorDescription}',
      );
      if (shouldRepairAtAnchor) {
        final source = _activeSource;
        _anchorNativeRecoveryProgress(
          recoveryPosition,
          reason: 'listener_exoplayer_anchor_repair',
        );
        if (source != null) {
          _scheduleDeferredResumeSeek(
            recoveryPosition,
            source.providerId,
            controller,
          );
        }
      } else {
        _recordControllerRuntimeFailureHint(controller, reason: 'listener');
      }
      unawaited(
        _recoverFromPlaybackStall(
          recoveryPosition,
          skipSameSource: !shouldRepairAtAnchor,
          skipProvider: !shouldRepairAtAnchor,
        ),
      );
      return;
    }
    if (controller != null && _resumeStartupSeekProofPending(controller)) {
      _syncKeepScreenOn();
      _maybeRecordDeferredLibVlcOpenSuccess(
        controller,
        reason: 'controller_update_resume_seek_pending',
      );
      return;
    }
    _clearControllerErrorGrace();
    _syncKeepScreenOn();
    if (controller != null) {
      _syncPlaybackIntegrity(controller);
    }
    _trackLastKnownPlaybackPosition();
    if (controller != null) {
      _maybeRecordDeferredLibVlcOpenSuccess(
        controller,
        reason: 'controller_update_visual_proof',
      );
    }
    _saveNativeProgress();
    if (controller != null) {
      _maybeAutoSkipSegment(controller);
      _maybeAutoplayNextEpisode(controller);
      _maybeCloseWhenPlaybackCompleted(controller);
      _ensureControlsAutoHide(reason: 'controller_update_playing');
    }
    final subtitleChanged = _syncSubtitleText();
    if (mounted && _shouldRebuildForControllerUpdate(subtitleChanged)) {
      _lastControllerUiRebuildAt = DateTime.now();
      setState(() {});
    }
  }

  bool _shouldRebuildForControllerUpdate(bool subtitleChanged) {
    if (subtitleChanged) return true;
    final controller = _controller;
    if (controller == null || !controller.isInitialized) return true;
    final now = DateTime.now();
    final previous = _lastControllerUiRebuildAt;
    final visibleUi = _controlsVisible ||
        _settingsExpanded ||
        _optionSheetOpen ||
        _loading ||
        _playbackWaitMessage != null ||
        controller.isBuffering;
    final interval = visibleUi
        ? const Duration(milliseconds: 500)
        : const Duration(seconds: 2);
    return previous == null || now.difference(previous) >= interval;
  }

  void _maybeAutoSkipSegment(_NativePlaybackController controller) {
    if (!AppState.playerBehaviorSettings.value.autoSkipSegments ||
        _locked ||
        _loading ||
        _openingSource ||
        _recoveringFromStall ||
        _optionSheetOpen ||
        _settingsExpanded ||
        !controller.isInitialized ||
        !controller.isPlaying ||
        controller.duration <= Duration.zero) {
      return;
    }
    final segment = _activeSkipSegment(
      controller.position,
      controller.duration,
      allowFallback: false,
    );
    if (segment == null ||
        segment.target <= controller.position + const Duration(seconds: 1)) {
      return;
    }
    final key = '${segment.label}:${segment.target.inSeconds}';
    if (!_autoSkippedSegmentKeys.add(key)) return;
    DiagnosticLog.add(
      'native auto skip segment applied label=${segment.label}',
    );
    unawaited(_skipToSegment(segment, automatic: true));
  }

  void _maybeAutoplayNextEpisode(_NativePlaybackController controller) {
    if (!_shouldAutoplayNextEpisodeAtTail(controller)) return;
    final remaining = controller.duration - controller.position;
    final reason = remaining <= const Duration(seconds: 2)
        ? 'ended_window'
        : 'tail_window';
    _triggerAutoplayNextEpisode(controller, reason: reason);
  }

  bool _shouldAutoplayNextEpisodeAtTail(
    _NativePlaybackController controller, {
    Duration? positionOverride,
  }) {
    if (_autoNextEpisodeStarted ||
        _nextEpisodeOpening ||
        !AppState.playerBehaviorSettings.value.autoplayNextEpisode ||
        _nextEpisodeResolver == null ||
        !controller.isInitialized ||
        controller.duration <= Duration.zero) {
      return false;
    }
    final duration = controller.duration;
    final rawPosition = positionOverride ?? controller.position;
    final position = _stableProgressClockPosition(
      rawPosition,
      reason: 'autoplay_next_episode_tail',
    );
    if (position < const Duration(seconds: 3)) return false;
    final remaining = duration - position;
    if (remaining <= const Duration(seconds: 2)) return true;
    if (remaining > _autoplayNextEpisodeTailWindow) return false;
    final progress = position.inMilliseconds / duration.inMilliseconds;
    return progress >= _autoplayNextEpisodeTailProgressRatio;
  }

  void _triggerAutoplayNextEpisode(
    _NativePlaybackController controller, {
    required String reason,
    Duration? positionOverride,
  }) {
    final duration = controller.duration;
    final position = _stableProgressClockPosition(
      positionOverride ?? controller.position,
      reason: 'autoplay_next_episode_trigger',
    );
    final remaining = duration - position;
    _autoNextEpisodeStarted = true;
    DiagnosticLog.add(
      'native autoplay next episode triggered reason=$reason position=${position.inSeconds}s duration=${duration.inSeconds}s remaining=${remaining.inSeconds}s',
    );
    unawaited(_openNextEpisodeInPlace());
  }

  bool _shouldCompletePlaybackAtTail(
    _NativePlaybackController controller, {
    Duration? positionOverride,
  }) {
    if (!controller.isInitialized || controller.duration <= Duration.zero) {
      return false;
    }
    final duration = controller.duration;
    final position = _stableProgressClockPosition(
      positionOverride ?? controller.position,
      reason: 'completion_tail',
    );
    if (position < const Duration(seconds: 3)) return false;
    final remaining = duration - position;
    final progress = position.inMilliseconds / duration.inMilliseconds;
    final terminalStop = controller.isEnded ||
        (!controller.isPlaying && !controller.isBuffering);
    final terminalTail =
        remaining <= const Duration(seconds: 2) && progress >= 0.985;
    return terminalStop && terminalTail;
  }

  void _completeNativePlayback(
    _NativePlaybackController controller, {
    required String reason,
    Duration? positionOverride,
  }) {
    if (_completionCloseStarted || _playerClosing) return;
    final duration = controller.duration;
    final position = _stableProgressClockPosition(
      positionOverride ?? controller.position,
      reason: 'completion_close',
    );
    _completionCloseStarted = true;
    _resumePromptHandled = true;
    _resumePromptAccepted = false;
    DiagnosticLog.add(
      'native playback completed; closing player reason=$reason position=${position.inSeconds}s duration=${duration.inSeconds}s',
    );
    _sendPlaybackFeedback('completed');
    _saveNativeProgress(force: true, completionObserved: true);
    unawaited(_close('completed'));
  }

  void _maybeCloseWhenPlaybackCompleted(_NativePlaybackController controller) {
    if (_completionCloseStarted ||
        _playerClosing ||
        _openingSource ||
        _recoveringFromStall ||
        _activeSourceHasZeroClockMetadata ||
        !controller.isInitialized ||
        controller.duration <= Duration.zero) {
      return;
    }
    if (_nextEpisodeResolver != null &&
        AppState.playerBehaviorSettings.value.autoplayNextEpisode &&
        _autoNextEpisodeStarted) {
      return;
    }
    final duration = controller.duration;
    final rawPosition = controller.position;
    final position = _stableProgressClockPosition(
      rawPosition,
      reason: 'completion_close',
    );
    final heldSuspiciousClock =
        rawPosition - position > const Duration(seconds: 2);
    final tailCompletion = _shouldCompletePlaybackAtTail(
      controller,
      positionOverride: position,
    );
    if (_playbackCadenceClockUnstable && !tailCompletion) {
      DiagnosticLog.add(
        'native completion held reason=unstable_playback_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s duration=${duration.inSeconds}s',
      );
      return;
    }
    if (heldSuspiciousClock && !tailCompletion) {
      DiagnosticLog.add(
        'native completion held reason=suspicious_player_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s duration=${duration.inSeconds}s',
      );
      return;
    }
    if (position < const Duration(seconds: 3)) return;
    final remaining = duration - position;
    final nearEnd = remaining <= const Duration(milliseconds: 1200) &&
        position.inMilliseconds / duration.inMilliseconds >= 0.985;
    if (!controller.isEnded && !nearEnd && !tailCompletion) return;
    _completeNativePlayback(
      controller,
      reason: tailCompletion ? 'terminal_tail' : 'normal',
      positionOverride: position,
    );
  }

  void _startStallWatchdog() {
    if (_playerClosing) return;
    _stopStallWatchdog();
    if (_controller?.engine == _NativePlaybackEngine.libvlc &&
        _mobileLibVlcCoordinator != null) {
      return;
    }
    _lastWatchdogPosition = _controller?.position ?? Duration.zero;
    _stallWatchdogTicks = 0;
    _blackVideoWatchdogTicks = 0;
    _bufferingWatchdogTicks = 0;
    _resetMedia3PersistentBufferingStreak(reason: 'start_watchdog');
    _resetTransientPlaybackDebounce();
    _stallWatchdogTimer = Timer.periodic(
      _stallWatchdogInterval,
      (_) => _checkPlaybackStall(),
    );
    _startPlaybackCadenceSampler();
  }

  void _stopStallWatchdog() {
    _stallWatchdogTimer?.cancel();
    _stallWatchdogTimer = null;
    _stopPlaybackCadenceSampler();
    _stallWatchdogTicks = 0;
    _deadPauseTicks = 0;
    _blackVideoWatchdogTicks = 0;
    _bufferingWatchdogTicks = 0;
    _resetMedia3PersistentBufferingStreak(reason: 'stop_watchdog');
    _resetTransientPlaybackDebounce();
  }

  void _resetTransientPlaybackDebounce() {
    _noProgressFirstSeenAt = null;
    _noProgressFirstSeenPosition = Duration.zero;
    _deadPauseFirstSeenAt = null;
  }

  void _startPlaybackCadenceSampler() {
    _stopPlaybackCadenceSampler();
    _lastCadencePosition = _controller?.position ?? Duration.zero;
    _lastCadenceSampleAt = DateTime.now();
    _playbackCadenceSamples = 0;
    _resetPlaybackCadenceCorrection();
    _playbackCadenceTimer = Timer.periodic(
      const Duration(seconds: 1),
      (_) => _samplePlaybackCadence(),
    );
  }

  void _stopPlaybackCadenceSampler() {
    _playbackCadenceTimer?.cancel();
    _playbackCadenceTimer = null;
    _lastCadenceSampleAt = null;
    _playbackCadenceSamples = 0;
    _resetPlaybackCadenceCorrection();
  }

  void _resetPlaybackCadenceCorrection() {
    _playbackCadenceJumpEvents = 0;
    _playbackCadenceConsecutiveJumpEvents = 0;
    _playbackCadenceHealthySamples = 0;
    _playbackCadenceUnstableEvents = 0;
    _playbackCadenceClockUnstable = false;
    _lastPlaybackCadenceDriftHoldAt = null;
    _lastPlaybackCadenceDriftObservationLogAt = null;
    _playbackCadenceUnstableWindowStartedAt = null;
    _media3RendererDriftHoldSourceKey = null;
    _media3RendererDriftHoldCountForSource = 0;
    _media3DirectHlsRendererDriftHoldCount = 0;
    _unstableClockProgressSkipLogSecond = -1;
  }

  void _recordPlaybackCadenceUnstableEvent(DateTime now) {
    final startedAt = _playbackCadenceUnstableWindowStartedAt;
    if (startedAt == null ||
        now.difference(startedAt) > const Duration(seconds: 45)) {
      _playbackCadenceUnstableWindowStartedAt = now;
      _playbackCadenceUnstableEvents = 1;
    } else {
      _playbackCadenceUnstableEvents += 1;
    }
    _playbackCadenceClockUnstable = true;
  }

  void _clearPlaybackCadenceUnstableState() {
    _playbackCadenceJumpEvents = 0;
    _playbackCadenceConsecutiveJumpEvents = 0;
    _playbackCadenceUnstableEvents = 0;
    _playbackCadenceClockUnstable = false;
    _playbackCadenceUnstableWindowStartedAt = null;
    _unstableClockProgressSkipLogSecond = -1;
    _media3RendererDriftRepairSourceKey = null;
    _media3RendererDriftRepairCountForSource = 0;
    _media3RendererDriftHoldSourceKey = null;
    _media3RendererDriftHoldCountForSource = 0;
  }

  String _playbackSourceRuntimeKey(PlaybackSource source) {
    return <String>[
      source.providerId,
      source.sourceClass.wireName,
      source.quality ?? '',
      source.url,
    ].join('|');
  }

  void _clearMedia3RecoveryQualityCeiling({required String reason}) {
    if (_media3RecoveryQualityCeilingRank == null) return;
    DiagnosticLog.add(
      'native media3 recovery quality ceiling cleared rank=$_media3RecoveryQualityCeilingRank reason=$reason',
    );
    _media3RecoveryQualityCeilingRank = null;
    _media3RecoveryQualityCeilingSetAt = null;
    _media3RecoveryQualityCeilingReason = null;
  }

  int _media3RecoveryQualityCeilingFor(
    _NativePlaybackController controller,
    PlaybackSource source,
  ) {
    final ranks = <int>[];
    final labelRank = _qualityRank(_qualityLabel(source));
    if (labelRank > 0) ranks.add(labelRank);
    final height = controller.size.height.toInt();
    if (height > 0) {
      final heightRank = _qualityRank(
        '${_normalizedPlaybackQualityHeight(height)}P',
      );
      if (heightRank > 0) ranks.add(heightRank);
    }
    if (ranks.isEmpty) return 0;
    return ranks.reduce(math.min);
  }

  void _armMedia3RecoveryQualityCeiling(
    _NativePlaybackController controller,
    PlaybackSource source, {
    required String reason,
  }) {
    if (controller.engine != _NativePlaybackEngine.exoplayer) return;
    if (!_isHlsSource(source)) return;
    final ceilingRank = _media3RecoveryQualityCeilingFor(controller, source);
    if (ceilingRank <= 0) return;
    final currentRank = _media3RecoveryQualityCeilingRank;
    if (currentRank != null && currentRank <= ceilingRank) return;
    _media3RecoveryQualityCeilingRank = ceilingRank;
    _media3RecoveryQualityCeilingSetAt = DateTime.now();
    _media3RecoveryQualityCeilingReason = reason;
    DiagnosticLog.add(
      'native media3 recovery quality ceiling armed provider=${source.providerId} rank=$ceilingRank reason=$reason',
    );
  }

  void _resetMedia3PersistentBufferingStreak({String? reason}) {
    if (_media3PersistentBufferingStreakTicks > 0 && reason != null) {
      DiagnosticLog.add(
        'native media3 persistent buffering streak reset provider=${_activeSource?.providerId} reason=$reason ticks=$_media3PersistentBufferingStreakTicks healthy=$_media3PersistentBufferingHealthySamples',
      );
    }
    if (_media3PersistentBufferingStreakTicks > 0 &&
        _media3PersistentBufferingSourceKey != null) {
      _lastMedia3PersistentBufferingSourceKey =
          _media3PersistentBufferingSourceKey;
      _lastMedia3PersistentBufferingSeenAt = DateTime.now();
      _lastMedia3PersistentBufferingTicks =
          _media3PersistentBufferingStreakTicks;
    }
    _media3PersistentBufferingStreakTicks = 0;
    _media3PersistentBufferingHealthySamples = 0;
    _media3PersistentBufferingLastHealthyPosition = Duration.zero;
    _media3PersistentBufferingSourceKey = null;
    if (reason == 'credible_playback_recovered') {
      _clearPlaybackWaitMessage(reason: reason!);
      _clearMedia3RecoveryQualityCeiling(reason: reason!);
    }
  }

  bool _hadRecentMedia3PersistentBufferingForSource(
    PlaybackSource source, {
    int minimumTicks = 4,
  }) {
    final seenAt = _lastMedia3PersistentBufferingSeenAt;
    if (seenAt == null) return false;
    if (DateTime.now().difference(seenAt) > const Duration(seconds: 30)) {
      return false;
    }
    return _lastMedia3PersistentBufferingSourceKey ==
            _playbackSourceRuntimeKey(source) &&
        _lastMedia3PersistentBufferingTicks >= minimumTicks;
  }

  bool _isMedia3PersistentBufferingCandidate(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (!controller.isInitialized ||
        !controller.isBuffering ||
        controller.hasError ||
        controller.duration <= Duration.zero ||
        controller.size == Size.zero ||
        _activeSourceHasZeroClockMetadata) {
      return false;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    return _activeSourceVerifiedForSession ||
        _sourceHasRawVisualPlaybackProof(controller) ||
        _sourceHasVisualPlaybackProof(controller) ||
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
        _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
        _lastSavedSecond >= 5;
  }

  bool _media3HasCurrentSessionBufferingHoldProof(
    _NativePlaybackController controller,
    PlaybackSource? source,
  ) {
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (!controller.isInitialized ||
        controller.hasError ||
        controller.duration <= Duration.zero ||
        controller.size == Size.zero ||
        _activeSourceHasZeroClockMetadata) {
      return false;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return true;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (!controller.hasRenderedVideoFrame) return false;
    if (_media3HasSustainedVisualCadenceProof(controller)) return true;
    return _sourceHasRawVisualPlaybackProof(controller) ||
        _sourceHasVisualPlaybackProof(controller);
  }

  bool _media3HasPersistentBufferingHoldProof(
    _NativePlaybackController controller,
    PlaybackSource? source,
  ) {
    if (!_media3HasCurrentSessionBufferingHoldProof(controller, source)) {
      return false;
    }
    if (source == null) return false;
    if (source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _media3PersistentBufferingStreakTicks > 0) {
      final proofMinimum = _verifiedSourcePlaybackProofMinimum(
        source,
        publicIptvSource: _isPublicIptvSource(source),
      );
      final hasSustainedCadence = _playbackCadenceHealthySamples >= 4 &&
          !_playbackCadenceClockUnstable &&
          _sourceCredibleWatchSeconds >= proofMinimum.inSeconds;
      final hasRecoveredFromCurrentStreak =
          _media3PersistentBufferingHealthySamples >= 4;
      if (!hasSustainedCadence && !hasRecoveredFromCurrentStreak) {
        return false;
      }
    }
    return true;
  }

  void _recordMedia3PersistentBufferingTick(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (!_isMedia3PersistentBufferingCandidate(
      controller,
      source,
      recoveryPosition,
    )) {
      return;
    }
    final sourceKey = _playbackSourceRuntimeKey(source!);
    if (_media3PersistentBufferingSourceKey != null &&
        _media3PersistentBufferingSourceKey != sourceKey) {
      _resetMedia3PersistentBufferingStreak(reason: 'source_changed');
    }
    _media3PersistentBufferingSourceKey = sourceKey;
    _media3PersistentBufferingStreakTicks += 1;
    if (!_hasRecentMedia3PersistentBufferingProgressProof(
      recoveryPosition,
      minimumSamples: 1,
    )) {
      _media3PersistentBufferingHealthySamples = 0;
      _media3PersistentBufferingLastHealthyPosition = Duration.zero;
    }
    _forgetVerifiedSource(source, 'media3_persistent_buffering');
    if (_media3PersistentBufferingStreakTicks > _bufferingWatchdogTicks) {
      _bufferingWatchdogTicks = _media3PersistentBufferingStreakTicks;
    }
    _lastMedia3PersistentBufferingSourceKey = sourceKey;
    _lastMedia3PersistentBufferingSeenAt = DateTime.now();
    _lastMedia3PersistentBufferingTicks = _media3PersistentBufferingStreakTicks;
    final escapeTickLimit =
        _persistentBufferingAnchorEscapeTickLimitForSourceAtPosition(
      source,
      recoveryPosition,
    );
    if (_media3PersistentBufferingStreakTicks == 1 ||
        _media3PersistentBufferingStreakTicks == escapeTickLimit ||
        _media3PersistentBufferingStreakTicks % escapeTickLimit == 0) {
      DiagnosticLog.add(
        'native media3 persistent buffering streak provider=${source.providerId} ticks=$_media3PersistentBufferingStreakTicks limit=$escapeTickLimit position=${recoveryPosition.inSeconds}s action=track_until_credible_playback',
      );
    }
  }

  bool _shouldTryMedia3PersistentBufferingSegmentNudge(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (source == null) return false;
    if (_media3PersistentBufferingNudgeInFlight) return false;
    if (!_isMedia3PersistentBufferingCandidate(
      controller,
      source,
      recoveryPosition,
    )) {
      return false;
    }
    if (_sourceHasMedia3DirectHlsRendererDriftRepair(source)) return false;
    if (!_isHlsSource(source)) return false;
    if (_hasRecentMedia3PersistentBufferingProgressProof(
      recoveryPosition,
      minimumSamples: 2,
    )) {
      DiagnosticLog.add(
        'native media3 persistent buffering segment nudge skipped provider=${source.providerId} healthy=$_media3PersistentBufferingHealthySamples position=${recoveryPosition.inSeconds}s action=hold_moving_buffering reason=recent_progress_proof',
      );
      return false;
    }
    final recoveryTickLimit = _bufferingRecoveryTickLimitForSourceAtPosition(
      source,
      recoveryPosition,
    );
    final hasPersistentBufferingHoldProof =
        _media3HasPersistentBufferingHoldProof(
      controller,
      source,
    );
    final provenSourceHoldLimit = hasPersistentBufferingHoldProof
        ? math.min(2, recoveryTickLimit)
        : recoveryTickLimit;
    if (hasPersistentBufferingHoldProof &&
        _media3PersistentBufferingStreakTicks < provenSourceHoldLimit) {
      DiagnosticLog.add(
        'native media3 persistent buffering segment nudge skipped provider=${source.providerId} ticks=$_media3PersistentBufferingStreakTicks limit=$provenSourceHoldLimit action=hold_proven_source reason=credible_playback_buffering',
      );
      return false;
    }
    if (_media3PersistentBufferingStreakTicks < provenSourceHoldLimit) {
      return false;
    }
    final duration = controller.duration;
    if (duration <= Duration.zero ||
        recoveryPosition + const Duration(seconds: 3) >= duration) {
      return false;
    }
    final sourceKey = _playbackSourceRuntimeKey(source);
    if (_media3PersistentBufferingNudgeSourceKey == sourceKey &&
        _media3PersistentBufferingNudgeCountForSource >= 1) {
      DiagnosticLog.add(
        'native media3 persistent buffering segment nudge skipped provider=${source.providerId} count=$_media3PersistentBufferingNudgeCountForSource action=escape_source reason=persistent_buffering_segment_nudge_limit',
      );
      return false;
    }
    if (_media3PersistentBufferingNudgeSourceKey == sourceKey &&
        (recoveryPosition.inSeconds -
                    _media3PersistentBufferingNudgeAnchorSecond)
                .abs() <
            10) {
      return false;
    }
    return true;
  }

  bool _media3PersistentBufferingNudgedSource(PlaybackSource? source) {
    if (source == null) return false;
    return _media3PersistentBufferingNudgeSourceKey ==
        _playbackSourceRuntimeKey(source);
  }

  Future<void> _tryMedia3PersistentBufferingSegmentNudge(
    _NativePlaybackController controller,
    PlaybackSource source,
    Duration recoveryPosition,
  ) async {
    if (!_shouldTryMedia3PersistentBufferingSegmentNudge(
      controller,
      source,
      recoveryPosition,
    )) {
      return;
    }
    _media3PersistentBufferingNudgeInFlight = true;
    final sourceKey = _playbackSourceRuntimeKey(source);
    if (_media3PersistentBufferingNudgeSourceKey != sourceKey) {
      _media3PersistentBufferingNudgeCountForSource = 0;
    }
    _media3PersistentBufferingNudgeSourceKey = sourceKey;
    _media3PersistentBufferingNudgeCountForSource += 1;
    _media3PersistentBufferingNudgeAnchorSecond = recoveryPosition.inSeconds;
    final duration = controller.duration;
    final target = recoveryPosition + const Duration(seconds: 2);
    final clampedTarget = duration > Duration.zero &&
            target + const Duration(seconds: 1) >= duration
        ? duration - const Duration(seconds: 1)
        : target;
    DiagnosticLog.add(
      'native media3 persistent buffering segment nudge provider=${source.providerId} count=$_media3PersistentBufferingNudgeCountForSource position=${recoveryPosition.inSeconds}s target=${clampedTarget.inSeconds}s action=seek_forward reason=persistent_buffering_segment_nudge',
    );
    _armMedia3RecoveryQualityCeiling(
      controller,
      source,
      reason: 'persistent_buffering_segment_nudge',
    );
    _clearTransientBufferingWaitMessage(
      reason: 'persistent_buffering_segment_nudge',
    );
    _showPlaybackWaitMessage(
      'Refreshing playback...',
      reason: 'persistent_buffering_segment_nudge',
      pausePlayback: false,
    );
    try {
      await controller.seekTo(clampedTarget).timeout(
            const Duration(seconds: 4),
          );
      await controller.play().timeout(const Duration(seconds: 4));
      _lastWatchdogPosition = clampedTarget;
      _bufferingWatchdogTicks = 0;
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
    } catch (error) {
      DiagnosticLog.add(
        'native media3 persistent buffering segment nudge failed provider=${source.providerId} position=${recoveryPosition.inSeconds}s error=${_safeDiagnosticError(error)} reason=persistent_buffering_segment_nudge',
      );
    } finally {
      _media3PersistentBufferingNudgeInFlight = false;
    }
  }

  void _recordMedia3PersistentBufferingHealthySample(
      _NativePlaybackController controller,
      PlaybackSource? source,
      Duration position,
      {bool allowVisualBufferingProgress = false}) {
    if (_media3PersistentBufferingStreakTicks <= 0) return;
    if (source == null ||
        controller.engine != _NativePlaybackEngine.exoplayer ||
        _media3PersistentBufferingSourceKey !=
            _playbackSourceRuntimeKey(source)) {
      _resetMedia3PersistentBufferingStreak(
          reason: 'healthy_sample_source_changed');
      return;
    }
    final visualBufferingProgress = allowVisualBufferingProgress &&
        controller.isBuffering &&
        controller.isPlaying &&
        controller.hasRenderedVideoFrame &&
        controller.duration > Duration.zero &&
        controller.size != Size.zero &&
        !_activeSourceHasZeroClockMetadata;
    if (!controller.isInitialized ||
        (controller.isBuffering && !visualBufferingProgress) ||
        !controller.isPlaying ||
        controller.hasError ||
        controller.size == Size.zero) {
      _media3PersistentBufferingHealthySamples = 0;
      _media3PersistentBufferingLastHealthyPosition = Duration.zero;
      return;
    }
    _media3PersistentBufferingHealthySamples += 1;
    _media3PersistentBufferingLastHealthyPosition = position;
    if (_media3PersistentBufferingHealthySamples >= 4) {
      _resetMedia3PersistentBufferingStreak(
        reason: 'credible_playback_recovered',
      );
      return;
    }
    DiagnosticLog.add(
      'native media3 persistent buffering tentative progress provider=${source.providerId} ticks=$_media3PersistentBufferingStreakTicks healthy=$_media3PersistentBufferingHealthySamples/4 position=${position.inSeconds}s bufferingVisual=$visualBufferingProgress action=retain_watchdog',
    );
  }

  bool _hasRecentMedia3PersistentBufferingProgressProof(
    Duration recoveryPosition, {
    required int minimumSamples,
  }) {
    if (_media3PersistentBufferingHealthySamples < minimumSamples) {
      return false;
    }
    final lastHealthy = _media3PersistentBufferingLastHealthyPosition;
    if (lastHealthy <= Duration.zero) return false;
    return recoveryPosition <= lastHealthy + const Duration(seconds: 2);
  }

  bool _shouldTolerateMedia3ResumeSeekSettleBurst(
    _NativePlaybackController controller,
    PlaybackSource source,
    DateTime now,
    Duration position,
    Duration previousPosition,
    double ratio,
  ) {
    final until = _media3ResumeSeekSettleUntil;
    if (until == null || now.isAfter(until)) {
      _clearMedia3ResumeSeekSettleWindow();
      return false;
    }
    if (controller.engine != _NativePlaybackEngine.exoplayer ||
        source.sourceClass != PlaybackSourceClass.direct ||
        !_isHlsSource(source) ||
        !controller.isPlaying ||
        controller.isBuffering ||
        controller.hasError ||
        !controller.hasRenderedVideoFrame ||
        controller.duration <= Duration.zero ||
        controller.size == Size.zero ||
        _activeSourceHasZeroClockMetadata ||
        _media3ResumeSeekSettleAnchor < const Duration(seconds: 30) ||
        position < _media3ResumeSeekSettleAnchor - const Duration(seconds: 5) ||
        position >
            _media3ResumeSeekSettleAnchor + const Duration(seconds: 45) ||
        position <= previousPosition ||
        ratio < 1.80 ||
        _media3ResumeSeekSettleDrifts >= 4) {
      return false;
    }
    _media3ResumeSeekSettleDrifts += 1;
    DiagnosticLog.add(
      'native media3 resume seek settle tolerated provider=${source.providerId} observed=${position.inSeconds}s previous=${previousPosition.inSeconds}s anchor=${_media3ResumeSeekSettleAnchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} tolerated=$_media3ResumeSeekSettleDrifts/4 reason=post_resume_seek_clock_settling',
    );
    return true;
  }

  void _samplePlaybackCadence() {
    final controller = _controller;
    final source = _activeSource;
    final sourceClass = source?.sourceClass;
    final shouldSampleSourceClass = sourceClass == PlaybackSourceClass.p2p ||
        sourceClass == PlaybackSourceClass.direct ||
        sourceClass == PlaybackSourceClass.debrid;
    if (_playerClosing ||
        controller == null ||
        source == null ||
        !shouldSampleSourceClass ||
        _isLiveTvMode ||
        !controller.isInitialized ||
        controller.hasError) {
      return;
    }
    if (controller.engine == _NativePlaybackEngine.libvlc &&
        _mobileLibVlcCoordinator != null) {
      return;
    }
    final now = DateTime.now();
    _logMedia3ChildLoadTelemetryIfChanged(controller, source);
    final previousSampleAt = _lastCadenceSampleAt ?? now;
    var previousPosition = _lastCadencePosition;
    final position = _resumeAnchoredPlaybackPosition(controller);
    final stableCadencePosition = _stableProgressClockPosition(
      position,
      reason: 'cadence_sample',
    );
    final wallDeltaMs = now.difference(previousSampleAt).inMilliseconds;
    if (wallDeltaMs <= 0) return;
    if (wallDeltaMs < 500) return;
    final speed = math.max(_playbackSpeed, 1.0);
    final playbackDeltaMs =
        position.inMilliseconds - previousPosition.inMilliseconds;
    _playbackCadenceSamples += 1;
    final ratio = playbackDeltaMs / wallDeltaMs;
    final allowedDeltaMs = (wallDeltaMs * speed * 1.80 + 1600).round();
    final media3DirectHlsClockBurst =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            _shouldAvoidLibVlcRendererDriftEscalation(source) &&
            controller.isPlaying &&
            !controller.isBuffering &&
            position.inSeconds >= 8 &&
            ratio >= 2.70;
    final correctedTarget = previousPosition +
        Duration(milliseconds: (wallDeltaMs * speed).round());
    if (_shouldPreemptSustainedMedia3DirectHlsClockDrift(
      controller,
      source,
      now,
    )) {
      final heldPosition = _lastCrediblePlaybackPosition > Duration.zero
          ? _lastCrediblePlaybackPosition
          : previousPosition;
      final recoveryAnchor = _media3RendererDriftRecoveryAnchor(
        heldPosition: heldPosition,
        observedPosition: position,
        correctedTarget: correctedTarget,
      );
      if (recoveryAnchor >= const Duration(seconds: 3) &&
          _sourceHasMedia3DirectHlsRendererDriftRepair(source) &&
          _shouldAvoidLibVlcRendererDriftEscalation(source)) {
        DiagnosticLog.add(
          'native playback cadence renderer drift preemptive escape queued provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s anchor=${recoveryAnchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} unstable=$_playbackCadenceUnstableEvents action=advance_source_at_anchor reason=sustained_unstable_direct_hls_clock_after_repair',
        );
        unawaited(
          _advanceFromMedia3DirectHlsRendererDrift(
            source: source,
            anchor: recoveryAnchor,
            reason: 'media3_repaired_direct_hls_renderer_drift_unproven',
          ),
        );
        return;
      }
      if (recoveryAnchor >= const Duration(seconds: 3) &&
          _canStartMedia3RendererDriftRepair(
            source: source,
            anchor: recoveryAnchor,
            now: now,
          )) {
        DiagnosticLog.add(
          'native playback cadence renderer drift preemptive repair queued provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s anchor=${recoveryAnchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} unstable=$_playbackCadenceUnstableEvents action=repair_renderer_at_anchor reason=sustained_unstable_direct_hls_clock',
        );
        unawaited(
          _repairMedia3RendererDriftAtAnchor(
            source: source,
            anchor: recoveryAnchor,
            observedPosition: position,
            heldPosition: heldPosition,
          ),
        );
      }
    }
    final hasImpossibleAdvance = controller.isPlaying &&
        !controller.isBuffering &&
        (playbackDeltaMs > allowedDeltaMs || media3DirectHlsClockBurst) &&
        ratio > 2.25 &&
        position.inSeconds >= 8;
    _lastCadenceSampleAt = now;
    if (hasImpossibleAdvance) {
      if (_shouldTolerateMedia3ResumeSeekSettleBurst(
        controller,
        source,
        now,
        position,
        previousPosition,
        ratio,
      )) {
        _lastCadencePosition = position;
        _lastWatchdogPosition = position;
        _playbackCadenceConsecutiveJumpEvents = 0;
        _playbackCadenceHealthySamples += 1;
        _recordMedia3PersistentBufferingHealthySample(
          controller,
          source,
          position,
        );
        return;
      }
      _playbackCadenceJumpEvents += 1;
      _playbackCadenceConsecutiveJumpEvents += 1;
      _playbackCadenceHealthySamples = 0;
      _recordPlaybackCadenceUnstableEvent(now);
      final startedAt = _nativeWallClockStartedAt;
      final startupElapsed =
          startedAt == null ? null : now.difference(startedAt);
      final isPastStartup = startupElapsed == null ||
          startupElapsed > _media3StartupErrorGraceForSource(source);
      final heldPosition = _lastCrediblePlaybackPosition > Duration.zero
          ? _lastCrediblePlaybackPosition
          : previousPosition;
      _lastCadencePosition = heldPosition;
      _lastWatchdogPosition = heldPosition;
      final lastHoldAt = _lastPlaybackCadenceDriftHoldAt;
      final holdThrottled = lastHoldAt != null &&
          now.difference(lastHoldAt) < const Duration(seconds: 8);
      final lastObservationAt = _lastPlaybackCadenceDriftObservationLogAt;
      final observationLogThrottled = lastObservationAt != null &&
          now.difference(lastObservationAt) < const Duration(seconds: 8);
      final isMedia3DirectHlsSource =
          controller.engine == _NativePlaybackEngine.exoplayer &&
              source.sourceClass == PlaybackSourceClass.direct &&
              _isHlsSource(source);
      final directHlsSevereFirstJump = isMedia3DirectHlsSource &&
          !_activeSourceVerifiedForSession &&
          _media3DirectHlsStartupProofPending &&
          ratio >= 4.25 &&
          _playbackCadenceConsecutiveJumpEvents >= 1;
      if ((_playbackCadenceJumpEvents >= 2 || directHlsSevereFirstJump) &&
          (isPastStartup || directHlsSevereFirstJump) &&
          correctedTarget < position) {
        final engineClockMismatch =
            controller.engine == _NativePlaybackEngine.exoplayer &&
                (controller.playbackSpeed - _playbackSpeed).abs() < 0.05;
        if (engineClockMismatch) {
          final sourceKey = _playbackSourceRuntimeKey(source);
          final repairedSameSource =
              _media3RendererDriftRepairSourceKey == sourceKey &&
                  _media3RendererDriftRepairCountForSource > 0;
          final severeRendererDrift = (ratio >= 4.25 &&
                  (_playbackCadenceConsecutiveJumpEvents >= 2 ||
                      directHlsSevereFirstJump)) ||
              (media3DirectHlsClockBurst &&
                  _playbackCadenceConsecutiveJumpEvents >= 2);
          final hasSustainedVisualCadenceProof =
              _media3HasSustainedVisualCadenceProof(controller);
          final shouldEscapeManualMedia3DirectHls = severeRendererDrift &&
              isMedia3DirectHlsSource &&
              _effectivePlaybackEngine == 'exoplayer' &&
              !hasSustainedVisualCadenceProof;
          final minimumDriftConsecutiveEvents = directHlsSevereFirstJump
              ? 1
              : (severeRendererDrift ? 2 : (repairedSameSource ? 2 : 3));
          final minimumDriftObservation = severeRendererDrift
              ? Duration.zero
              : (repairedSameSource
                  ? const Duration(seconds: 1)
                  : const Duration(seconds: 2));
          final unstableStartedAt =
              _playbackCadenceUnstableWindowStartedAt ?? now;
          final unstableFor = now.difference(unstableStartedAt);
          final shouldRepairRendererDrift =
              _playbackCadenceConsecutiveJumpEvents >=
                      minimumDriftConsecutiveEvents &&
                  unstableFor >= minimumDriftObservation;
          if (shouldRepairRendererDrift) {
            final recoveryAnchor = _media3RendererDriftRecoveryAnchor(
              heldPosition: heldPosition,
              observedPosition: position,
              correctedTarget: correctedTarget,
            );
            if (recoveryAnchor >= const Duration(seconds: 3)) {
              if (_shouldHoldMedia3RendererDriftOnCurrentSource(
                controller,
                source,
                recoveryAnchor,
                now,
                repairedSameSource: repairedSameSource,
                severeRendererDrift: severeRendererDrift,
                unstableFor: unstableFor,
                ratio: ratio,
              )) {
                _holdMedia3RendererDriftOnCurrentSource(
                  controller,
                  source,
                  anchor: recoveryAnchor,
                  observedPosition: position,
                  heldPosition: heldPosition,
                  ratio: ratio,
                  unstableFor: unstableFor,
                );
                return;
              }
              if (shouldEscapeManualMedia3DirectHls) {
                _recordMedia3DirectHlsRendererDriftRisk(source);
                DiagnosticLog.add(
                  'native playback cadence renderer drift direct hls escape queued provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s anchor=${recoveryAnchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} consecutive=$_playbackCadenceConsecutiveJumpEvents action=advance_source_at_anchor reason=manual_media3_direct_hls_renderer_drift',
                );
                unawaited(
                  _advanceFromMedia3DirectHlsRendererDrift(
                    source: source,
                    anchor: recoveryAnchor,
                    reason: 'manual_media3_direct_hls_renderer_drift',
                  ),
                );
                return;
              }
              final canRepairRendererDrift = _canStartMedia3RendererDriftRepair(
                source: source,
                anchor: recoveryAnchor,
                now: now,
              );
              final canEscalateRendererDrift =
                  _canStartMedia3RendererDriftEscalation(
                source: source,
                anchor: recoveryAnchor,
                now: now,
              );
              final shouldEscalateRendererDrift =
                  (repairedSameSource || severeRendererDrift) &&
                      canEscalateRendererDrift;
              if (canEscalateRendererDrift) {
                if (shouldEscalateRendererDrift) {
                  DiagnosticLog.add(
                    'native playback cadence renderer drift escalation queued provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s anchor=${recoveryAnchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} consecutive=$_playbackCadenceConsecutiveJumpEvents unstable=$_playbackCadenceUnstableEvents action=escalate_renderer_route_at_anchor',
                  );
                  unawaited(
                    _escalateMedia3RendererDriftAtAnchor(
                      source: source,
                      anchor: recoveryAnchor,
                      observedPosition: position,
                      heldPosition: heldPosition,
                    ),
                  );
                }
              }
              if (canRepairRendererDrift) {
                if (!shouldEscalateRendererDrift) {
                  DiagnosticLog.add(
                    'native playback cadence renderer drift repair queued provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s anchor=${recoveryAnchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} consecutive=$_playbackCadenceConsecutiveJumpEvents unstable=$_playbackCadenceUnstableEvents action=repair_renderer_at_anchor',
                  );
                  unawaited(
                    _repairMedia3RendererDriftAtAnchor(
                      source: source,
                      anchor: recoveryAnchor,
                      observedPosition: position,
                      heldPosition: heldPosition,
                    ),
                  );
                }
              }
            }
          }
          if (!holdThrottled && _playbackCadenceConsecutiveJumpEvents >= 2) {
            _lastPlaybackCadenceDriftHoldAt = now;
            DiagnosticLog.add(
              'native playback cadence renderer drift held provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s ratio=${ratio.toStringAsFixed(2)} consecutive=$_playbackCadenceConsecutiveJumpEvents unstable=$_playbackCadenceUnstableEvents engineSpeed=${controller.playbackSpeed.toStringAsFixed(2)} expectedSpeed=${_playbackSpeed.toStringAsFixed(2)} action=hold_progress_clock',
            );
          } else if (!observationLogThrottled) {
            _lastPlaybackCadenceDriftObservationLogAt = now;
            DiagnosticLog.add(
              'native playback cadence renderer drift observed provider=${source.providerId} engine=${controller.engine.id} observed=${position.inSeconds}s stable=${heldPosition.inSeconds}s ratio=${ratio.toStringAsFixed(2)} consecutive=$_playbackCadenceConsecutiveJumpEvents unstable=$_playbackCadenceUnstableEvents engineSpeed=${controller.playbackSpeed.toStringAsFixed(2)} expectedSpeed=${_playbackSpeed.toStringAsFixed(2)} action=observe_current_source',
            );
          }
        }
      }
    } else if (ratio > 0.35 && ratio < 1.80 && !controller.isBuffering) {
      _lastCadencePosition = position;
      _playbackCadenceConsecutiveJumpEvents = 0;
      _playbackCadenceHealthySamples += 1;
      _recordMedia3PersistentBufferingHealthySample(
        controller,
        source,
        position,
      );
      if (_playbackCadenceClockUnstable &&
          _playbackCadenceHealthySamples >= 4) {
        _lastIntegritySampleAt = now;
        _lastIntegrityPosition = position;
        _lastKnownPlaybackPosition = position;
        _rememberCrediblePlaybackAnchor(
          position,
          reason: 'cadence_clock_recovered',
        );
        DiagnosticLog.add(
          'native playback cadence clock recovered provider=${source.providerId} engine=${controller.engine.id} position=${position.inSeconds}s healthy=$_playbackCadenceHealthySamples action=trust_current_clock',
        );
        _clearPlaybackCadenceUnstableState();
      }
      if (_playbackCadenceHealthySamples >= 15) {
        _clearPlaybackCadenceUnstableState();
      }
    } else if (ratio > 0.35 &&
        ratio < 1.80 &&
        controller.isBuffering &&
        controller.isPlaying &&
        _shouldKeepVisualControllerBufferingQuiet(
          controller,
          source,
          position,
        )) {
      _lastCadencePosition = position;
      _playbackCadenceConsecutiveJumpEvents = 0;
      _recordMedia3PersistentBufferingHealthySample(
        controller,
        source,
        position,
        allowVisualBufferingProgress: true,
      );
    } else {
      if (_playbackCadenceClockUnstable || controller.isBuffering) {
        _lastCadencePosition = stableCadencePosition;
      } else {
        _lastCadencePosition = position;
      }
      _playbackCadenceConsecutiveJumpEvents = 0;
    }
    final shouldLog = _playbackCadenceSamples <= 3 ||
        _playbackCadenceSamples % 30 == 0 ||
        ratio < 0.35 ||
        ratio > 1.80 ||
        controller.isBuffering;
    if (!shouldLog) return;
    DiagnosticLog.add(
      'native playback cadence sample sourceClass=${source.sourceClass.wireName} provider=${source.providerId} engine=${controller.engine.id} view=${controller.videoViewType?.name ?? 'native'} position=${position.inSeconds}s bufferEnd=${controller.bufferedPosition.inSeconds}s bufferAhead=${controller.totalBufferedDuration.inSeconds}s relayBufferEnd=${_libVlcContinuousTsBufferedPosition.inSeconds}s relayLead=${_libVlcContinuousTsRemainingLead(position).inSeconds}s relayFatal=${_libVlcContinuousTsUpstreamErrors > 0} wallDeltaMs=$wallDeltaMs playbackDeltaMs=$playbackDeltaMs ratio=${ratio.toStringAsFixed(2)} engineSpeed=${controller.playbackSpeed.toStringAsFixed(2)} playing=${controller.isPlaying} buffering=${controller.isBuffering}',
    );
  }

  void _logMedia3ChildLoadTelemetryIfChanged(
    _NativePlaybackController controller,
    PlaybackSource source,
  ) {
    final media3Controller = controller.media3;
    if (media3Controller == null) return;
    final signature = [
      media3Controller.loadCompletedSummary,
      media3Controller.loadErrorSummary,
      media3Controller.lastLoadErrorBucket,
    ].join('|');
    if (signature == _lastMedia3ChildLoadTelemetrySignature) return;
    _lastMedia3ChildLoadTelemetrySignature = signature;
    DiagnosticLog.add(
      'native media3 child load telemetry provider=${source.providerId} loads=${media3Controller.loadCompletedSummary} loadErrors=${media3Controller.loadErrorSummary} lastLoadError=${media3Controller.lastLoadErrorBucket}',
    );
  }

  Future<void> _recoverFromMedia3HlsPersistentBufferingNudge(
    PlaybackSource source,
    Duration recoveryPosition,
  ) async {
    final retriedWithLibVlc = await _retrySourceWithLibVlcAfterExoVisualFailure(
      source,
      recoveryPosition,
      statusMessage: 'Recovering stream...',
      reason: 'media3_hls_buffering_nudge_limit',
    );
    if (retriedWithLibVlc) {
      DiagnosticLog.add(
        'native media3 persistent buffering nudge recovered with libvlc provider=${source.providerId} ticks=$_media3PersistentBufferingStreakTicks position=${recoveryPosition.inSeconds}s action=retry_libvlc reason=media3_hls_buffering_nudge_limit',
      );
      return;
    }

    final qualityRank = _qualityRank(_qualityLabel(source));
    final inferredRank =
        qualityRank > 0 ? qualityRank : _media3RecoveryQualityCeilingRank;
    if (qualityRank > 0) {
      _resumeRecoveryExcludedQualityRanks.add(qualityRank);
    } else {
      _resumeRecoveryUnrankedDirectHlsFailures += 1;
    }
    _markRuntimeSourceFailure(
      source,
      'media3_persistent_buffering_nudge_limit',
    );
    _incrementFailedSourceAttempt(source);
    _ignoreSavedQualityForResumeRecovery = true;
    _anchorNativeRecoveryProgress(
      recoveryPosition,
      reason: 'media3_persistent_buffering_nudge_limit',
    );
    _bufferingWatchdogTicks = 0;
    _persistentBufferingRecoveryEscapeArmed = true;
    DiagnosticLog.add(
      'native media3 persistent buffering nudge limit escaping source provider=${source.providerId} ticks=$_media3PersistentBufferingStreakTicks rank=${inferredRank ?? qualityRank} position=${recoveryPosition.inSeconds}s action=advance_source reason=media3_hls_buffering_nudge_limit',
    );
    final nextSourceIndex =
        _nextSourceIndexAfterHardFailure(_activeSources, _sourceIndex);
    if (nextSourceIndex != null) {
      DiagnosticLog.add(
        'native media3 persistent buffering nudge provider=${source.providerId} nextSourceIndex=$nextSourceIndex action=advance_known_source_without_resolve position=${recoveryPosition.inSeconds}s reason=media3_hls_buffering_nudge_limit',
      );
      if (await _tryKnownMedia3RecoverySourceAtIndex(
        nextSourceIndex,
        recoveryPosition,
        reason: 'media3_persistent_buffering_alternate_source',
      )) {
        return;
      }
      _recoveringFromStall = false;
    }
    await _recoverFromPlaybackStall(
      recoveryPosition,
      skipSameSource: true,
      skipProvider: false,
      forceSourceAdvance: true,
      allowSourceReload: false,
    );
  }

  Future<bool> _retrySourceWithLibVlcAfterExoVisualFailure(
    PlaybackSource source,
    Duration resumePosition, {
    required String statusMessage,
    required String reason,
  }) async {
    if (!mounted || _playerClosing) return false;
    if (_effectivePlaybackEngine != 'auto') {
      DiagnosticLog.add(
        'native retry with libvlc skipped provider=${source.providerId} reason=manual_engine_locked originalReason=$reason',
      );
      return false;
    }
    if (_manualLibVlcConfigured || _libvlcUnavailableForCurrentPass) {
      return false;
    }
    if (_isLiveTvMode && !_isPublicIptvSource(source)) return false;
    if (_shouldRejectLibVlcDirectHlsStartup(
      source,
      _NativePlaybackEngine.libvlc,
    )) {
      DiagnosticLog.add(
        'native retry with libvlc skipped provider=${source.providerId} reason=libvlc_direct_hls_startup_crash_guard originalReason=$reason',
      );
      return false;
    }
    if (_libVlcContinuousTsRelayEnabled &&
        source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        !_canUseLibVlcHlsRelaySource(source, _NativePlaybackEngine.libvlc) &&
        resumePosition >= const Duration(seconds: 5)) {
      if (_effectivePlaybackEngine == 'auto') {
        _libvlcUnavailableForSession = true;
      }
      DiagnosticLog.add(
        'native retry with libvlc skipped provider=${source.providerId} reason=resumed_direct_hls_libvlc_crash_guard originalReason=$reason position=${resumePosition.inSeconds}s autoRouteUnavailable=$_libvlcUnavailableForSession',
      );
      return false;
    }
    DiagnosticLog.add(
      'native retrying source with libvlc provider=${source.providerId} position=${resumePosition.inSeconds}s reason=$reason',
    );
    return _openSource(
      source,
      resumePosition: resumePosition,
      statusMessage: statusMessage,
      engineOverride: _NativePlaybackEngine.libvlc,
      requireStartupPlaybackProof: true,
    );
  }

  bool _shouldRejectLibVlcDirectHlsStartup(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (engine != _NativePlaybackEngine.libvlc) return false;
    if (!_libVlcContinuousTsRelayEnabled) return false;
    if (_nativeRouteIsLiveWithoutRequestState || _isPublicIptvSource(source)) {
      return false;
    }
    if (_canUseLibVlcHlsRelaySource(source, engine)) return false;
    return source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source);
  }

  bool _shouldRejectLibVlcDirectHlsResume(
    PlaybackSource source,
    _NativePlaybackEngine engine,
    Duration resumePosition,
  ) {
    if (engine != _NativePlaybackEngine.libvlc) return false;
    if (!_libVlcContinuousTsRelayEnabled) return false;
    if (resumePosition < const Duration(seconds: 5)) return false;
    if (_nativeRouteIsLiveWithoutRequestState || _isPublicIptvSource(source)) {
      return false;
    }
    if (_canUseLibVlcHlsRelaySource(source, engine)) return false;
    return source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source);
  }

  bool _canUseLibVlcHlsRelaySource(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (engine != _NativePlaybackEngine.libvlc) return false;
    if (!_libVlcContinuousTsRelayEnabled) return false;
    if (source.sourceClass != PlaybackSourceClass.direct) return false;
    if (!_isHlsSource(source)) return false;
    if (source.headers.isNotEmpty) return true;
    return mobileFirstPartyOpaqueMediaCapability(Uri.tryParse(source.url));
  }

  bool get _nativeRouteIsLiveWithoutRequestState {
    return widget.liveMode || _progressItem?.type == MediaType.liveTv;
  }

  Duration? _preOpenLibVlcDirectHlsResumePosition(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (engine != _NativePlaybackEngine.libvlc) return null;
    if (source.sourceClass != PlaybackSourceClass.direct) return null;
    if (!_isHlsSource(source)) return null;
    final resumePosition = _preOpenPreferredResumePosition(source, engine);
    return resumePosition > Duration.zero ? resumePosition : null;
  }

  bool _shouldTryLibVlcForMedia3ResumeFailure(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (_effectivePlaybackEngine != 'auto') return false;
    if (_manualLibVlcConfigured || _libvlcUnavailableForCurrentPass) {
      return false;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    final hasResumeAnchor =
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
            _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
            _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
            _lastSavedSecond >= 5;
    if (!hasResumeAnchor) return false;
    final description = controller.errorDescription.toLowerCase();
    final sourceError = controller.hasError &&
        (description.contains('source error') ||
            description.contains('exoplaybackexception') ||
            description.contains('failed_runtime_check'));
    return sourceError && _hadRecentMedia3PersistentBufferingForSource(source);
  }

  void _prepareForSystemPip() {
    if (!mounted) return;
    DiagnosticLog.add('native system PiP preparing compact controls');
    setState(() {
      _pictureInPictureActive = true;
      _systemPipHandoffActive = false;
      _optionSheetOpen = false;
      _settingsExpanded = false;
      _controlsVisible = false;
      _clearGestureHintState();
      _locked = false;
    });
    unawaited(_setKeepScreenOn(false));
  }

  void _showPlaybackWaitMessage(
    String message, {
    required String reason,
    bool pausePlayback = false,
  }) {
    if (_playerClosing || _loading) return;
    final pausedForMessage = pausePlayback
        ? _pauseActivePlaybackForLoading('wait_message_$reason')
        : false;
    _playbackWaitMessagePausedPlayback =
        _playbackWaitMessagePausedPlayback || pausedForMessage;
    if (_playbackWaitMessage == message) {
      if (mounted && (_controlsVisible || _settingsExpanded)) {
        setState(() {
          _controlsVisible = false;
          _settingsExpanded = false;
          _clearGestureHintState();
        });
      }
      return;
    }
    DiagnosticLog.add(
      'native playback wait message reason=$reason provider=${_activeSource?.providerId} message="$message"',
    );
    if (mounted) {
      setState(() {
        _playbackWaitMessage = message;
        _controlsVisible = false;
        _settingsExpanded = false;
        _clearGestureHintState();
      });
    } else {
      _playbackWaitMessage = message;
      _controlsVisible = false;
      _settingsExpanded = false;
      _clearGestureHintState();
    }
  }

  void _clearPlaybackWaitMessage({required String reason}) {
    if (_playbackWaitMessage == null) return;
    final shouldResume = _playbackWaitMessagePausedPlayback &&
        !_playerClosing &&
        !_loading &&
        !_recoveringFromStall &&
        !_openingSource &&
        !_optionSheetOpen &&
        !_settingsExpanded &&
        !_userPaused;
    _playbackWaitMessagePausedPlayback = false;
    DiagnosticLog.add(
      'native playback wait message cleared reason=$reason provider=${_activeSource?.providerId}',
    );
    if (mounted) {
      setState(() => _playbackWaitMessage = null);
    } else {
      _playbackWaitMessage = null;
    }
    if (shouldResume) {
      unawaited(_resumePlaybackAfterWaitMessage(reason));
    }
  }

  void _checkPlaybackStall() {
    final controller = _controller;
    if (_playerClosing || !mounted) {
      _stopStallWatchdog();
      return;
    }
    if (_settingsExpanded || _optionSheetOpen) {
      _lastWatchdogPosition = controller?.position ?? Duration.zero;
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      _resetTransientPlaybackDebounce();
      _clearPlaybackWaitMessage(reason: 'player_sheet_open');
      return;
    }
    if (_loading || _recoveringFromStall || controller == null) {
      _lastWatchdogPosition = controller?.position ?? Duration.zero;
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      _resetTransientPlaybackDebounce();
      return;
    }
    if (controller.engine == _NativePlaybackEngine.libvlc &&
        _mobileLibVlcCoordinator != null) {
      return;
    }

    final position = controller.position;
    if (controller.hasError) {
      if (!AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
        DiagnosticLog.add(
          'native playback controller error detected but auto-switch on stall is disabled',
        );
        return;
      }
      if (_shouldDeferControllerErrorRecovery(controller, reason: 'watchdog')) {
        return;
      }
      final recoveryPosition = _effectiveRecoveryPosition(position);
      if (_controllerErrorRecoveryAlreadyQueued(
        controller,
        recoveryPosition: recoveryPosition,
        reason: 'watchdog',
      )) {
        return;
      }
      final shouldRepairAtAnchor = _shouldRepairExoControllerErrorAtAnchor(
        controller,
        recoveryPosition,
      );
      DiagnosticLog.add(
        'native playback controller error provider=${_activeSource?.providerId} reportedPosition=${position.inSeconds}s recoveryPosition=${recoveryPosition.inSeconds}s action=${shouldRepairAtAnchor ? 'repair_exoplayer_at_anchor' : 'failover_source'} error=${controller.errorDescription}',
      );
      if (shouldRepairAtAnchor) {
        final source = _activeSource;
        _anchorNativeRecoveryProgress(
          recoveryPosition,
          reason: 'watchdog_exoplayer_anchor_repair',
        );
        if (source != null) {
          _scheduleDeferredResumeSeek(
            recoveryPosition,
            source.providerId,
            controller,
          );
        }
      } else {
        _recordControllerRuntimeFailureHint(controller, reason: 'watchdog');
      }
      unawaited(
        _recoverFromPlaybackStall(
          recoveryPosition,
          skipSameSource: !shouldRepairAtAnchor,
          skipProvider: !shouldRepairAtAnchor,
        ),
      );
      return;
    }

    if (!controller.isInitialized) {
      _lastWatchdogPosition = position;
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      _resetTransientPlaybackDebounce();
      return;
    }

    final nativeClockUnavailable = position <= Duration.zero &&
        controller.duration <= Duration.zero &&
        controller.size == Size.zero;
    if (nativeClockUnavailable) {
      final publicIptvSource =
          _activeSource != null && _isPublicIptvSource(_activeSource!);
      final source = _activeSource;
      final metadataStartupElapsed = _nativeWallClockStartedAt == null
          ? null
          : DateTime.now().difference(_nativeWallClockStartedAt!);
      _stallWatchdogTicks += 1;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      _saveNativeProgress();
      if (_stallWatchdogTicks == 1) {
        DiagnosticLog.add(
          'native metadata clock unavailable; skipping position-only stall recovery provider=${_activeSource?.providerId} engine=${controller.engine.id}',
        );
      }
      if (_isLiveTvMode || publicIptvSource) {
        if (_stallWatchdogTicks < 6) {
          DiagnosticLog.add(
            'native live tv metadata grace provider=${_activeSource?.providerId} tick=$_stallWatchdogTicks engine=${controller.engine.id}',
          );
          _clearPlaybackWaitMessage(reason: 'live_tv_metadata_grace');
          return;
        }
        if (AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
          DiagnosticLog.add(
            'native live tv metadata unresolved provider=${_activeSource?.providerId} tick=$_stallWatchdogTicks engine=${controller.engine.id} action=refresh-surface',
          );
          unawaited(
            _recoverFromBlackVideo(_effectiveRecoveryPosition(position)),
          );
          return;
        }
      }
      final media3MetadataStartupTimedOut = controller.engine ==
              _NativePlaybackEngine.exoplayer &&
          source != null &&
          source.sourceClass != PlaybackSourceClass.p2p &&
          !_isLiveTvMode &&
          metadataStartupElapsed != null &&
          metadataStartupElapsed >= _media3StartupErrorGraceForSource(source);
      if (media3MetadataStartupTimedOut &&
          AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
        DiagnosticLog.add(
          'native media3 metadata startup timeout provider=${source.providerId} elapsed=${metadataStartupElapsed.inSeconds}s position=${position.inSeconds}s duration=${controller.duration.inSeconds}s size=0x0 action=recover',
        );
        _showPlaybackWaitMessage(
          'Recovering playback...',
          reason: 'media3_metadata_startup_timeout',
        );
        unawaited(
          _recoverFromPlaybackStall(
            _effectiveRecoveryPosition(position),
            skipSameSource: false,
            skipProvider: false,
          ),
        );
        return;
      }
      _showPlaybackWaitMessage(
        'Getting stream details...',
        reason: 'metadata_clock_unavailable',
        pausePlayback: false,
      );
      return;
    }

    if (controller.isBuffering) {
      _lastWatchdogPosition = position;
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _blackVideoWatchdogTicks = 0;
      _bufferingWatchdogTicks += 1;
      _resetTransientPlaybackDebounce();
      final source = _activeSource;
      final recoveryTickLimit = _bufferingRecoveryTickLimitForSource(source);
      final zeroVisualStartupRecoveryTickLimit =
          _zeroVisualStartupRecoveryTickLimitForSource(source);
      final bufferingStartupGrace = _media3StartupGraceActive(
        controller,
        source,
        _nativeWallClockStartedAt == null
            ? null
            : DateTime.now().difference(_nativeWallClockStartedAt!),
      );
      if (bufferingStartupGrace) {
        if (_bufferingWatchdogTicks == 1 ||
            _bufferingWatchdogTicks % recoveryTickLimit == 0) {
          DiagnosticLog.add(
            'native media3 startup buffering grace provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s duration=${controller.duration.inSeconds}s size=${controller.size.width.toStringAsFixed(0)}x${controller.size.height.toStringAsFixed(0)}',
          );
        }
        if (_bufferingWaitMessageReady(
          _bufferingWatchdogTicks,
          recoveryTickLimit,
        )) {
          _showPlaybackWaitMessage(
            'Buffering stream...',
            reason: 'media3_startup_buffering_grace',
            pausePlayback: false,
          );
        } else {
          _clearTransientBufferingWaitMessage(
            reason: 'media3_startup_buffering_grace',
          );
        }
        return;
      }
      final media3ZeroVisualBuffering = source != null &&
          controller.engine == _NativePlaybackEngine.exoplayer &&
          source.sourceClass != PlaybackSourceClass.p2p &&
          !_isLiveTvMode &&
          controller.duration > Duration.zero &&
          controller.size == Size.zero &&
          _progressItem?.type != MediaType.music;
      final zeroVisualRecoveryTickLimit = media3ZeroVisualBuffering
          ? zeroVisualStartupRecoveryTickLimit
          : recoveryTickLimit;
      final zeroVisualHasProgressAnchor =
          position >= const Duration(seconds: 3) ||
              _lastKnownPlaybackPosition >= const Duration(seconds: 3) ||
              _lastSavedSecond >= 3;
      final bufferingSourceHasRuntimeProof = _activeSourceVerifiedForSession ||
          _sourceHasVisualPlaybackProof(controller);
      final zeroVisualShouldHoldHealthyAnchor = media3ZeroVisualBuffering &&
          zeroVisualHasProgressAnchor &&
          !controller.hasError &&
          (_playbackCadenceClockUnstable ||
              _lastCrediblePlaybackPosition >= const Duration(seconds: 3) ||
              _lastKnownPlaybackPosition >= const Duration(seconds: 3) ||
              _resumeProgressAnchorPosition >= const Duration(seconds: 3));
      final zeroVisualAnchorHoldExpired =
          _bufferingWatchdogTicks >= zeroVisualRecoveryTickLimit;
      if (media3ZeroVisualBuffering &&
          zeroVisualHasProgressAnchor &&
          !controller.hasError &&
          !zeroVisualAnchorHoldExpired) {
        final anchorPosition = _effectiveRecoveryPosition(position);
        DiagnosticLog.add(
          'native buffering zero visual provider=${source.providerId} engine=${controller.engine.id} tick=$_bufferingWatchdogTicks position=${position.inSeconds}s duration=${controller.duration.inSeconds}s anchor=true proof=$bufferingSourceHasRuntimeProof healthyAnchor=$zeroVisualShouldHoldHealthyAnchor action=hold reason=buffering_zero_visual_anchor_hold',
        );
        _stallWatchdogTicks = 0;
        _deadPauseTicks = 0;
        _lastWatchdogPosition = anchorPosition;
        _scheduleDeferredResumeSeek(
            anchorPosition, source.providerId, controller);
        _clearTransientBufferingWaitMessage(
          reason: 'media3_zero_visual_progress_anchor_hold',
        );
        return;
      }
      final canRecoverAnchoredZeroVisualBuffering = media3ZeroVisualBuffering &&
          zeroVisualHasProgressAnchor &&
          !bufferingSourceHasRuntimeProof &&
          AppState.playerBehaviorSettings.value.autoSwitchOnStall &&
          _bufferingWatchdogTicks >= zeroVisualRecoveryTickLimit;
      final canRecoverUnanchoredZeroVisualBuffering =
          media3ZeroVisualBuffering &&
              !zeroVisualHasProgressAnchor &&
              !bufferingSourceHasRuntimeProof &&
              AppState.playerBehaviorSettings.value.autoSwitchOnStall &&
              _bufferingWatchdogTicks >= zeroVisualRecoveryTickLimit;
      final canRecoverZeroVisualBuffering =
          canRecoverAnchoredZeroVisualBuffering ||
              canRecoverUnanchoredZeroVisualBuffering;
      if (media3ZeroVisualBuffering) {
        final zeroVisualReason = canRecoverZeroVisualBuffering
            ? canRecoverAnchoredZeroVisualBuffering
                ? 'media3_zero_visual_anchor_recovery'
                : 'media3_zero_visual_buffering'
            : zeroVisualShouldHoldHealthyAnchor
                ? 'buffering_zero_visual_anchor_hold'
                : 'buffering_zero_visual_hold';
        DiagnosticLog.add(
          'native buffering zero visual provider=${source.providerId} engine=${controller.engine.id} tick=$_bufferingWatchdogTicks position=${position.inSeconds}s duration=${controller.duration.inSeconds}s anchor=$zeroVisualHasProgressAnchor proof=$bufferingSourceHasRuntimeProof healthyAnchor=$zeroVisualShouldHoldHealthyAnchor action=${canRecoverZeroVisualBuffering ? 'recover' : 'hold'} reason=$zeroVisualReason',
        );
      }
      if (canRecoverZeroVisualBuffering) {
        final recoveryPosition = _effectiveRecoveryPosition(position);
        DiagnosticLog.add(
          'native buffering watchdog provider=${source.providerId} tick=$_bufferingWatchdogTicks limit=$zeroVisualRecoveryTickLimit position=${position.inSeconds}s recoveryPosition=${recoveryPosition.inSeconds}s action=recover reason=media3_zero_visual_buffering',
        );
        _showPlaybackWaitMessage(
          'Recovering playback...',
          reason: 'buffering_watchdog_recover',
          pausePlayback: false,
        );
        _bufferingWatchdogTicks = 0;
        unawaited(
          _recoverFromPlaybackStall(
            recoveryPosition,
            skipSameSource: false,
            skipProvider: false,
            forceSourceAdvance: false,
            allowSourceReload: true,
          ),
        );
        return;
      }
      final persistentBufferingRecoveryPosition =
          _effectiveRecoveryPosition(position);
      _recordMedia3PersistentBufferingTick(
        controller,
        source,
        persistentBufferingRecoveryPosition,
      );
      if (controller.engine == _NativePlaybackEngine.exoplayer &&
          source != null &&
          source.sourceClass == PlaybackSourceClass.direct &&
          _isHlsSource(source) &&
          _media3PersistentBufferingStreakTicks == 1) {
        DiagnosticLog.add(
          'native media3 persistent buffering synthetic nudge disabled provider=${source.providerId} position=${persistentBufferingRecoveryPosition.inSeconds}s action=hold_current_source reason=tv_parity_no_synthetic_seek',
        );
      }
      final persistentBufferingRecoveryTickLimit =
          _bufferingRecoveryTickLimitForSourceAtPosition(
        source,
        persistentBufferingRecoveryPosition,
      );
      final persistentBufferingEscapeTickLimit =
          _persistentBufferingAnchorEscapeTickLimitForSourceAtPosition(
        source,
        persistentBufferingRecoveryPosition,
      );
      final persistentBufferingHasRecentProgress =
          _hasRecentMedia3PersistentBufferingProgressProof(
        persistentBufferingRecoveryPosition,
        minimumSamples: 2,
      );
      final persistentBufferingNudgeLimitReached =
          !persistentBufferingHasRecentProgress &&
              _media3PersistentBufferingNudgedSource(source) &&
              _media3PersistentBufferingNudgeCountForSource >= 1 &&
              _media3PersistentBufferingStreakTicks >=
                  math.max(4, persistentBufferingRecoveryTickLimit ~/ 2);
      final resumeRecoveryQualityLimitReached = source != null &&
          !persistentBufferingHasRecentProgress &&
          source.sourceClass == PlaybackSourceClass.direct &&
          _isHlsSource(source) &&
          _resumeRecoveryExcludedQualityRanks.isNotEmpty &&
          _bufferingWatchdogTicks > persistentBufferingRecoveryTickLimit;
      final persistentBufferingRepairLimit =
          persistentBufferingNudgeLimitReached
              ? persistentBufferingRecoveryTickLimit + 1
              : resumeRecoveryQualityLimitReached
                  ? persistentBufferingRecoveryTickLimit + 1
                  : _media3PersistentBufferingNudgedSource(source)
                      ? persistentBufferingEscapeTickLimit
                      : source != null &&
                              _isHlsSource(source) &&
                              _media3HasPersistentBufferingHoldProof(
                                controller,
                                source,
                              )
                          ? persistentBufferingRecoveryTickLimit
                          : persistentBufferingRecoveryTickLimit *
                              _persistentBufferingAnchorRepairLimitForSource(
                                source,
                              );
      final persistentBufferingEscapeReady =
          !persistentBufferingHasRecentProgress &&
              (persistentBufferingNudgeLimitReached ||
                  resumeRecoveryQualityLimitReached ||
                  _bufferingWatchdogTicks >=
                      persistentBufferingEscapeTickLimit);
      if (persistentBufferingNudgeLimitReached &&
          source != null &&
          controller.engine == _NativePlaybackEngine.exoplayer &&
          source.sourceClass == PlaybackSourceClass.direct &&
          _isHlsSource(source)) {
        unawaited(
          _recoverFromMedia3HlsPersistentBufferingNudge(
            source,
            persistentBufferingRecoveryPosition,
          ),
        );
        return;
      }
      if (_shouldKeepVerifiedControllerBufferingQuiet(
        controller,
        source,
        persistentBufferingRecoveryPosition,
      )) {
        if (persistentBufferingEscapeReady) {
          DiagnosticLog.add(
            'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s recoveryPosition=${persistentBufferingRecoveryPosition.inSeconds}s action=expire_quiet_guard reason=persistent_buffering_anchor_expired',
          );
        } else {
          final keepVisualBufferingQuiet =
              _shouldKeepVisualControllerBufferingQuiet(
            controller,
            source,
            persistentBufferingRecoveryPosition,
          );
          if (_bufferingWatchdogTicks == 1 ||
              _bufferingWatchdogTicks == recoveryTickLimit - 1) {
            DiagnosticLog.add(
              'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s recoveryPosition=${persistentBufferingRecoveryPosition.inSeconds}s action=hold_quiet reason=verified_controller_buffering_grace',
            );
          }
          if (keepVisualBufferingQuiet) {
            if (_bufferingWatchdogTicks == 1 ||
                _bufferingWatchdogTicks == recoveryTickLimit ||
                _bufferingWatchdogTicks % recoveryTickLimit == 0) {
              DiagnosticLog.add(
                'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s recoveryPosition=${persistentBufferingRecoveryPosition.inSeconds}s action=hold_quiet reason=verified_controller_buffering_visual_progress',
              );
            }
            _clearTransientBufferingWaitMessage(
              reason: 'verified_controller_buffering_visual_progress',
            );
          } else if (_bufferingWaitMessageReady(
            _bufferingWatchdogTicks,
            recoveryTickLimit,
          )) {
            _showPlaybackWaitMessage(
              'Buffering stream...',
              reason: 'verified_controller_buffering_grace',
              pausePlayback: false,
            );
          } else {
            _clearTransientBufferingWaitMessage(
              reason: 'verified_controller_buffering_grace',
            );
          }
          return;
        }
      }
      final shouldRepairPersistentBuffering =
          _bufferingWatchdogTicks >= persistentBufferingRepairLimit &&
              _shouldRepairPersistentControllerBuffering(
                controller,
                source,
                persistentBufferingRecoveryPosition,
              );
      if (shouldRepairPersistentBuffering) {
        DiagnosticLog.add(
          'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s recoveryPosition=${persistentBufferingRecoveryPosition.inSeconds}s holds=$_verifiedTransientBufferingHolds repairLimit=$persistentBufferingRepairLimit escape=$persistentBufferingEscapeReady action=repair_current_source reason=persistent_buffering_progress_anchor',
        );
        _anchorNativeRecoveryProgress(
          persistentBufferingRecoveryPosition,
          reason: 'persistent_buffering_progress_anchor',
        );
        if (!persistentBufferingEscapeReady &&
            _shouldHoldSoftWatchdogRecovery(
              controller,
              source,
              persistentBufferingRecoveryPosition,
              allowSourceReload: true,
              forceSourceAdvance: false,
              skipProvider: false,
              libVlcZeroMetadataStall: false,
            )) {
          _bufferingWatchdogTicks = 0;
          _holdSoftWatchdogRecovery(
            controller,
            persistentBufferingRecoveryPosition,
            'persistent_buffering_progress_anchor_hold',
          );
          return;
        }
        _bufferingWatchdogTicks = 0;
        _persistentBufferingRecoveryEscapeArmed =
            persistentBufferingEscapeReady;
        unawaited(
          _recoverFromPlaybackStall(
            persistentBufferingRecoveryPosition,
            skipSameSource: false,
            skipProvider: false,
            forceSourceAdvance: false,
            allowSourceReload: true,
          ),
        );
        return;
      }
      if (_bufferingWatchdogTicks >= recoveryTickLimit) {
        DiagnosticLog.add(
          'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s action=hold',
        );
      }
      if (_shouldKeepVisualControllerBufferingQuiet(
        controller,
        source,
        persistentBufferingRecoveryPosition,
      )) {
        if (_bufferingWatchdogTicks == 1 ||
            _bufferingWatchdogTicks == recoveryTickLimit ||
            _bufferingWatchdogTicks % recoveryTickLimit == 0) {
          DiagnosticLog.add(
            'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$recoveryTickLimit position=${position.inSeconds}s recoveryPosition=${persistentBufferingRecoveryPosition.inSeconds}s action=hold_quiet reason=controller_buffering_visual_progress',
          );
        }
        _clearTransientBufferingWaitMessage(
          reason: 'controller_buffering_visual_progress',
        );
        return;
      }
      if (_bufferingWaitMessageReady(
        _bufferingWatchdogTicks,
        recoveryTickLimit,
      )) {
        _showPlaybackWaitMessage(
          'Buffering stream...',
          reason: 'controller_buffering',
          pausePlayback: false,
        );
      } else {
        _clearTransientBufferingWaitMessage(
          reason: 'controller_buffering_grace',
        );
      }
      return;
    }
    if (_media3PersistentBufferingStreakTicks <= 0) {
      _bufferingWatchdogTicks = 0;
      _verifiedTransientBufferingHolds = 0;
      _persistentBufferingRecoveryEscapeArmed = false;
    } else {
      _verifiedTransientBufferingHolds = 0;
      final escapeTickLimit =
          _persistentBufferingAnchorEscapeTickLimitForSource(_activeSource);
      _bufferingWatchdogTicks = math.max(
        _bufferingWatchdogTicks,
        math.min(_media3PersistentBufferingStreakTicks, escapeTickLimit),
      );
    }

    final publicIptvSource =
        _activeSource != null && _isPublicIptvSource(_activeSource!);

    final exoMissingVideoSurface =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            controller.isPlaying &&
            position >= const Duration(seconds: 3) &&
            controller.duration > Duration.zero &&
            controller.size == Size.zero &&
            _progressItem?.type != MediaType.music;
    if (exoMissingVideoSurface) {
      if (_isSuspiciousProgressClockJump(
        position,
        reason: 'black_video_watchdog',
        log: true,
      )) {
        DiagnosticLog.add(
          'native black video watchdog held suspicious player clock provider=${_activeSource?.providerId} engine=${controller.engine.id} position=${position.inSeconds}s lastKnown=${_lastKnownPlaybackPosition.inSeconds}s',
        );
        _blackVideoWatchdogTicks = 0;
        _stallWatchdogTicks = 0;
        _deadPauseTicks = 0;
        _bufferingWatchdogTicks = 0;
        _lastWatchdogPosition = _lastIntegrityPosition ?? _lastWatchdogPosition;
        _clearPlaybackWaitMessage(reason: 'black_video_suspicious_clock');
        return;
      }
      final integrityPosition = _lastIntegrityPosition;
      final visualClockAdvanced = position >
              _lastWatchdogPosition + const Duration(milliseconds: 850) ||
          (integrityPosition != null &&
              position > integrityPosition + const Duration(milliseconds: 850));
      if (visualClockAdvanced && _blackVideoWatchdogTicks < 2) {
        _blackVideoWatchdogTicks += 1;
        _stallWatchdogTicks = 0;
        _deadPauseTicks = 0;
        _bufferingWatchdogTicks = 0;
        DiagnosticLog.add(
          'native missing video surface held transient progress provider=${_activeSource?.providerId} engine=${controller.engine.id} position=${position.inSeconds}s duration=${controller.duration.inSeconds}s reason=missing_video_surface_progressing_hold',
        );
        _lastWatchdogPosition = position;
        _clearPlaybackWaitMessage(
          reason: 'missing_video_surface_progressing_hold',
        );
        return;
      }
      _blackVideoWatchdogTicks += 1;
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      final elapsed = _stallWatchdogInterval * _blackVideoWatchdogTicks;
      if (_blackVideoWatchdogTicks == 1) {
        DiagnosticLog.add(
          'native black video watchdog waiting provider=${_activeSource?.providerId} engine=${controller.engine.id} position=${position.inSeconds}s duration=${controller.duration.inSeconds}s size=0x0',
        );
      }
      final recoveryPosition = _effectiveRecoveryPosition(position);
      if (_shouldHoldBlackVideoSurfaceRefresh(
        controller,
        _activeSource,
        recoveryPosition,
      )) {
        _holdBlackVideoSurfaceRefresh(
          controller,
          recoveryPosition,
          'black_video_watchdog_hold_proven_source',
        );
        return;
      }
      _showPlaybackWaitMessage(
        'Refreshing video surface...',
        reason: 'black_video_watchdog',
      );
      final zeroMetadataResume = _activeSourceHasZeroClockMetadata &&
          (position >= const Duration(seconds: 3) ||
              _lastKnownPlaybackPosition >= const Duration(seconds: 3));
      if ((zeroMetadataResume || elapsed >= _blackVideoWatchdogWindow) &&
          AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
        DiagnosticLog.add(
          'native black video watchdog provider=${_activeSource?.providerId} engine=${controller.engine.id} position=${position.inSeconds}s elapsed=${elapsed.inSeconds}s action=refresh-surface zeroMetadataResume=$zeroMetadataResume',
        );
        unawaited(_recoverFromBlackVideo(recoveryPosition));
      }
      _lastWatchdogPosition = position;
      return;
    }
    _blackVideoWatchdogTicks = 0;

    if (!controller.isPlaying) {
      if (_exitConfirmationOpen) {
        _lastWatchdogPosition = position;
        _stallWatchdogTicks = 0;
        _deadPauseTicks = 0;
        _bufferingWatchdogTicks = 0;
        _resetTransientPlaybackDebounce();
        _clearPlaybackWaitMessage(reason: 'exit_confirmation');
        return;
      }
      if (_userPaused) {
        _lastWatchdogPosition = position;
        _stallWatchdogTicks = 0;
        _deadPauseTicks = 0;
        _bufferingWatchdogTicks = 0;
        _resetTransientPlaybackDebounce();
        _clearPlaybackWaitMessage(reason: 'user_paused');
        return;
      }
      _deadPauseTicks += 1;
      final now = DateTime.now();
      _deadPauseFirstSeenAt ??= now;
      final deadPauseElapsed = now.difference(_deadPauseFirstSeenAt!);
      DiagnosticLog.add(
        'native playback inactive provider=${_activeSource?.providerId} tick=$_deadPauseTicks position=${position.inSeconds}s elapsedMs=${deadPauseElapsed.inMilliseconds}',
      );
      if (deadPauseElapsed < _deadPauseRecoveryGrace) {
        _showPlaybackWaitMessage(
          'Buffering stream...',
          reason: 'dead_pause_grace',
          pausePlayback: false,
        );
        return;
      }
      if (AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
        _showPlaybackWaitMessage(
          'Recovering playback...',
          reason: 'dead_pause_recovery',
        );
        unawaited(
          _recoverFromPlaybackStall(
            _effectiveRecoveryPosition(position),
            skipSameSource: false,
            skipProvider: false,
            forceSourceAdvance: false,
          ),
        );
      }
      return;
    }

    _deadPauseTicks = 0;
    _deadPauseFirstSeenAt = null;
    if (_media3ResumeAnchorIsVisiblyWrong(controller)) {
      final source = _activeSource;
      final recoveryPosition = _effectiveRecoveryPosition(
        _resumeProgressAnchorPosition,
      );
      DiagnosticLog.add(
        'native media3 resume anchor mismatch provider=${source?.providerId} '
        'position=${position.inSeconds}s anchor=${_resumeProgressAnchorPosition.inSeconds}s '
        'recovery=${recoveryPosition.inSeconds}s action=advance_source',
      );
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      _persistentBufferingRecoveryEscapeArmed = false;
      _resetTransientPlaybackDebounce();
      if (source != null) {
        _markRuntimeSourceFailure(source, 'resume_anchor_clock_mismatch');
        _excludeResumeRecoveryQualityAfterRuntimeFailure(
          source,
          engine: controller.engine,
          recoveryPosition: recoveryPosition,
        );
      }
      _showPlaybackWaitMessage(
        'Recovering playback...',
        reason: 'resume_anchor_clock_mismatch',
      );
      unawaited(
        _recoverFromPlaybackStall(
          recoveryPosition,
          skipSameSource: true,
          skipProvider: true,
          forceSourceAdvance: true,
        ),
      );
      return;
    }
    if (_isSuspiciousProgressClockJump(
      position,
      reason: 'watchdog_progress',
      log: true,
    )) {
      DiagnosticLog.add(
        'native watchdog progress held suspicious player clock provider=${_activeSource?.providerId} engine=${controller.engine.id} position=${position.inSeconds}s lastKnown=${_lastKnownPlaybackPosition.inSeconds}s',
      );
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      if (_media3PersistentBufferingStreakTicks <= 0) {
        _bufferingWatchdogTicks = 0;
        _persistentBufferingRecoveryEscapeArmed = false;
      }
      _resetTransientPlaybackDebounce();
      _lastWatchdogPosition = _lastIntegrityPosition ?? _lastWatchdogPosition;
      _clearPlaybackWaitMessage(reason: 'watchdog_suspicious_clock');
      return;
    }
    final moved = (position - _lastWatchdogPosition).abs() >
        const Duration(milliseconds: 850);
    _lastWatchdogPosition = position;
    if (moved) {
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      if (_media3PersistentBufferingStreakTicks <= 0) {
        _bufferingWatchdogTicks = 0;
        _persistentBufferingRecoveryEscapeArmed = false;
        _clearPlaybackWaitMessage(reason: 'playback_progress');
      } else {
        final escapeTickLimit =
            _persistentBufferingAnchorEscapeTickLimitForSource(_activeSource);
        _bufferingWatchdogTicks = math.max(
          _bufferingWatchdogTicks,
          math.min(_media3PersistentBufferingStreakTicks, escapeTickLimit),
        );
        DiagnosticLog.add(
          'native media3 persistent buffering moved progress held provider=${_activeSource?.providerId} ticks=$_media3PersistentBufferingStreakTicks healthy=$_media3PersistentBufferingHealthySamples/4 position=${position.inSeconds}s action=retain_watchdog',
        );
      }
      _resetTransientPlaybackDebounce();
      _maybeRecordDeferredLibVlcOpenSuccess(
        controller,
        reason: 'watchdog_playback_progress',
      );
      _rememberVerifiedSource(controller, position);
      return;
    }

    if (publicIptvSource &&
        controller.engine == _NativePlaybackEngine.exoplayer) {
      _stallWatchdogTicks += 1;
      if (_stallWatchdogTicks < 6) {
        DiagnosticLog.add(
          'native live tv stall grace provider=${_activeSource?.providerId} tick=$_stallWatchdogTicks position=${position.inSeconds}s engine=${controller.engine.id}',
        );
        _clearPlaybackWaitMessage(reason: 'live_tv_stall_grace');
        return;
      }
    } else {
      _stallWatchdogTicks += 1;
    }

    final now = DateTime.now();
    final firstSeen = _noProgressFirstSeenAt;
    if (firstSeen == null) {
      _noProgressFirstSeenAt = now;
      _noProgressFirstSeenPosition = position;
    } else if (position - _noProgressFirstSeenPosition >
        const Duration(milliseconds: 750)) {
      _resetTransientPlaybackDebounce();
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _clearPlaybackWaitMessage(reason: 'playback_progress_debounced');
      return;
    }
    final noProgressElapsed = _noProgressFirstSeenAt == null
        ? Duration.zero
        : now.difference(_noProgressFirstSeenAt!);
    final isDirectHealthySource =
        _activeSource?.sourceClass != PlaybackSourceClass.p2p &&
            !_isLiveTvMode &&
            !publicIptvSource;
    if (isDirectHealthySource &&
        _playbackCadenceClockUnstable &&
        noProgressElapsed < _transientPlaybackRecoveryGrace) {
      if (_stallWatchdogTicks == 1) {
        DiagnosticLog.add(
          'native playback no-progress held unstable clock provider=${_activeSource?.providerId} position=${position.inSeconds}s stable=${_lastCrediblePlaybackPosition.inSeconds}s elapsedMs=${noProgressElapsed.inMilliseconds} engine=${controller.engine.id} reason=playback_no_progress_unstable_clock',
        );
      }
      _stallWatchdogTicks = 0;
      _deadPauseTicks = 0;
      _bufferingWatchdogTicks = 0;
      if (_lastCrediblePlaybackPosition > Duration.zero) {
        _lastWatchdogPosition = _lastCrediblePlaybackPosition;
      }
      _clearPlaybackWaitMessage(reason: 'playback_no_progress_unstable_clock');
      return;
    }
    if (isDirectHealthySource &&
        noProgressElapsed < _transientPlaybackRecoveryGrace) {
      if (_stallWatchdogTicks == 1) {
        DiagnosticLog.add(
          'native playback no-progress grace provider=${_activeSource?.providerId} position=${position.inSeconds}s elapsedMs=${noProgressElapsed.inMilliseconds} engine=${controller.engine.id}',
        );
      }
      _clearTransientBufferingWaitMessage(reason: 'playback_no_progress_grace');
      return;
    }

    final stallRecoveryTickLimit =
        _stallRecoveryTickLimitForSource(_activeSource);
    if (_stallWatchdogTicks < stallRecoveryTickLimit) {
      DiagnosticLog.add(
        'native source stall grace provider=${_activeSource?.providerId} tick=$_stallWatchdogTicks limit=$stallRecoveryTickLimit position=${position.inSeconds}s',
      );
      _showPlaybackWaitMessage(
        'Buffering stream...',
        reason: 'source_stall_grace',
        pausePlayback: false,
      );
      return;
    }
    if (_stallWatchdogTicks >= stallRecoveryTickLimit &&
        AppState.playerBehaviorSettings.value.autoSwitchOnStall) {
      _showPlaybackWaitMessage(
        'Recovering playback...',
        reason: 'stall_recovery',
      );
      unawaited(
        _recoverFromPlaybackStall(
          _effectiveRecoveryPosition(position),
          skipSameSource: false,
          skipProvider: false,
          forceSourceAdvance: false,
        ),
      );
    }
  }

  void _trackLastKnownPlaybackPosition() {
    final controller = _controller;
    if (controller == null ||
        !controller.isInitialized ||
        controller.hasError) {
      return;
    }

    final duration = controller.duration;
    final position = _resumeAnchoredPlaybackPosition(controller);
    if (duration.inSeconds > 0) {
      _lastKnownPlaybackDuration = duration;
      _maybeReloadSkipSegmentsWithDuration(duration);
    }
    if (position.inSeconds < 3) return;
    if (_playbackCadenceClockUnstable) {
      if (position.inSeconds != _unstableClockProgressSkipLogSecond) {
        _unstableClockProgressSkipLogSecond = position.inSeconds;
        DiagnosticLog.add(
          'native progress anchor skipped reason=unstable_playback_clock position=${position.inSeconds}s stable=${_lastKnownPlaybackPosition.inSeconds}s',
        );
      }
      return;
    }
    final trustedControllerClock =
        controller.isPlaying && !controller.isBuffering;
    final staleStateButVisibleProgress = !trustedControllerClock &&
        _shouldTrustVisibleProgressClock(controller, position);
    if (!trustedControllerClock && !staleStateButVisibleProgress) {
      if (position.inSeconds != _untrustedClockProgressSkipLogSecond) {
        _untrustedClockProgressSkipLogSecond = position.inSeconds;
        DiagnosticLog.add(
          'native progress anchor skipped reason=untrusted_decoder_clock position=${position.inSeconds}s stable=${_lastKnownPlaybackPosition.inSeconds}s playing=${controller.isPlaying} buffering=${controller.isBuffering}',
        );
      }
      return;
    }
    if (_isSuspiciousProgressClockJump(position, reason: 'track_last_known')) {
      return;
    }
    if (staleStateButVisibleProgress &&
        position.inSeconds != _untrustedClockProgressSkipLogSecond) {
      _untrustedClockProgressSkipLogSecond = position.inSeconds;
      DiagnosticLog.add(
        'native progress anchor accepted reason=visible_decoder_progress position=${position.inSeconds}s stable=${_lastKnownPlaybackPosition.inSeconds}s playing=${controller.isPlaying} buffering=${controller.isBuffering}',
      );
    }
    if (position > _lastKnownPlaybackPosition) {
      _lastKnownPlaybackPosition = position;
    }
  }

  bool _shouldTrustVisibleProgressClock(
    _NativePlaybackController controller,
    Duration position,
  ) {
    if (!controller.isInitialized || controller.hasError) return false;
    if (_isLiveTvMode) return false;
    if (position.inSeconds < 3) return false;
    final movingForward = position > _lastKnownPlaybackPosition;
    if (!movingForward) return false;
    final boundedForwardStep = _lastKnownPlaybackPosition <= Duration.zero ||
        position - _lastKnownPlaybackPosition <= const Duration(seconds: 12);
    if (!boundedForwardStep) return false;
    if (_resumeProgressAnchorPosition > Duration.zero &&
        position <
            _resumeProgressAnchorPosition - const Duration(seconds: 10)) {
      return false;
    }
    final duration = _bestKnownProgressDuration(controller);
    if (duration > const Duration(seconds: 20) &&
        position >= duration - const Duration(seconds: 1)) {
      return false;
    }
    if (controller.size == Size.zero) return false;
    if (_activeSourceHasZeroClockMetadata) return false;
    if (_playbackCadenceClockUnstable) return false;
    if (_isSuspiciousProgressClockJump(
      position,
      reason: 'visible_progress_clock',
    )) {
      return false;
    }
    return true;
  }

  bool _shouldTrustLibVlcContinuousTsProgress(
    _NativePlaybackController? controller,
    Duration position,
  ) {
    if (controller == null) return false;
    if (controller.engine != _NativePlaybackEngine.libvlc) return false;
    if (!_libVlcContinuousTsActive ||
        !_libVlcContinuousTsRelayProofReady ||
        _libVlcContinuousTsTimelineOffset <= Duration.zero) {
      return false;
    }
    if (!controller.isInitialized ||
        controller.hasError ||
        !controller.isPlaying ||
        controller.isBuffering) {
      return false;
    }
    if (position < _libVlcContinuousTsTimelineOffset) return false;
    if (!_hasSustainedLibVlcContinuousTsPlaybackProof(controller)) {
      return false;
    }
    final previous = _lastKnownPlaybackPosition;
    if (previous > Duration.zero &&
        position < previous - const Duration(seconds: 3)) {
      return false;
    }
    return true;
  }

  bool _shouldResetLibVlcContinuousTsIntegrityBaseline(
    _NativePlaybackController controller,
    Duration position,
  ) {
    if (!_shouldTrustLibVlcContinuousTsProgress(controller, position)) {
      return false;
    }
    final previous = _lastIntegrityPosition;
    final previousAt = _lastIntegritySampleAt;
    if (previous == null || previousAt == null) return true;
    if (position <= previous) return false;
    final wallDeltaMs = DateTime.now().difference(previousAt).inMilliseconds;
    final positionDelta = position - previous;
    if (positionDelta <= const Duration(seconds: 2)) return false;
    if (wallDeltaMs <= 1500) return false;
    final proofSeconds = _libVlcContinuousTsPlaybackProofSeconds(controller);
    if (proofSeconds < 8) return false;
    final maxExpectedForward = Duration(
      seconds: proofSeconds + 18,
    );
    if (positionDelta > maxExpectedForward) return false;
    return true;
  }

  void _maybeReloadSkipSegmentsWithDuration(Duration duration) {
    if (!_skipSegmentsSupported ||
        duration <= Duration.zero ||
        _skipSegmentLookupDuration > Duration.zero) {
      return;
    }
    if ((_skipSegmentTmdbId == null && _skipSegmentImdbId == null) ||
        _skipSegmentSeason == null ||
        _skipSegmentEpisode == null) {
      return;
    }
    _skipSegmentLookupDuration = duration;
    unawaited(_loadSkipSegments());
  }

  Duration _libVlcContinuousTsAbsolutePosition(
    _NativePlaybackController? controller,
  ) {
    final rawPosition = controller?.position ?? Duration.zero;
    if (controller?.engine != _NativePlaybackEngine.libvlc ||
        !_libVlcContinuousTsActive ||
        _libVlcContinuousTsTimelineOffset <= Duration.zero) {
      return rawPosition;
    }
    final activeTimeline = _activeMobileLibVlcSessionTimeline;
    if (activeTimeline != null) {
      return activeTimeline.absolutePlaybackPosition;
    }
    return _libVlcContinuousTsTimelineOffset + rawPosition;
  }

  Duration _resumeAnchoredPlaybackPosition(
    _NativePlaybackController? controller,
  ) {
    final rawControllerPosition = controller?.position ?? Duration.zero;
    final controllerPosition = _libVlcContinuousTsAbsolutePosition(controller);
    if (controller == null) {
      return controllerPosition;
    }
    final usesLibVlcContinuousTsLocalClock =
        controller.engine == _NativePlaybackEngine.libvlc &&
            _libVlcContinuousTsActive &&
            _libVlcContinuousTsTimelineOffset > Duration.zero;
    if (_resumeProgressAnchorPosition <= Duration.zero) {
      return controllerPosition;
    }
    if (usesLibVlcContinuousTsLocalClock) {
      if (rawControllerPosition.inSeconds != _resumeProgressAnchorLogSecond) {
        _resumeProgressAnchorLogSecond = rawControllerPosition.inSeconds;
        DiagnosticLog.add(
          'native libvlc continuous-ts timeline anchored raw=${rawControllerPosition.inSeconds}s offset=${_libVlcContinuousTsTimelineOffset.inSeconds}s absolute=${controllerPosition.inSeconds}s',
        );
      }
      if (controllerPosition < _resumeProgressAnchorPosition) {
        return _resumeProgressAnchorPosition;
      }
      _resumeProgressAnchorPosition = Duration.zero;
      _resumeProgressAnchorLogSecond = -1;
      return controllerPosition;
    }
    if (controllerPosition >= _resumeProgressAnchorPosition) {
      _resumeProgressAnchorPosition = Duration.zero;
      _resumeProgressAnchorLogSecond = -1;
      return controllerPosition;
    }
    if (controllerPosition >=
        _resumeProgressAnchorPosition - const Duration(seconds: 10)) {
      return _resumeProgressAnchorPosition;
    }
    if (controllerPosition <= const Duration(seconds: 10) &&
        controllerPosition.inSeconds != _resumeProgressAnchorLogSecond) {
      _resumeProgressAnchorLogSecond = controllerPosition.inSeconds;
      DiagnosticLog.add(
        'native resume-local progress waiting for media seek engine=${controller.engine.id} raw=${controllerPosition.inSeconds}s anchor=${_resumeProgressAnchorPosition.inSeconds}s',
      );
    }
    return controllerPosition;
  }

  Duration _bestKnownProgressPosition(
    _NativePlaybackController? controller,
    Duration duration,
  ) {
    var controllerPosition = _resumeAnchoredPlaybackPosition(controller);
    Duration? acceptedSeekPosition;
    if (controller?.engine == _NativePlaybackEngine.libvlc &&
        _libVlcContinuousTsActive &&
        _libVlcSeekSettlementBarrier.isSettling) {
      final nativePosition = controllerPosition;
      controllerPosition = _libVlcSeekSettlementBarrier.acceptedPosition(
        nativePosition: nativePosition,
        observedAt: DateTime.now(),
      );
      acceptedSeekPosition = controllerPosition;
      if (controllerPosition != nativePosition &&
          _libVlcSeekSettlementLoggedGeneration !=
              _libVlcSeekSettlementBarrier.generation) {
        _libVlcSeekSettlementLoggedGeneration =
            _libVlcSeekSettlementBarrier.generation;
        DiagnosticLog.add(
          'native libvlc seek settlement held stale clock '
          'seekSettlementGeneration=${_libVlcSeekSettlementBarrier.generation} '
          'surfaceGeneration=${_mobileLibVlcCoordinator?.generation ?? -1} '
          'raw=${nativePosition.inSeconds}s '
          'anchor=${controllerPosition.inSeconds}s',
        );
      }
    }
    final controllerClockTrusted = controller == null ||
        (controller.isInitialized &&
            !controller.hasError &&
            controller.isPlaying &&
            !controller.isBuffering);
    final waitingForResumeSeek = controller != null &&
        _resumeProgressAnchorPosition > Duration.zero &&
        controllerPosition <
            _resumeProgressAnchorPosition - const Duration(seconds: 10);
    final visibleProgressClockTrusted = controller != null &&
        _shouldTrustVisibleProgressClock(controller, controllerPosition);
    final libVlcContinuousTsProgressTrusted =
        _shouldTrustLibVlcContinuousTsProgress(controller, controllerPosition);
    var position = (controllerClockTrusted ||
                visibleProgressClockTrusted ||
                libVlcContinuousTsProgressTrusted) &&
            controllerPosition > Duration.zero
        ? controllerPosition
        : waitingForResumeSeek
            ? Duration.zero
            : _lastKnownPlaybackPosition;
    if (!waitingForResumeSeek &&
        !libVlcContinuousTsProgressTrusted &&
        _lastKnownPlaybackPosition > Duration.zero &&
        (position <= Duration.zero ||
            _lastKnownPlaybackPosition > position ||
            (position - _lastKnownPlaybackPosition).abs() >
                const Duration(seconds: 10))) {
      position = _lastKnownPlaybackPosition;
    }
    if (acceptedSeekPosition != null) {
      position = _libVlcSeekSettlementBarrier.constrainComputedPosition(
        computedPosition: position,
        acceptedNativePosition: acceptedSeekPosition,
      );
      if (!_libVlcSeekSettlementBarrier.isSettling) {
        _lastKnownPlaybackPosition = position;
        _lastCrediblePlaybackPosition = position;
        _lastCrediblePlaybackPositionAt = DateTime.now();
      }
    }
    if (duration > const Duration(seconds: 20) &&
        position >= duration - const Duration(seconds: 1)) {
      return duration - const Duration(seconds: 1);
    }
    return position;
  }

  Duration _bestKnownProgressDuration(_NativePlaybackController? controller) {
    final controllerDuration = controller?.duration ?? Duration.zero;
    if (controllerDuration > Duration.zero &&
        !_durationLooksLikeShortVodPlaceholder(controllerDuration)) {
      return controllerDuration;
    }
    if (_lastKnownPlaybackDuration > Duration.zero) {
      return _lastKnownPlaybackDuration;
    }
    final fallbackSeconds = _fallbackProgressDurationSeconds();
    if (fallbackSeconds != null && fallbackSeconds > 0) {
      return Duration(seconds: fallbackSeconds);
    }
    final item = _progressItem;
    if (item == null) return Duration.zero;
    return const Duration(minutes: 45);
  }

  Duration _qualitySwitchResumePosition() {
    _trackLastKnownPlaybackPosition();
    final duration = _bestKnownProgressDuration(_controller);
    final position = _bestKnownProgressPosition(_controller, duration);
    DiagnosticLog.add(
      'native quality switch resume anchor position=${position.inSeconds}s duration=${duration.inSeconds}s',
    );
    return position;
  }

  void _resetPlaybackIntegritySample() {
    _lastIntegritySampleAt = null;
    _lastIntegrityPosition = null;
    _media3RendererClockProofWasPending = false;
  }

  void _clearMedia3ResumeSeekSettleWindow() {
    _media3ResumeSeekSettleAnchor = Duration.zero;
    _media3ResumeSeekSettleUntil = null;
    _media3ResumeSeekSettleDrifts = 0;
  }

  void _resetCrediblePlaybackAnchor() {
    _lastCrediblePlaybackPosition = Duration.zero;
    _lastCrediblePlaybackPositionAt = null;
  }

  void _clearUnprovedResumePlaybackState({required String reason}) {
    final resumeAnchor = _resumeProgressAnchorPosition;
    final knownPosition = _lastKnownPlaybackPosition;
    final crediblePosition = _lastCrediblePlaybackPosition;
    final savedSecond = _lastSavedSecond;
    final integrityPosition = _lastIntegrityPosition;
    _resumeProgressAnchorPosition = Duration.zero;
    _resumeProgressAnchorLogSecond = -1;
    _deferredResumeSeekPosition = null;
    _deferredResumeSeekProviderId = null;
    _deferredResumeSeekAttempts = 0;
    _deferredResumeSeekInFlight = false;
    _deferredResumeSeekRequiresVisualProof = false;
    _lastKnownPlaybackPosition = Duration.zero;
    _lastCrediblePlaybackPosition = Duration.zero;
    _lastCrediblePlaybackPositionAt = null;
    _lastIntegrityPosition = null;
    _lastIntegritySampleAt = null;
    _media3RendererClockProofWasPending = false;
    _lastCadencePosition = Duration.zero;
    _lastCadenceSampleAt = null;
    _lastWatchdogPosition = Duration.zero;
    _lastSavedSecond = -1;
    _rendererRecoveryAnchorPosition = Duration.zero;
    _rendererRecoveryAnchorUntil = null;
    _clearMedia3ResumeSeekSettleWindow();
    _media3ResumeAnchorHadStartupVisualProof = false;
    DiagnosticLog.add(
      'native resume state cleared reason=$reason '
      'anchor=${resumeAnchor.inSeconds}s known=${knownPosition.inSeconds}s '
      'credible=${crediblePosition.inSeconds}s saved=$savedSecond '
      'integrity=${integrityPosition?.inSeconds ?? 0}s',
    );
  }

  void _rememberCrediblePlaybackAnchor(
    Duration position, {
    required String reason,
  }) {
    if (position < const Duration(seconds: 1)) return;
    if (position < _lastCrediblePlaybackPosition &&
        _lastCrediblePlaybackPosition - position > const Duration(seconds: 3)) {
      return;
    }
    _lastCrediblePlaybackPosition = position;
    _lastCrediblePlaybackPositionAt = DateTime.now();
  }

  Duration _heldPlaybackAnchor({Duration fallback = Duration.zero}) {
    final savedPosition = _lastSavedSecond >= 1
        ? Duration(seconds: _lastSavedSecond)
        : Duration.zero;
    for (final candidate in <Duration>[
      _lastCrediblePlaybackPosition,
      _lastKnownPlaybackPosition,
      _lastIntegrityPosition ?? Duration.zero,
      savedPosition,
      _resumeProgressAnchorPosition,
      fallback,
    ]) {
      if (candidate >= const Duration(seconds: 1)) {
        return candidate;
      }
    }
    return Duration.zero;
  }

  void _syncPlaybackIntegrity(_NativePlaybackController controller) {
    final item = _progressItem;
    final key = _playbackKey;
    if (item == null || key == null) {
      _resetPlaybackIntegritySample();
      return;
    }
    if (_integrityPlaybackKey != key) {
      _integrityPlaybackKey = key;
      _credibleWatchMilliseconds = (AppState.progressFor(
                item,
                playbackKey: key,
              )?.credibleWatchedSeconds ??
              0) *
          1000;
      _seekAbuseEvents = 0;
      _resetPlaybackIntegritySample();
    }
    final duration = _bestKnownProgressDuration(controller);
    final position = _bestKnownProgressPosition(controller, duration);
    if (!controller.isInitialized ||
        controller.hasError ||
        duration <= Duration.zero ||
        position <= Duration.zero) {
      final heldPosition = _heldPlaybackAnchor();
      _lastIntegritySampleAt = DateTime.now();
      _lastIntegrityPosition = heldPosition;
      if (position.inSeconds != _untrustedClockProgressSkipLogSecond) {
        _untrustedClockProgressSkipLogSecond = position.inSeconds;
        DiagnosticLog.add(
          'native progress anchor skipped reason=unavailable_decoder_clock position=${position.inSeconds}s stable=${heldPosition.inSeconds}s initialized=${controller.isInitialized} error=${controller.hasError} duration=${duration.inSeconds}s',
        );
      }
      return;
    }

    final libVlcContinuousTsProgressTrusted =
        _shouldTrustLibVlcContinuousTsProgress(controller, position);
    if ((!controller.isPlaying || controller.isBuffering) &&
        !libVlcContinuousTsProgressTrusted) {
      final heldPosition = _heldPlaybackAnchor(fallback: position);
      _lastIntegritySampleAt = DateTime.now();
      _lastIntegrityPosition = heldPosition;
      if (position.inSeconds != _untrustedClockProgressSkipLogSecond) {
        _untrustedClockProgressSkipLogSecond = position.inSeconds;
        DiagnosticLog.add(
          'native progress anchor skipped reason=untrusted_decoder_clock position=${position.inSeconds}s stable=${heldPosition.inSeconds}s playing=${controller.isPlaying} buffering=${controller.isBuffering}',
        );
      }
      return;
    }
    final media3RendererClockUnproven =
        _media3RendererClockIsUnproven(controller);
    if (media3RendererClockUnproven && !libVlcContinuousTsProgressTrusted) {
      _media3RendererClockProofWasPending = true;
      final heldPosition = _heldPlaybackAnchor(fallback: position);
      _lastIntegritySampleAt = DateTime.now();
      _lastIntegrityPosition = heldPosition;
      if (position.inSeconds != _untrustedClockProgressSkipLogSecond) {
        _untrustedClockProgressSkipLogSecond = position.inSeconds;
        DiagnosticLog.add(
          'native progress anchor skipped reason=media3_renderer_unproven_clock position=${position.inSeconds}s stable=${heldPosition.inSeconds}s playing=${controller.isPlaying} buffering=${controller.isBuffering}',
        );
      }
      return;
    }
    if (_media3RendererClockProofWasPending &&
        controller.engine == _NativePlaybackEngine.exoplayer) {
      _media3RendererClockProofWasPending = false;
      _lastIntegritySampleAt = DateTime.now();
      _lastIntegrityPosition = position;
      _untrustedClockProgressSkipLogSecond = -1;
      _rememberCrediblePlaybackAnchor(
        position,
        reason: 'media3_renderer_proof_trusted',
      );
      DiagnosticLog.add(
        'native progress integrity reset reason=media3_renderer_proof_trusted position=${position.inSeconds}s',
      );
      return;
    }
    _media3RendererClockProofWasPending = false;

    if (_shouldResetLibVlcContinuousTsIntegrityBaseline(controller, position)) {
      _lastIntegritySampleAt = DateTime.now();
      _lastIntegrityPosition = position;
      _lastKnownPlaybackPosition = position;
      _untrustedClockProgressSkipLogSecond = -1;
      _rememberCrediblePlaybackAnchor(
        position,
        reason: 'libvlc_continuous_ts_progress_trusted',
      );
      DiagnosticLog.add(
        'native progress integrity reset reason=libvlc_continuous_ts_progress_trusted position=${position.inSeconds}s',
      );
      return;
    }

    _creditPlaybackIntegrityPosition(position, reason: 'controller');
  }

  void _creditPlaybackIntegrityPosition(
    Duration position, {
    required String reason,
  }) {
    final now = DateTime.now();
    final previousAt = _lastIntegritySampleAt;
    final previousPosition = _lastIntegrityPosition;
    if (previousAt == null || previousPosition == null) {
      _lastIntegritySampleAt = now;
      _lastIntegrityPosition = position;
      _rememberCrediblePlaybackAnchor(position, reason: reason);
      return;
    }

    final wallDeltaMs = now.difference(previousAt).inMilliseconds;
    final positionDeltaMs =
        position.inMilliseconds - previousPosition.inMilliseconds;
    if (wallDeltaMs <= 250) return;
    if (positionDeltaMs <= 250) {
      _lastIntegritySampleAt = now;
      _lastIntegrityPosition = position;
      _rememberCrediblePlaybackAnchor(position, reason: reason);
      return;
    }

    final speed = math.max(_playbackSpeed, 1.0);
    final allowedDeltaMs = (wallDeltaMs * speed * 1.45 + 1250).round();
    if (positionDeltaMs > allowedDeltaMs) {
      _lastIntegritySampleAt = now;
      _lastIntegrityPosition = previousPosition;
      _rememberCrediblePlaybackAnchor(previousPosition, reason: 'held_$reason');
      if (positionDeltaMs > 5000) {
        _seekAbuseEvents += 1;
        if (_seekAbuseEvents == 1 || _seekAbuseEvents == 3) {
          DiagnosticLog.add(
            'native metrics integrity ignored jump positionDelta=${(positionDeltaMs / 1000).toStringAsFixed(1)}s wallDelta=${(wallDeltaMs / 1000).toStringAsFixed(1)}s stable=${_lastIntegrityPosition?.inSeconds ?? 0}s events=$_seekAbuseEvents',
          );
        }
      }
      return;
    }

    final credibleDeltaMs = math.min(
      positionDeltaMs,
      (wallDeltaMs * speed).round(),
    );
    _lastIntegritySampleAt = now;
    _lastIntegrityPosition = position;
    _rememberCrediblePlaybackAnchor(position, reason: reason);
    final beforeSeconds = _credibleWatchSeconds;
    _credibleWatchMilliseconds += credibleDeltaMs.clamp(0, 10000).toInt();
    final afterSeconds = _credibleWatchSeconds;
    if ((beforeSeconds == 0 && afterSeconds > 0) ||
        afterSeconds ~/ 60 > beforeSeconds ~/ 60) {
      DiagnosticLog.add(
        'native metrics integrity credited activeWatch=${afterSeconds}s delta=${(credibleDeltaMs / 1000).toStringAsFixed(1)}s reason=$reason',
      );
    }
  }

  Duration _stableProgressClockPosition(
    Duration position, {
    required String reason,
  }) {
    final previousPosition = _lastIntegrityPosition;
    if (!_isSuspiciousProgressClockJump(position, reason: reason, log: true) ||
        previousPosition == null) {
      return position;
    }

    final previousAt = _lastIntegritySampleAt;
    if (previousAt == null) return previousPosition;
    final wallDeltaMs = DateTime.now().difference(previousAt).inMilliseconds;
    if (wallDeltaMs <= 250) return previousPosition;
    if (_playbackCadenceClockUnstable) {
      if (_lastCrediblePlaybackPosition > Duration.zero) {
        return _lastCrediblePlaybackPosition;
      }
      return previousPosition;
    }
    final speed = math.max(_playbackSpeed, 1.0);
    final wallClockTarget = previousPosition +
        Duration(milliseconds: (wallDeltaMs * speed).round());
    if (wallClockTarget <= previousPosition) return previousPosition;
    return wallClockTarget < position ? wallClockTarget : previousPosition;
  }

  bool _isSuspiciousProgressClockJump(
    Duration position, {
    required String reason,
    bool log = false,
  }) {
    final previousAt = _lastIntegritySampleAt;
    final previousPosition = _lastIntegrityPosition;
    if (previousAt == null || previousPosition == null) return false;
    final wallDeltaMs = DateTime.now().difference(previousAt).inMilliseconds;
    final positionDeltaMs =
        position.inMilliseconds - previousPosition.inMilliseconds;
    if (wallDeltaMs <= 250 || positionDeltaMs <= 250) return false;

    final speed = math.max(_playbackSpeed, 1.0);
    final allowedDeltaMs = (wallDeltaMs * speed * 1.45 + 1250).round();
    if (positionDeltaMs <= allowedDeltaMs) return false;

    if (log) {
      DiagnosticLog.add(
        'native progress save held suspicious player clock reason=$reason position=${position.inSeconds}s stable=${previousPosition.inSeconds}s wallDeltaMs=$wallDeltaMs playbackDeltaMs=$positionDeltaMs',
      );
    }
    return true;
  }

  Duration _rendererRecoveryProgressSavePosition({
    required Duration rawPosition,
    required Duration stablePosition,
    required bool force,
    required bool completionObserved,
  }) {
    if (!force || completionObserved) return stablePosition;

    final hasRendererRecoveryAnchor = _inRendererRecoveryAnchorWindow &&
        _rendererRecoveryAnchorPosition >= const Duration(seconds: 3);
    if (hasRendererRecoveryAnchor) {
      final anchor = _rendererRecoveryAnchorPosition;
      final rawAheadOfAnchor =
          rawPosition - anchor > const Duration(seconds: 2);
      final anchorAheadOfRaw =
          anchor - rawPosition > const Duration(seconds: 2);
      final stableAheadOfAnchor =
          stablePosition - anchor > const Duration(seconds: 2);
      final anchorAheadOfStable =
          anchor - stablePosition > const Duration(seconds: 2);
      if (rawAheadOfAnchor ||
          anchorAheadOfRaw ||
          stableAheadOfAnchor ||
          anchorAheadOfStable) {
        DiagnosticLog.add(
          'native progress save anchored reason=media3_renderer_recovery_anchor_window raw=${rawPosition.inSeconds}s stable=${stablePosition.inSeconds}s anchor=${anchor.inSeconds}s force=$force',
        );
        return anchor;
      }
    }

    final inRendererRecoveryWindow = _recoveringFromMedia3RendererDrift ||
        _escalatingMedia3RendererDrift ||
        _inRendererRecoveryAnchorWindow ||
        _playbackCadenceClockUnstable ||
        _resumeProgressAnchorPosition >= const Duration(seconds: 3);

    var anchor = Duration.zero;
    void considerAnchor(Duration candidate) {
      if (candidate < const Duration(seconds: 3)) return;
      if (candidate > rawPosition) return;
      if (candidate > anchor) anchor = candidate;
    }

    if (inRendererRecoveryWindow) {
      considerAnchor(_resumeProgressAnchorPosition);
      considerAnchor(_lastCrediblePlaybackPosition);
      considerAnchor(_lastKnownPlaybackPosition);
      final integrityPosition = _lastIntegrityPosition;
      if (integrityPosition != null) {
        considerAnchor(integrityPosition);
      }
      considerAnchor(stablePosition);

      if (anchor > Duration.zero &&
          rawPosition - anchor > const Duration(seconds: 2)) {
        DiagnosticLog.add(
          'native progress save anchored reason=media3_renderer_recovery_clock raw=${rawPosition.inSeconds}s stable=${stablePosition.inSeconds}s anchor=${anchor.inSeconds}s force=$force',
        );
        return anchor;
      }
    }

    if (rawPosition - stablePosition <= const Duration(seconds: 2)) {
      return stablePosition;
    }
    return stablePosition;
  }

  int get _credibleWatchSeconds => (_credibleWatchMilliseconds / 1000).floor();

  void _markManualSeekForIntegrity(
    Duration from,
    Duration to, {
    required String reason,
  }) {
    final forwardDelta = to - from;
    if (forwardDelta > const Duration(seconds: 2)) {
      _seekAbuseEvents += 1;
      if (_seekAbuseEvents == 1 || _seekAbuseEvents == 3) {
        DiagnosticLog.add(
          'native metrics integrity manual seek reason=$reason delta=${forwardDelta.inSeconds}s events=$_seekAbuseEvents',
        );
      }
    }
    _lastIntegritySampleAt = DateTime.now();
    _lastIntegrityPosition = to;
    _lastKnownPlaybackPosition = to;
    _lastCrediblePlaybackPosition = to;
    _lastCrediblePlaybackPositionAt = _lastIntegritySampleAt;
    _lastCadencePosition = to;
    _lastCadenceSampleAt = _lastIntegritySampleAt;
    _lastWatchdogPosition = to;
    _resumeProgressAnchorPosition = Duration.zero;
    _resumeProgressAnchorLogSecond = -1;
    _rendererRecoveryAnchorPosition = Duration.zero;
    _rendererRecoveryAnchorUntil = null;
    _clearPlaybackCadenceUnstableState();
    _untrustedClockProgressSkipLogSecond = -1;
    DiagnosticLog.add(
      'native progress anchor updated reason=manual_seek_anchor source=$reason position=${to.inSeconds}s',
    );
  }

  Duration _newerRecoveryAnchor(Duration current, Duration candidate) {
    if (candidate.inSeconds < 3) return current;
    if (current.inSeconds < 3 || candidate > current) return candidate;
    return current;
  }

  bool get _inRendererRecoveryAnchorWindow {
    final until = _rendererRecoveryAnchorUntil;
    return until != null && DateTime.now().isBefore(until);
  }

  void _beginRendererRecoveryAnchorWindow(
    Duration position, {
    required String reason,
  }) {
    if (position < const Duration(seconds: 3)) return;
    _rendererRecoveryAnchorPosition = position;
    _rendererRecoveryAnchorUntil =
        DateTime.now().add(const Duration(seconds: 18));
    DiagnosticLog.add(
      'native renderer recovery anchor window reason=$reason position=${position.inSeconds}s',
    );
  }

  Duration _media3RendererDriftRecoveryAnchor({
    required Duration heldPosition,
    required Duration observedPosition,
    required Duration correctedTarget,
  }) {
    final recoveryPosition = _effectiveRecoveryPosition(heldPosition);
    if (recoveryPosition >= const Duration(seconds: 3)) {
      return recoveryPosition;
    }

    var lowAnchor = Duration.zero;
    void considerLowAnchor(Duration candidate) {
      if (candidate >= const Duration(seconds: 1) &&
          candidate <= observedPosition &&
          candidate > lowAnchor) {
        lowAnchor = candidate;
      }
    }

    considerLowAnchor(_resumeProgressAnchorPosition);
    considerLowAnchor(_lastKnownPlaybackPosition);
    considerLowAnchor(_lastCrediblePlaybackPosition);
    final integrityPosition = _lastIntegrityPosition;
    if (integrityPosition != null) {
      considerLowAnchor(integrityPosition);
    }
    considerLowAnchor(heldPosition);
    considerLowAnchor(correctedTarget);
    if (lowAnchor > Duration.zero) {
      return lowAnchor;
    }

    return Duration.zero;
  }

  Duration _effectiveRecoveryPosition(Duration reportedPosition) {
    final translatedLibVlcPosition =
        _libVlcContinuousTsRecoveryPositionFromController();
    final stablePosition = _stableProgressClockPosition(
      reportedPosition,
      reason: 'recovery_anchor',
    );
    final hasRendererRecoveryAnchor = _inRendererRecoveryAnchorWindow &&
        _rendererRecoveryAnchorPosition >= const Duration(seconds: 3);
    if (_playbackCadenceClockUnstable) {
      var recoveryPosition = Duration.zero;
      if (hasRendererRecoveryAnchor) {
        recoveryPosition = _newerRecoveryAnchor(
          recoveryPosition,
          _rendererRecoveryAnchorPosition,
        );
      }
      recoveryPosition =
          _newerRecoveryAnchor(recoveryPosition, _lastCrediblePlaybackPosition);
      final integrityPosition = _lastIntegrityPosition;
      if (integrityPosition != null) {
        recoveryPosition =
            _newerRecoveryAnchor(recoveryPosition, integrityPosition);
      }
      if (_lastSavedSecond >= 3) {
        recoveryPosition = _newerRecoveryAnchor(
          recoveryPosition,
          Duration(seconds: _lastSavedSecond),
        );
      }
      recoveryPosition = _newerRecoveryAnchor(recoveryPosition, stablePosition);
      recoveryPosition =
          _newerRecoveryAnchor(recoveryPosition, translatedLibVlcPosition);
      return recoveryPosition;
    }
    var recoveryPosition = stablePosition;
    if (hasRendererRecoveryAnchor) {
      return _newerRecoveryAnchor(
        translatedLibVlcPosition,
        _rendererRecoveryAnchorPosition,
      );
    }
    recoveryPosition = _newerRecoveryAnchor(recoveryPosition, reportedPosition);
    recoveryPosition =
        _newerRecoveryAnchor(recoveryPosition, _lastKnownPlaybackPosition);
    if (_lastSavedSecond >= 3) {
      recoveryPosition = _newerRecoveryAnchor(
        recoveryPosition,
        Duration(seconds: _lastSavedSecond),
      );
    }
    recoveryPosition =
        _newerRecoveryAnchor(recoveryPosition, _lastCrediblePlaybackPosition);
    recoveryPosition =
        _newerRecoveryAnchor(recoveryPosition, translatedLibVlcPosition);
    return recoveryPosition;
  }

  Duration _libVlcContinuousTsRecoveryPositionFromController() {
    final controller = _controller;
    if (controller == null ||
        controller.engine != _NativePlaybackEngine.libvlc ||
        !_libVlcContinuousTsActive) {
      return Duration.zero;
    }
    return _resumeAnchoredPlaybackPosition(controller);
  }

  Duration _currentPlaybackResumeAnchor() {
    final controllerPosition = _controller?.position ?? Duration.zero;
    final reportedPosition = controllerPosition > Duration.zero
        ? controllerPosition
        : _lastKnownPlaybackPosition;
    return _effectiveRecoveryPosition(reportedPosition);
  }

  void _anchorNativeRecoveryProgress(
    Duration position, {
    required String reason,
  }) {
    if (position < const Duration(seconds: 3)) return;
    final now = DateTime.now();
    _lastKnownPlaybackPosition = position;
    _rememberCrediblePlaybackAnchor(position, reason: reason);
    _lastIntegritySampleAt = now;
    _lastIntegrityPosition = position;
    _lastWatchdogPosition = position;
    _lastCadencePosition = position;
    _lastCadenceSampleAt = now;
    _resumeProgressAnchorPosition = position;
    _resumeProgressAnchorLogSecond = -1;
    _beginRendererRecoveryAnchorWindow(position, reason: reason);
    DiagnosticLog.add(
      'native recovery progress anchored reason=$reason position=${position.inSeconds}s',
    );
  }

  bool _media3RendererDriftActiveSourceMatches(PlaybackSource source) {
    final activeSource = _activeSource;
    return activeSource != null &&
        activeSource.providerId == source.providerId &&
        activeSource.url == source.url;
  }

  bool _shouldHoldMedia3RendererDriftOnCurrentSource(
    _NativePlaybackController controller,
    PlaybackSource source,
    Duration anchor,
    DateTime now, {
    required bool repairedSameSource,
    required bool severeRendererDrift,
    required Duration unstableFor,
    required double ratio,
  }) {
    if (_playerClosing ||
        !mounted ||
        controller.hasError ||
        !controller.isInitialized ||
        anchor < const Duration(seconds: 3) ||
        !_media3RendererDriftActiveSourceMatches(source)) {
      return false;
    }
    final hasRuntimeProof = _activeSourceVerifiedForSession ||
        _sourceHasVisualPlaybackProof(controller) ||
        _sourceCredibleWatchSeconds >=
            _verifiedSourcePlaybackProofMinimum(
              source,
              publicIptvSource: _isPublicIptvSource(source),
            ).inSeconds ||
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
        _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
        _lastSavedSecond >= 5;
    if (!hasRuntimeProof) return false;
    final sourceKey = _playbackSourceRuntimeKey(source);
    final holdCount = _media3RendererDriftHoldSourceKey == sourceKey
        ? _media3RendererDriftHoldCountForSource
        : 0;
    final repeatedMedia3DirectHlsDrift = severeRendererDrift &&
        controller.engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        holdCount >= 1;
    if (repeatedMedia3DirectHlsDrift) {
      return false;
    }
    final repeatedDirectHlsSessionDrift =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            source.sourceClass == PlaybackSourceClass.direct &&
            _isHlsSource(source) &&
            _media3DirectHlsRendererDriftHoldCount >= 1 &&
            ratio >= 2.25;
    if (repeatedDirectHlsSessionDrift) {
      return false;
    }
    final severeAutoMedia3DirectHlsDrift = severeRendererDrift &&
        controller.engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _shouldAvoidLibVlcRendererDriftEscalation(source);
    if (severeAutoMedia3DirectHlsDrift) {
      return false;
    }
    final earlyMedia3DirectHlsResumeDrift = severeRendererDrift &&
        controller.engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _media3ResumeAnchorHadStartupVisualProof &&
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) &&
        !_hasLongVisibleMedia3SessionProof(controller) &&
        _sourceCredibleWatchSeconds < 45;
    if (earlyMedia3DirectHlsResumeDrift) {
      return false;
    }
    final manualMedia3DirectHlsSevereDrift = severeRendererDrift &&
        controller.engine == _NativePlaybackEngine.exoplayer &&
        _effectivePlaybackEngine == _NativePlaybackEngine.exoplayer.id &&
        _shouldAvoidLibVlcRendererDriftEscalation(source);
    if (manualMedia3DirectHlsSevereDrift) {
      return unstableFor < const Duration(seconds: 2) &&
          _playbackCadenceConsecutiveJumpEvents < 2;
    }
    final hasLongVisibleSessionProof =
        _hasLongVisibleMedia3SessionProof(controller);
    if (hasLongVisibleSessionProof) {
      return unstableFor < const Duration(seconds: 12) &&
          _playbackCadenceConsecutiveJumpEvents < 6;
    }
    final hasActiveVisualProof =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            controller.isPlaying &&
            !controller.isBuffering &&
            _sourceHasRawVisualPlaybackProof(controller);
    if (hasActiveVisualProof) {
      if (severeRendererDrift) {
        return unstableFor < const Duration(seconds: 5) &&
            _playbackCadenceConsecutiveJumpEvents < 4;
      }
      return true;
    }
    if (severeRendererDrift && unstableFor >= const Duration(seconds: 3)) {
      return false;
    }
    if (holdCount >= 1) {
      return false;
    }
    if (_playbackCadenceConsecutiveJumpEvents >= 3) {
      return false;
    }

    final lastRepairAt = _lastMedia3RendererDriftRepairAt;
    final repairedRecently = lastRepairAt != null &&
        now.difference(lastRepairAt) < const Duration(seconds: 45);
    final holdWindow = repairedSameSource || repairedRecently
        ? const Duration(seconds: 45)
        : const Duration(seconds: 15);
    return unstableFor < holdWindow;
  }

  bool _hasLongVisibleMedia3SessionProof(
    _NativePlaybackController controller,
  ) {
    return controller.engine == _NativePlaybackEngine.exoplayer &&
        controller.isPlaying &&
        !controller.isBuffering &&
        (_activeSourceVerifiedForSession ||
            _sourceCredibleWatchSeconds >=
                const Duration(seconds: 45).inSeconds ||
            _lastKnownPlaybackPosition >= const Duration(seconds: 45) ||
            _lastCrediblePlaybackPosition >= const Duration(seconds: 45) ||
            _lastSavedSecond >= 45);
  }

  void _holdMedia3RendererDriftOnCurrentSource(
    _NativePlaybackController controller,
    PlaybackSource source, {
    required Duration anchor,
    required Duration observedPosition,
    required Duration heldPosition,
    required double ratio,
    required Duration unstableFor,
  }) {
    final sourceKey = _playbackSourceRuntimeKey(source);
    if (_media3RendererDriftHoldSourceKey == sourceKey) {
      _media3RendererDriftHoldCountForSource += 1;
    } else {
      _media3RendererDriftHoldSourceKey = sourceKey;
      _media3RendererDriftHoldCountForSource = 1;
    }
    if (controller.engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source)) {
      _recordMedia3DirectHlsRendererDriftRisk(source);
      _media3DirectHlsRendererDriftHoldCount += 1;
    }
    _anchorNativeRecoveryProgress(
      anchor,
      reason: 'media3_renderer_drift_hold_current_source',
    );
    _bufferingWatchdogTicks = 0;
    _stallWatchdogTicks = 0;
    _deadPauseTicks = 0;
    _lastWatchdogPosition = anchor;
    final shouldCorrectVisibleClock =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            source.sourceClass == PlaybackSourceClass.direct &&
            _isHlsSource(source) &&
            !_hasLongVisibleMedia3SessionProof(controller) &&
            observedPosition - anchor > const Duration(seconds: 2) &&
            !_recoveringFromMedia3RendererDrift &&
            !_recoveringFromStall &&
            mounted &&
            !_playerClosing &&
            identical(_controller, controller);
    if (shouldCorrectVisibleClock) {
      _lastCadencePosition = anchor;
      unawaited(
        _seekControllerToPlaybackPosition(
          controller,
          anchor,
          reason: 'media3_renderer_drift_clock_correction',
          fromPosition: observedPosition,
          allowContinuousTsReopen: false,
        ).then((sameController) {
          DiagnosticLog.add(
            'native playback cadence renderer drift clock corrected provider=${source.providerId} observed=${observedPosition.inSeconds}s anchor=${anchor.inSeconds}s sameController=$sameController action=seek_back_to_anchor',
          );
        }).catchError((Object error) {
          DiagnosticLog.add(
            'native playback cadence renderer drift clock correction failed provider=${source.providerId} observed=${observedPosition.inSeconds}s anchor=${anchor.inSeconds}s errorType=${error.runtimeType}',
          );
        }),
      );
    } else {
      _lastCadencePosition = observedPosition;
    }
    _playbackCadenceConsecutiveJumpEvents = 0;
    _clearTransientBufferingWaitMessage(
      reason: 'media3_renderer_drift_hold_current_source',
    );
    DiagnosticLog.add(
      'native playback cadence renderer drift held current source provider=${source.providerId} engine=${controller.engine.id} observed=${observedPosition.inSeconds}s stable=${heldPosition.inSeconds}s anchor=${anchor.inSeconds}s ratio=${ratio.toStringAsFixed(2)} unstableFor=${unstableFor.inSeconds}s holds=$_media3RendererDriftHoldCountForSource directHlsSessionHolds=$_media3DirectHlsRendererDriftHoldCount action=hold_current_source_after_renderer_drift',
    );
  }

  bool _canStartMedia3RendererDriftRepair({
    required PlaybackSource source,
    required Duration anchor,
    required DateTime now,
  }) {
    if (_playerClosing ||
        !mounted ||
        _recoveringFromMedia3RendererDrift ||
        _recoveringFromStall ||
        anchor < const Duration(seconds: 3) ||
        !_media3RendererDriftActiveSourceMatches(source)) {
      return false;
    }
    final lastRepairAt = _lastMedia3RendererDriftRepairAt;
    return lastRepairAt == null ||
        now.difference(lastRepairAt) >= const Duration(seconds: 4);
  }

  bool _shouldPreemptSustainedMedia3DirectHlsClockDrift(
    _NativePlaybackController controller,
    PlaybackSource source,
    DateTime now,
  ) {
    if (!_playbackCadenceClockUnstable ||
        controller.engine != _NativePlaybackEngine.exoplayer ||
        !controller.isInitialized ||
        !controller.isPlaying ||
        controller.isBuffering ||
        controller.hasError ||
        !_shouldAvoidLibVlcRendererDriftEscalation(source) ||
        !_media3RendererDriftActiveSourceMatches(source)) {
      return false;
    }
    if (_recoveringFromMedia3RendererDrift ||
        _recoveringFromStall ||
        _playerClosing ||
        !mounted) {
      return false;
    }
    final startedAt = _playbackCadenceUnstableWindowStartedAt;
    if (startedAt == null) return false;
    final unstableFor = now.difference(startedAt);
    if (_hasLongVisibleMedia3SessionProof(controller) &&
        (unstableFor < const Duration(seconds: 12) ||
            _playbackCadenceConsecutiveJumpEvents < 6)) {
      return false;
    }
    final hasPostStartupVisualProof = controller.hasRenderedVideoFrame &&
        controller.duration > Duration.zero &&
        controller.size != Size.zero &&
        !_activeSourceHasZeroClockMetadata &&
        (_activeSourceVerifiedForSession || _sourceCredibleWatchSeconds >= 20);
    final minimumUnstableFor = hasPostStartupVisualProof
        ? const Duration(seconds: 3)
        : const Duration(seconds: 4);
    final minimumUnstableEvents = hasPostStartupVisualProof ? 2 : 2;
    return unstableFor >= minimumUnstableFor &&
        _playbackCadenceUnstableEvents >= minimumUnstableEvents;
  }

  bool _canStartMedia3RendererDriftEscalation({
    required PlaybackSource source,
    required Duration anchor,
    required DateTime now,
  }) {
    if (_playerClosing ||
        !mounted ||
        _recoveringFromMedia3RendererDrift ||
        _escalatingMedia3RendererDrift ||
        _recoveringFromStall ||
        anchor < const Duration(seconds: 3) ||
        _effectivePlaybackEngine != 'auto' ||
        _libvlcUnavailableForAppSession ||
        _libvlcUnavailableForCurrentPass ||
        _shouldAvoidLibVlcRendererDriftEscalation(source) ||
        !_media3RendererDriftActiveSourceMatches(source)) {
      return false;
    }
    final lastEscalationAt = _lastMedia3RendererDriftEscalationAt;
    return lastEscalationAt == null ||
        now.difference(lastEscalationAt) >= const Duration(seconds: 20);
  }

  bool _shouldAvoidLibVlcRendererDriftEscalation(PlaybackSource source) {
    return source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _libVlcCrashGuardActive;
  }

  bool _isMedia3DirectHlsRendererDriftCandidate(PlaybackSource source) {
    return source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source);
  }

  bool _shouldEscapeRepeatedDirectHlsRendererDrift(PlaybackSource source) {
    final repeatedDrift = _media3RendererDriftRepairCountForSource >= 2;
    if (_shouldProtectVisiblyPlayingSource(
          source,
          _NativePlaybackEngine.exoplayer,
        ) &&
        !repeatedDrift) {
      return false;
    }
    return _shouldAvoidLibVlcRendererDriftEscalation(source) && repeatedDrift;
  }

  bool _shouldSkipProviderAfterMedia3DirectHlsRendererDrift(
    PlaybackSource source,
  ) {
    if (!_shouldAvoidLibVlcRendererDriftEscalation(source)) return false;
    if (_qualityPreferenceMode == 'advanced') return false;
    return _effectivePlaybackEngine == 'auto' ||
        _effectivePlaybackEngine == _NativePlaybackEngine.exoplayer.id;
  }

  bool _sourceHasMedia3DirectHlsRendererDriftRepair(PlaybackSource source) {
    return _shouldAvoidLibVlcRendererDriftEscalation(source) &&
        _media3RendererDriftRepairSourceKey ==
            _playbackSourceRuntimeKey(source) &&
        _media3RendererDriftRepairCountForSource > 0;
  }

  Future<void> _advanceFromMedia3DirectHlsRendererDrift({
    required PlaybackSource source,
    required Duration anchor,
    required String reason,
  }) async {
    final startupProofRecovery =
        reason == 'media3_direct_hls_startup_proof_unavailable';
    if (_recoveringFromMedia3RendererDrift ||
        (_recoveringFromStall && !startupProofRecovery)) {
      DiagnosticLog.add(
        'native playback cadence renderer drift advance ignored provider=${source.providerId} reason=$reason action=already_recovering',
      );
      return;
    }
    if (startupProofRecovery && _recoveringFromStall) {
      DiagnosticLog.add(
        'native playback cadence renderer drift startup proof recovery taking over stall recovery provider=${source.providerId} anchor=${anchor.inSeconds}s reason=$reason',
      );
      _recoveringFromStall = false;
    }
    _recoveringFromMedia3RendererDrift = true;
    _activeSourceVerifiedForSession = false;
    _anchorNativeRecoveryProgress(anchor, reason: '${reason}_advance');
    final directHlsRendererDrift =
        _isMedia3DirectHlsRendererDriftCandidate(source);
    final nextMedia3SourceIndex = directHlsRendererDrift
        ? _nextSourceIndexAfterHardFailure(
            _activeSources,
            _sourceIndex,
            _NativePlaybackEngine.exoplayer,
          )
        : null;
    if (nextMedia3SourceIndex != null) {
      DiagnosticLog.add(
        'native playback cadence renderer drift trying known media3 source provider=${source.providerId} sourceIndex=$_sourceIndex nextSourceIndex=$nextMedia3SourceIndex anchor=${anchor.inSeconds}s reason=$reason action=advance_media3_before_cross_engine',
      );
      final recovered = await _tryKnownMedia3RecoverySourceAtIndex(
        nextMedia3SourceIndex,
        anchor,
        reason: 'media3_renderer_drift_alternate_source',
      );
      if (recovered || !mounted || _playerClosing) {
        _recoveringFromMedia3RendererDrift = false;
        return;
      }
      _recoveringFromMedia3RendererDrift = true;
    }
    final shouldTryLibVlcRelay = directHlsRendererDrift &&
        _effectivePlaybackEngine == 'auto' &&
        !_manualLibVlcConfigured &&
        !_libvlcUnavailableForCurrentPass &&
        !_libvlcUnavailableForAppSession &&
        _canUseLibVlcHlsRelaySource(source, _NativePlaybackEngine.libvlc);
    if (shouldTryLibVlcRelay) {
      DiagnosticLog.add(
        'native playback cadence renderer drift trying libvlc relay provider=${source.providerId} anchor=${anchor.inSeconds}s reason=$reason action=override_media3_drift_to_libvlc',
      );
      final recovered = await _retrySourceWithLibVlcAfterExoVisualFailure(
        source,
        anchor,
        statusMessage: 'Switching video engine...',
        reason: reason,
      );
      if (recovered || !mounted || _playerClosing) {
        _recoveringFromMedia3RendererDrift = false;
        return;
      }
      DiagnosticLog.add(
        'native playback cadence renderer drift libvlc relay failed provider=${source.providerId} anchor=${anchor.inSeconds}s reason=$reason action=advance_source_at_anchor',
      );
    }
    if (_controller != null) {
      await _disposeCurrentController(
        updateUi: false,
        awaitLibVlcRelease: true,
        saveProgress: false,
      );
      if (!mounted) return;
    }
    if (_shouldSkipProviderAfterMedia3DirectHlsRendererDrift(source) &&
        _providerIndex < _requests.length - 1) {
      DiagnosticLog.add(
        'native playback cadence renderer drift skipping direct hls provider provider=${source.providerId} providerIndex=$_providerIndex anchor=${anchor.inSeconds}s reason=$reason action=advance_provider_at_anchor',
      );
      _providerIndex += 1;
      _sourceIndex = 0;
      _activeSource = null;
      _activeSources = const <PlaybackSource>[];
      _sameSourceRecoveryAttempts = 0;
      _recoveringFromStall = false;
      _recoveringFromMedia3RendererDrift = false;
      await _openNextAvailableSource(resumePositionOverride: anchor);
      return;
    }
    final nextSourceIndex =
        _nextSourceIndexAfterHardFailure(_activeSources, _sourceIndex) ??
            _sourceIndex + 1;
    DiagnosticLog.add(
      'native playback cadence renderer drift advancing source provider=${source.providerId} sourceIndex=$_sourceIndex nextSourceIndex=$nextSourceIndex anchor=${anchor.inSeconds}s reason=$reason action=advance_source_at_anchor',
    );
    _sourceIndex = nextSourceIndex;
    _sameSourceRecoveryAttempts = 0;
    _activeSource = null;
    _recoveringFromStall = false;
    _recoveringFromMedia3RendererDrift = false;
    await _openNextAvailableSource(resumePositionOverride: anchor);
  }

  bool _shouldReopenForMedia3RendererDrift(
    _NativePlaybackController? currentController,
    PlaybackSource source, {
    required Duration anchor,
  }) {
    if (currentController == null) return true;
    if (_playerClosing || !mounted) return false;
    if (_activeSource?.url != source.url) return true;
    if (!currentController.isInitialized || currentController.hasError) {
      return true;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return true;
    if (_playbackCadenceClockUnstable ||
        _playbackCadenceConsecutiveJumpEvents >= 2) {
      return true;
    }
    if (_shouldProtectVisiblyPlayingSource(source, currentController.engine)) {
      return false;
    }

    final hasStableAnchor = anchor >= const Duration(seconds: 5) ||
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
        _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
        _lastSavedSecond >= 5;
    if (!hasStableAnchor) return true;

    final hasRuntimeProof = _activeSourceVerifiedForSession ||
        _sourceHasVisualPlaybackProof(currentController);
    final canHoldCurrentSource = currentController.isPlaying ||
        currentController.isBuffering ||
        hasRuntimeProof;
    return !(hasRuntimeProof && canHoldCurrentSource);
  }

  Future<void> _repairMedia3RendererDriftAtAnchor({
    required PlaybackSource source,
    required Duration anchor,
    required Duration observedPosition,
    required Duration heldPosition,
  }) async {
    final now = DateTime.now();
    if (!_canStartMedia3RendererDriftRepair(
      source: source,
      anchor: anchor,
      now: now,
    )) {
      return;
    }
    final sourceKey = _playbackSourceRuntimeKey(source);
    if (_media3RendererDriftRepairSourceKey == sourceKey) {
      _media3RendererDriftRepairCountForSource += 1;
    } else {
      _media3RendererDriftRepairSourceKey = sourceKey;
      _media3RendererDriftRepairCountForSource = 1;
    }
    if (_shouldEscapeRepeatedDirectHlsRendererDrift(source)) {
      DiagnosticLog.add(
        'native playback cadence renderer drift escaping repeated direct hls provider=${source.providerId} observed=${observedPosition.inSeconds}s held=${heldPosition.inSeconds}s anchor=${anchor.inSeconds}s repairs=$_media3RendererDriftRepairCountForSource action=advance_source_at_anchor',
      );
      await _advanceFromMedia3DirectHlsRendererDrift(
        source: source,
        anchor: anchor,
        reason: 'media3_repeated_direct_hls_renderer_drift',
      );
      return;
    }
    if (source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source)) {
      _recordMedia3DirectHlsRendererDriftRisk(source);
    }
    final currentController = _controller;
    final earlyDirectHlsDrift =
        _shouldAvoidLibVlcRendererDriftEscalation(source) &&
            (currentController == null ||
                !_hasLongVisibleMedia3SessionProof(currentController));
    if (earlyDirectHlsDrift) {
      DiagnosticLog.add(
        'native playback cadence renderer drift advancing early direct hls provider=${source.providerId} observed=${observedPosition.inSeconds}s held=${heldPosition.inSeconds}s anchor=${anchor.inSeconds}s repairs=$_media3RendererDriftRepairCountForSource action=advance_source_at_anchor reason=media3_direct_hls_early_renderer_drift',
      );
      await _advanceFromMedia3DirectHlsRendererDrift(
        source: source,
        anchor: anchor,
        reason: 'media3_direct_hls_early_renderer_drift',
      );
      return;
    }
    if (!_shouldReopenForMedia3RendererDrift(
      currentController,
      source,
      anchor: anchor,
    )) {
      DiagnosticLog.add(
        'native playback cadence renderer drift repair suppressed provider=${source.providerId} observed=${observedPosition.inSeconds}s held=${heldPosition.inSeconds}s anchor=${anchor.inSeconds}s reason=media3_renderer_drift_repair_suppressed action=hold_current_source_after_renderer_drift',
      );
      _anchorNativeRecoveryProgress(
        anchor,
        reason: 'media3_renderer_drift_repair_suppressed',
      );
      _playbackCadenceConsecutiveJumpEvents = 0;
      _playbackCadenceUnstableEvents = 0;
      _playbackCadenceClockUnstable = false;
      if (currentController != null) {
        _rememberVerifiedSource(currentController, anchor);
      }
      if (mounted) {
        _clearPlaybackWaitMessage(
            reason: 'media3_renderer_drift_repair_suppressed');
      }
      return;
    }
    _recoveringFromMedia3RendererDrift = true;
    _lastMedia3RendererDriftRepairAt = now;
    _anchorNativeRecoveryProgress(anchor,
        reason: 'media3_renderer_drift_repair_start');
    DiagnosticLog.add(
      'native playback cadence renderer drift repair starting provider=${source.providerId} observed=${observedPosition.inSeconds}s held=${heldPosition.inSeconds}s anchor=${anchor.inSeconds}s action=repair_renderer_at_anchor',
    );
    try {
      final opened = await _openSource(
        source,
        resumePosition: anchor,
        quietRecovery: true,
      );
      DiagnosticLog.add(
        'native playback cadence renderer drift repair completed provider=${source.providerId} anchor=${anchor.inSeconds}s reopened=$opened action=repair_renderer_at_anchor',
      );
      if (!opened && _shouldAvoidLibVlcRendererDriftEscalation(source)) {
        DiagnosticLog.add(
          'native playback cadence renderer drift repair open failed provider=${source.providerId} anchor=${anchor.inSeconds}s action=advance_source_at_anchor reason=direct_hls_repair_open_failed',
        );
        await _advanceFromMedia3DirectHlsRendererDrift(
          source: source,
          anchor: anchor,
          reason: 'media3_direct_hls_renderer_drift_repair_open_failed',
        );
      }
    } catch (error) {
      DiagnosticLog.add(
        'native playback cadence renderer drift repair failed provider=${source.providerId} anchor=${anchor.inSeconds}s errorType=${error.runtimeType} action=repair_renderer_at_anchor',
      );
      if (_shouldAvoidLibVlcRendererDriftEscalation(source)) {
        DiagnosticLog.add(
          'native playback cadence renderer drift repair exception provider=${source.providerId} anchor=${anchor.inSeconds}s action=advance_source_at_anchor reason=direct_hls_repair_exception',
        );
        await _advanceFromMedia3DirectHlsRendererDrift(
          source: source,
          anchor: anchor,
          reason: 'media3_direct_hls_renderer_drift_repair_exception',
        );
      }
    } finally {
      _recoveringFromMedia3RendererDrift = false;
    }
  }

  Future<void> _escalateMedia3RendererDriftAtAnchor({
    required PlaybackSource source,
    required Duration anchor,
    required Duration observedPosition,
    required Duration heldPosition,
  }) async {
    final now = DateTime.now();
    if (!_canStartMedia3RendererDriftEscalation(
      source: source,
      anchor: anchor,
      now: now,
    )) {
      return;
    }
    _escalatingMedia3RendererDrift = true;
    _recoveringFromMedia3RendererDrift = true;
    _lastMedia3RendererDriftEscalationAt = now;
    _anchorNativeRecoveryProgress(anchor,
        reason: 'media3_renderer_drift_escalation_start');
    _recordMedia3DirectHlsRendererDriftRisk(source);
    DiagnosticLog.add(
      'native playback cadence renderer drift escalation starting provider=${source.providerId} observed=${observedPosition.inSeconds}s held=${heldPosition.inSeconds}s anchor=${anchor.inSeconds}s action=escalate_renderer_route_at_anchor',
    );
    try {
      final opened = await _openSource(
        source,
        resumePosition: anchor,
        engineOverride: _NativePlaybackEngine.libvlc,
        quietRecovery: true,
      );
      DiagnosticLog.add(
        'native playback cadence renderer drift escalation completed provider=${source.providerId} anchor=${anchor.inSeconds}s reopened=$opened action=escalate_renderer_route_at_anchor',
      );
    } catch (error) {
      DiagnosticLog.add(
        'native playback cadence renderer drift escalation failed provider=${source.providerId} anchor=${anchor.inSeconds}s errorType=${error.runtimeType} action=escalate_renderer_route_at_anchor',
      );
    } finally {
      _escalatingMedia3RendererDrift = false;
      _recoveringFromMedia3RendererDrift = false;
    }
  }

  void _clearControllerErrorGrace() {
    _firstControllerErrorAt = null;
    _lastControllerErrorDescription = null;
    _controllerErrorGraceLogs = 0;
  }

  bool _controllerErrorRecoveryAlreadyQueued(
    _NativePlaybackController controller, {
    required Duration recoveryPosition,
    required String reason,
  }) {
    final source = _activeSource;
    final key = [
      _providerRunId,
      source?.providerId ?? 'none',
      controller.engine.id,
      recoveryPosition.inSeconds,
      controller.errorDescription,
    ].join('|');
    final now = DateTime.now();
    final previousAt = _lastControllerErrorRecoveryAt;
    if (_lastControllerErrorRecoveryKey == key &&
        previousAt != null &&
        now.difference(previousAt) < const Duration(seconds: 8)) {
      DiagnosticLog.add(
        'native playback error recovery coalesced reason=$reason provider=${source?.providerId} engine=${controller.engine.id} recoveryPosition=${recoveryPosition.inSeconds}s error=${controller.errorDescription}',
      );
      return true;
    }
    _lastControllerErrorRecoveryKey = key;
    _lastControllerErrorRecoveryAt = now;
    return false;
  }

  bool _shouldDeferControllerErrorRecovery(
    _NativePlaybackController controller, {
    required String reason,
  }) {
    final now = DateTime.now();
    final position = controller.position;
    final description = controller.errorDescription;
    final hadUsefulPlayback = position >= const Duration(seconds: 5) ||
        _lastKnownPlaybackPosition >= const Duration(seconds: 5);
    final movedSinceWatchdog = (position - _lastWatchdogPosition).abs() >=
        const Duration(milliseconds: 850);
    final libVlcWarmupElapsed = _nativeWallClockStartedAt == null
        ? null
        : now.difference(_nativeWallClockStartedAt!);
    final media3StartupElapsed = _nativeWallClockStartedAt == null
        ? null
        : now.difference(_nativeWallClockStartedAt!);
    final libVlcStillGatheringMetadata =
        controller.engine == _NativePlaybackEngine.libvlc &&
            controller.isInitialized &&
            position <= Duration.zero &&
            controller.size == Size.zero &&
            libVlcWarmupElapsed != null &&
            libVlcWarmupElapsed < _libVlcWarmupGrace;

    if (libVlcStillGatheringMetadata) {
      if (_controllerErrorGraceLogs < 3) {
        DiagnosticLog.add(
          'native playback error deferred reason=$reason provider=${_activeSource?.providerId} engine=libvlc elapsed=${libVlcWarmupElapsed.inMilliseconds}ms position=${position.inSeconds}s duration=${controller.duration.inSeconds}s size=0x0 phase=warmup error=$description',
        );
        _controllerErrorGraceLogs += 1;
      }
      return true;
    }

    final source = _activeSource;
    final media3StillGatheringStartupProof =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            controller.isInitialized &&
            source != null &&
            source.sourceClass != PlaybackSourceClass.p2p &&
            !_isLiveTvMode &&
            position < const Duration(seconds: 5) &&
            media3StartupElapsed != null &&
            media3StartupElapsed < _media3StartupErrorGraceForSource(source) &&
            (controller.duration <= Duration.zero ||
                controller.size == Size.zero ||
                controller.isBuffering);
    if (media3StillGatheringStartupProof) {
      if (_controllerErrorGraceLogs < 4) {
        DiagnosticLog.add(
          'native playback error deferred reason=$reason provider=${source.providerId} engine=exoplayer elapsed=${media3StartupElapsed.inMilliseconds}ms position=${position.inSeconds}s duration=${controller.duration.inSeconds}s size=${controller.size.width.toStringAsFixed(0)}x${controller.size.height.toStringAsFixed(0)} phase=media3_startup error=$description',
        );
        _controllerErrorGraceLogs += 1;
      }
      return true;
    }

    if (hadUsefulPlayback && controller.isPlaying && movedSinceWatchdog) {
      if (_controllerErrorGraceLogs < 2) {
        DiagnosticLog.add(
          'native playback error deferred reason=$reason provider=${_activeSource?.providerId} position=${position.inSeconds}s progress=moving error=$description',
        );
        _controllerErrorGraceLogs += 1;
      }
      _clearControllerErrorGrace();
      return true;
    }

    if (!hadUsefulPlayback) return false;

    if (controller.isPlaying || controller.isBuffering) {
      if (_controllerErrorGraceLogs < 3) {
        DiagnosticLog.add(
          'native playback error deferred reason=$reason provider=${_activeSource?.providerId} position=${position.inSeconds}s buffering=${controller.isBuffering} playing=${controller.isPlaying} phase=held_as_transient error=$description',
        );
        _controllerErrorGraceLogs += 1;
      }
      if (controller.isPlaying && movedSinceWatchdog) {
        _clearControllerErrorGrace();
      }
      return true;
    }

    if (_firstControllerErrorAt == null ||
        _lastControllerErrorDescription != description) {
      _firstControllerErrorAt = now;
      _lastControllerErrorDescription = description;
      _controllerErrorGraceLogs = 1;
      DiagnosticLog.add(
        'native playback error grace started reason=$reason provider=${_activeSource?.providerId} position=${position.inSeconds}s lastKnown=${_lastKnownPlaybackPosition.inSeconds}s error=$description',
      );
      return true;
    }

    final elapsed = now.difference(_firstControllerErrorAt!);
    if (elapsed < const Duration(milliseconds: 4500)) {
      if (_controllerErrorGraceLogs < 3) {
        DiagnosticLog.add(
          'native playback error grace waiting reason=$reason provider=${_activeSource?.providerId} elapsed=${elapsed.inMilliseconds}ms position=${position.inSeconds}s error=$description',
        );
        _controllerErrorGraceLogs += 1;
      }
      return true;
    }

    return false;
  }

  bool _shouldRepairExoControllerErrorAtAnchor(
    _NativePlaybackController controller,
    Duration recoveryPosition,
  ) {
    final source = _activeSource;
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (_isMedia3HardSourceHttpError(controller.errorDescription)) {
      return false;
    }
    if (_shouldKeepCurrentSourceAfterMedia3RendererRepairError(
      controller,
      recoveryPosition,
    )) {
      return true;
    }
    if (!controller.hasError || !controller.isInitialized) return false;
    if (_isLiveTvMode || source.sourceClass == PlaybackSourceClass.p2p) {
      return false;
    }
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    final hasStableAnchor =
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
            _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
            _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
            _lastSavedSecond >= 5;
    final hasPlayableAnchor = hasStableAnchor ||
        _activeSourceVerifiedForSession ||
        _playbackCadenceClockUnstable;
    if (controller.position > const Duration(seconds: 2) &&
        !hasPlayableAnchor) {
      return false;
    }
    return hasPlayableAnchor;
  }

  bool _shouldKeepCurrentSourceAfterMedia3RendererRepairError(
    _NativePlaybackController controller,
    Duration recoveryPosition,
  ) {
    final source = _activeSource;
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (!controller.hasError) return false;
    if (_isMedia3HardSourceHttpError(controller.errorDescription)) {
      return false;
    }
    if (_isLiveTvMode || source.sourceClass == PlaybackSourceClass.p2p) {
      return false;
    }
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    if (!_inRendererRecoveryAnchorWindow) return false;
    if (!_media3RendererDriftActiveSourceMatches(source)) return false;
    final hasStableAnchor =
        _rendererRecoveryAnchorPosition >= const Duration(seconds: 5) ||
            _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
            _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
            _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
            _lastSavedSecond >= 5;
    final hasPlayableAnchor =
        hasStableAnchor || _activeSourceVerifiedForSession;
    if (controller.position > const Duration(seconds: 2) &&
        !hasPlayableAnchor) {
      return false;
    }
    if (!hasPlayableAnchor) {
      return false;
    }
    final description = controller.errorDescription.toLowerCase();
    return _isMedia3AnchorRepairEscapableError(description);
  }

  bool _isMedia3AnchorRepairEscapableError(String description) {
    return description.contains('source error') ||
        description.contains('exoplaybackexception') ||
        description.contains('videoerror') ||
        description.contains('network_connection_timeout') ||
        description.contains('network connection timeout') ||
        description.contains('connection timeout') ||
        description.contains('sockettimeout') ||
        description.contains('io_network') ||
        _isMedia3AnchorRepairTerminalError(description);
  }

  bool _isMedia3HardSourceHttpError(String description) {
    final normalized = description.toLowerCase();
    return normalized.contains('error_code_io_bad_http_status') ||
        normalized.contains('bad_http_status') ||
        normalized.contains('bad http status') ||
        normalized.contains('http status 4') ||
        normalized.contains('http status 5') ||
        normalized.contains('response code: 4') ||
        normalized.contains('response code: 5');
  }

  bool _isMedia3AnchorRepairTerminalError(String description) {
    return description.contains('decoding_failed') ||
        description.contains('failed_runtime_check') ||
        description.contains('decoding failed') ||
        description.contains('decoder') ||
        description.contains('codec');
  }

  bool _shouldEscapeRepeatedMedia3AnchorRepairError(
    _NativePlaybackController controller,
    Duration recoveryPosition,
  ) {
    final source = _activeSource;
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (!controller.hasError) return false;
    if (_isLiveTvMode || source.sourceClass == PlaybackSourceClass.p2p) {
      return false;
    }
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    if (!_inRendererRecoveryAnchorWindow) return false;
    if (!_media3RendererDriftActiveSourceMatches(source)) return false;
    final description = controller.errorDescription.toLowerCase();
    if (!_isMedia3AnchorRepairEscapableError(description)) return false;
    if (_isMedia3AnchorRepairTerminalError(description)) return true;

    final now = DateTime.now();
    final sameProvider =
        _media3AnchorRepairSourceErrorProviderId == source.providerId;
    final windowStarted = _media3AnchorRepairSourceErrorWindowStartedAt;
    final inWindow = sameProvider &&
        windowStarted != null &&
        now.difference(windowStarted) <= const Duration(seconds: 20);

    if (!inWindow) {
      _media3AnchorRepairSourceErrorProviderId = source.providerId;
      _media3AnchorRepairSourceErrorWindowStartedAt = now;
      _media3AnchorRepairSourceErrorCount = 1;
      return false;
    }

    _media3AnchorRepairSourceErrorCount += 1;
    return _media3AnchorRepairSourceErrorCount >= 2;
  }

  void _resetMedia3AnchorRepairErrorWindow({
    String reason = 'healthy_playback',
  }) {
    if (_media3AnchorRepairSourceErrorCount == 0 &&
        _media3AnchorRepairSourceErrorProviderId == null) {
      return;
    }
    DiagnosticLog.add(
      'native media3 anchor repair error window reset reason=$reason count=$_media3AnchorRepairSourceErrorCount',
    );
    _media3AnchorRepairSourceErrorCount = 0;
    _media3AnchorRepairSourceErrorWindowStartedAt = null;
    _media3AnchorRepairSourceErrorProviderId = null;
  }

  bool _shouldRepairPersistentControllerBuffering(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (source == null) return false;
    if (!controller.isInitialized ||
        !controller.isBuffering ||
        controller.hasError) {
      return false;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (controller.engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.direct &&
        !_isHlsSource(source) &&
        (controller.duration <= Duration.zero ||
            controller.size == Size.zero)) {
      return false;
    }
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    if (_shouldHoldProvenMedia3PersistentBuffering(
          controller,
          source,
          recoveryPosition,
        ) &&
        _media3HasPersistentBufferingHoldProof(controller, source)) {
      if (_isHlsSource(source) &&
          _bufferingWatchdogTicks >=
              _bufferingRecoveryTickLimitForSource(source)) {
        DiagnosticLog.add(
          'native media3 proven buffering hold expired provider=${source.providerId} tick=$_bufferingWatchdogTicks reason=hls_clock_stall_repair',
        );
        return true;
      }
      return false;
    }
    final hasStableAnchor =
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
            _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
            _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
            _lastSavedSecond >= 5;
    return hasStableAnchor ||
        _activeSourceVerifiedForSession ||
        _sourceHasVisualPlaybackProof(controller) ||
        _playbackCadenceClockUnstable;
  }

  bool _shouldKeepVerifiedControllerBufferingQuiet(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    final quietTickLimit = _bufferingRecoveryTickLimitForSource(source) *
        _persistentBufferingAnchorRepairLimitForSource(source);
    final escapeTickLimit =
        _persistentBufferingAnchorEscapeTickLimitForSource(source);
    if (source != null &&
        _inRendererRecoveryAnchorWindow &&
        _media3RendererDriftActiveSourceMatches(source) &&
        controller.isInitialized &&
        controller.isBuffering &&
        !controller.hasError &&
        source.sourceClass != PlaybackSourceClass.p2p &&
        !_isLiveTvMode &&
        !_isPublicIptvSource(source)) {
      final anchorPosition =
          _rendererRecoveryAnchorPosition >= const Duration(seconds: 3)
              ? _rendererRecoveryAnchorPosition
              : recoveryPosition;
      if (anchorPosition >= const Duration(seconds: 3) &&
          (_bufferingWatchdogTicks < quietTickLimit ||
              _shouldHoldProvenMedia3PersistentBuffering(
                controller,
                source,
                recoveryPosition,
              ))) {
        _lastWatchdogPosition = anchorPosition;
        if (_bufferingWatchdogTicks == 1 ||
            _bufferingWatchdogTicks == quietTickLimit ||
            _bufferingWatchdogTicks % quietTickLimit == 0) {
          DiagnosticLog.add(
            'native buffering watchdog provider=${source.providerId} tick=$_bufferingWatchdogTicks limit=$quietTickLimit position=${anchorPosition.inSeconds}s action=hold_quiet reason=renderer_recovery_buffering_hold',
          );
        }
        return true;
      }
    }
    if (_bufferingWatchdogTicks >= quietTickLimit &&
        _shouldHoldProvenMedia3PersistentBuffering(
          controller,
          source,
          recoveryPosition,
        ) &&
        _media3HasPersistentBufferingHoldProof(controller, source)) {
      if (_bufferingWatchdogTicks >= escapeTickLimit) {
        DiagnosticLog.add(
          'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$escapeTickLimit position=${recoveryPosition.inSeconds}s action=escape reason=verified_media3_buffering_anchor_expired',
        );
        return false;
      }
      _lastWatchdogPosition = recoveryPosition;
      if (_bufferingWatchdogTicks == quietTickLimit ||
          _bufferingWatchdogTicks % quietTickLimit == 0) {
        DiagnosticLog.add(
          'native buffering watchdog provider=${source?.providerId} tick=$_bufferingWatchdogTicks limit=$escapeTickLimit position=${recoveryPosition.inSeconds}s action=hold_current_source reason=verified_media3_buffering_anchor_hold',
        );
      }
      return true;
    }
    if (_bufferingWatchdogTicks >= quietTickLimit) {
      return false;
    }
    if (_shouldRepairPersistentControllerBuffering(
      controller,
      source,
      recoveryPosition,
    )) {
      return false;
    }
    return false;
  }

  bool _shouldKeepVisualControllerBufferingQuiet(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (!controller.isInitialized ||
        !controller.isBuffering ||
        controller.hasError ||
        controller.duration <= Duration.zero ||
        controller.size == Size.zero ||
        _activeSourceHasZeroClockMetadata) {
      return false;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (controller.engine == _NativePlaybackEngine.exoplayer &&
        source.sourceClass == PlaybackSourceClass.direct &&
        !_isHlsSource(source) &&
        (controller.duration <= Duration.zero ||
            controller.size == Size.zero)) {
      return false;
    }
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    final hasCurrentSourceProof =
        _activeSourceVerifiedForSession || _sourceCredibleWatchSeconds >= 4;
    final hasVisibleRuntimeProgress = hasCurrentSourceProof &&
        controller.hasRenderedVideoFrame &&
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) &&
        _lastKnownPlaybackPosition >=
            recoveryPosition - const Duration(seconds: 3);
    return hasVisibleRuntimeProgress ||
        _sourceHasRawVisualPlaybackProof(controller) ||
        _sourceHasVisualPlaybackProof(controller);
  }

  bool _shouldHoldProvenMedia3PersistentBuffering(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition,
  ) {
    if (source == null) return false;
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (!controller.isInitialized ||
        !controller.isBuffering ||
        controller.hasError ||
        controller.duration <= Duration.zero ||
        controller.size == Size.zero ||
        _activeSourceHasZeroClockMetadata) {
      return false;
    }
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (recoveryPosition < const Duration(seconds: 5)) return false;
    final hasVisualBufferingProof = controller.isPlaying &&
        controller.hasRenderedVideoFrame &&
        _sourceHasRawVisualPlaybackProof(controller);
    if (hasVisualBufferingProof &&
        _bufferingWatchdogTicks <
            _persistentBufferingAnchorEscapeTickLimitForSource(source)) {
      return true;
    }
    if (source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _bufferingWatchdogTicks >=
            _bufferingRecoveryTickLimitForSource(source) &&
        !controller.isPlaying) {
      DiagnosticLog.add(
        'native media3 proven buffering hold expired provider=${source.providerId} tick=$_bufferingWatchdogTicks reason=hls_clock_stall_repair',
      );
      return false;
    }
    if (_media3PersistentBufferingNudgedSource(source) &&
        _media3PersistentBufferingNudgeCountForSource >= 1 &&
        _bufferingWatchdogTicks >=
            _bufferingRecoveryTickLimitForSource(source)) {
      DiagnosticLog.add(
        'native media3 proven buffering hold expired provider=${source.providerId} tick=$_bufferingWatchdogTicks reason=post_nudge_resume_hls_escape',
      );
      return false;
    }
    if (source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source) &&
        _resumeRecoveryExcludedQualityRanks.isNotEmpty &&
        _bufferingWatchdogTicks >=
            _bufferingRecoveryTickLimitForSource(source)) {
      DiagnosticLog.add(
        'native media3 proven buffering hold expired provider=${source.providerId} tick=$_bufferingWatchdogTicks reason=resume_quality_recovery_hls_escape',
      );
      return false;
    }
    if (_bufferingWatchdogTicks >=
        _persistentBufferingAnchorEscapeTickLimitForSource(source)) {
      return false;
    }
    return _activeSourceVerifiedForSession ||
        _sourceHasRawVisualPlaybackProof(controller) ||
        _sourceHasVisualPlaybackProof(controller);
  }

  bool _shouldHoldHealthyBufferingSource(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition, {
    required bool allowSourceReload,
    required bool forceSourceAdvance,
    required bool libVlcZeroMetadataStall,
  }) {
    if (!allowSourceReload || forceSourceAdvance) return false;
    if (source == null) return false;
    if (!controller.isInitialized || controller.hasError) return false;
    if (!controller.isBuffering && !controller.isPlaying) return false;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    if (source.sourceClass == PlaybackSourceClass.p2p) return false;
    if (libVlcZeroMetadataStall) return false;
    if (recoveryPosition < const Duration(seconds: 3)) return false;
    if (_shouldBypassSoftHoldForMedia3PersistentBuffering(
      controller,
      source,
      recoveryPosition,
    )) {
      return false;
    }
    if (controller.isBuffering &&
        _bufferingWatchdogTicks >=
            _persistentBufferingAnchorEscapeTickLimitForSource(source)) {
      return false;
    }

    final hasStableAnchor = recoveryPosition >= const Duration(seconds: 5) ||
        _lastKnownPlaybackPosition >= const Duration(seconds: 5) ||
        _lastCrediblePlaybackPosition >= const Duration(seconds: 5) ||
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) ||
        _lastSavedSecond >= 5;
    final hasRuntimeProof = _activeSourceVerifiedForSession ||
        _sourceHasVisualPlaybackProof(controller) ||
        _playbackCadenceClockUnstable ||
        hasStableAnchor;
    if (!hasRuntimeProof) return false;

    final zeroVisualWithoutProof =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            controller.size == Size.zero &&
            !_activeSourceVerifiedForSession &&
            !_playbackCadenceClockUnstable &&
            !_sourceHasVisualPlaybackProof(controller);
    return !zeroVisualWithoutProof;
  }

  bool _shouldHoldEarlySoftBufferingSource(
    _NativePlaybackController controller,
    PlaybackSource? source,
    Duration recoveryPosition, {
