  Future<void> _loadSkipSegments() async {
    final generation = ++_skipSegmentLoadGeneration;
    if (!_skipSegmentsSupported) {
      if (mounted) {
        setState(() {
          _skipSegments = const <PlaybackSkipSegment>[];
          _skipSegmentLookupDuration = Duration.zero;
        });
      }
      return;
    }
    try {
      final segments = await _skipSegmentClient.lookup(
        tmdbId: _skipSegmentTmdbId,
        imdbId: _skipSegmentImdbId,
        season: _skipSegmentSeason,
        episode: _skipSegmentEpisode,
        duration: _knownSkipSegmentDuration,
      );
      if (!mounted || generation != _skipSegmentLoadGeneration) return;
      setState(() => _skipSegments = segments);
      _skipSegmentLookupDuration = _knownSkipSegmentDuration ?? Duration.zero;
      if (segments.isNotEmpty) {
        DiagnosticLog.add(
          'skip segment lookup loaded count=${segments.length}',
        );
      }
    } catch (error) {
      if (!mounted || generation != _skipSegmentLoadGeneration) return;
      _skipSegmentLookupDuration = Duration.zero;
      setState(() => _skipSegments = const <PlaybackSkipSegment>[]);
      DiagnosticLog.add(
        'skip segment lookup unavailable reason=${_safeDiagnosticError(error)}',
      );
    }
  }

  String? get _skipSegmentImdbId {
    final metadataId = _progressItem?.imdbId?.trim();
    if (metadataId != null && metadataId.isNotEmpty) return metadataId;
    final itemId = _progressItem?.id.trim();
    if (itemId == null || itemId.isEmpty) return null;
    return RegExp(r'tt\d+', caseSensitive: false).firstMatch(itemId)?.group(0);
  }

  int? get _skipSegmentTmdbId {
    final metadataId = _progressItem?.tmdbId;
    if (metadataId != null && metadataId > 0) return metadataId;
    final itemId = _progressItem?.id.trim();
    if (itemId == null || itemId.isEmpty) return null;
    final match = RegExp(
      r'(?:tmdb|moviedb)[:/](\d+)',
      caseSensitive: false,
    ).firstMatch(itemId);
    return int.tryParse(match?.group(1) ?? '');
  }

  Duration? get _knownSkipSegmentDuration {
    final controllerDuration = _controller?.duration ?? Duration.zero;
    if (controllerDuration > Duration.zero) return controllerDuration;
    if (_lastKnownPlaybackDuration > Duration.zero) {
      return _lastKnownPlaybackDuration;
    }
    return null;
  }

  Future<void> _showSubtitleSheet() async {
    if (_locked) return;
    _ensureSubtitlesLoading();
    final wasPlaying = _openOptionSheetWithoutPause();
    final selected = await showModalBottomSheet<Object>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (context) {
        return _SubtitleSheet(
          subtitles: _subtitles,
          activeSubtitle: _activeSubtitle,
          allowStyleControls: !_usingGlobalOverrides,
          fontSize: _subtitleFontSize,
          backgroundOpacity: _subtitleBackgroundOpacity,
          backgroundColor: _subtitleBackgroundColor,
          backgroundRadius: _subtitleBackgroundRadius,
          textColor: _subtitleTextColor,
          bottomOffset: _subtitleBottomOffset,
          delaySeconds: _subtitleDelaySeconds,
          defaultDelaySeconds: AppState.nativePlaybackOverridesEnabled.value
              ? AppState.nativePlaybackOverrides.value.subtitleDelaySeconds
              : 0.0,
          onDelayChanged: (value) {
            if (mounted) {
              setState(() {
                _subtitleDelaySeconds = value;
                _subtitleDelayCustomized = true;
              });
              _syncSubtitleText();
              _saveNativeProgress(force: true);
            }
          },
          onDelayResetToDefault: () {
            if (mounted) {
              final defaultDelay = AppState.nativePlaybackOverridesEnabled.value
                  ? AppState.nativePlaybackOverrides.value.subtitleDelaySeconds
                  : 0.0;
              setState(() {
                _subtitleDelayCustomized = false;
                _subtitleDelaySeconds = defaultDelay;
              });
              _syncSubtitleText();
              _saveNativeProgress(force: true);
            }
          },
          onFontSizeChanged: (value) {
            if (mounted) {
              setState(() => _subtitleFontSize = value);
              _saveNativeProgress(force: true);
            }
          },
          onBackgroundOpacityChanged: (value) {
            if (mounted) {
              setState(() => _subtitleBackgroundOpacity = value);
              _saveNativeProgress(force: true);
            }
          },
          onBackgroundColorChanged: (value) {
            if (mounted) {
              setState(() => _subtitleBackgroundColor = value);
              _saveNativeProgress(force: true);
            }
          },
          onBackgroundRadiusChanged: (value) {
            if (mounted) {
              setState(() => _subtitleBackgroundRadius = value);
              _saveNativeProgress(force: true);
            }
          },
          onTextColorChanged: (value) {
            if (mounted) {
              setState(() => _subtitleTextColor = value);
              _saveNativeProgress(force: true);
            }
          },
          onBottomOffsetChanged: (value) {
            if (mounted) {
              setState(() => _subtitleBottomOffset = value);
              _saveNativeProgress(force: true);
            }
          },
        );
      },
    );
    if (!mounted) return;
    if (selected is PlaybackSubtitle) {
      await _selectSubtitle(selected, saveAsDefault: true);
    } else if (selected is _SubtitleOffSelection) {
      await _selectSubtitle(null, saveAsDefault: true);
    }
    await _resumeAfterOptionSheet(wasPlaying);
    _scheduleControlsHide();
  }

  Future<void> _selectSubtitle(
    PlaybackSubtitle? subtitle, {
    bool saveAsDefault = false,
  }) async {
    if (subtitle == null) {
      setState(() {
        _activeSubtitle = null;
        _subtitleCues = const <_SubtitleCue>[];
        _subtitleText = null;
        _preferredSubtitleId = null;
      });
      DiagnosticLog.add('native subtitles off');
      if (saveAsDefault) {
        final behavior = AppState.playerBehaviorSettings.value;
        AppState.updatePlayerBehaviorSettings(
          behavior.copyWith(subtitleAutoSelect: 'off'),
        );
      }
      _saveNativeProgress(force: true);
      return;
    }

    try {
      DiagnosticLog.add(
        'native subtitle load label=${subtitle.label} url=[hidden]',
      );
      final response = await http
          .get(Uri.parse(subtitle.url))
          .timeout(const Duration(seconds: 8));
      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw Exception('Subtitle request failed: ${response.statusCode}');
      }
      final cues = _parseWebVtt(
        utf8.decode(response.bodyBytes, allowMalformed: true),
      );
      if (!mounted) return;
      setState(() {
        _activeSubtitle = subtitle;
        _subtitleCues = cues;
        _subtitleText = null;
        _preferredSubtitleId = subtitle.id;
      });
      _syncSubtitleText();
      DiagnosticLog.add(
        'native subtitle loaded label=${subtitle.label} cues=${cues.length}',
      );
      if (saveAsDefault) {
        final language = subtitle.language.trim().toLowerCase();
        final behavior = AppState.playerBehaviorSettings.value;
        AppState.updatePlayerBehaviorSettings(
          behavior.copyWith(
            subtitleAutoSelect: 'default',
            subtitleLanguage: language.isEmpty ? 'auto' : language,
          ),
        );
      }
      _saveNativeProgress(force: true);
      if (cues.isNotEmpty) {
        DiagnosticLog.add(
          'native subtitle first cue start=${_formatDuration(cues.first.start)} end=${_formatDuration(cues.first.end)} textLength=${cues.first.text.length}',
        );
      }
      if (cues.isEmpty) {
        DiagnosticLog.add('native subtitle parser produced no cues');
      }
    } catch (error) {
      DiagnosticLog.add(
        'native subtitle failed label=${subtitle.label} error=${_safeDiagnosticError(error)}',
      );
    }
  }

  bool _hasCurrentLibVlcProofForSource(PlaybackSource source) {
    final key = _playbackKey;
    if (key == null || key.isEmpty || source.url.isEmpty) return false;
    return AppState.verifiedPlaybackSourcesFor(key).any((cached) {
      if (_verifiedSourceIsExpired(cached) ||
          cached.engineId != _NativePlaybackEngine.libvlc.id ||
          cached.source.url != source.url) {
        return false;
      }
      return cached.confidence >= 12 &&
          cached.failureCount <= 0 &&
          _verifiedSourceHasOpenableDescriptor(cached.source);
    });
  }

  Future<List<PlaybackSource>> _expandQualitySources(
    List<PlaybackSource> sources, {
    DateTime? deadline,
  }) async {
    final routeDeadline = _routeStartupOwner.workCutoff;
    final effectiveDeadline = _routeStartupOwner.isCompletedSuccessfully
        ? deadline
        : deadline == null || routeDeadline.isBefore(deadline)
            ? routeDeadline
            : deadline;
    final expanded = <PlaybackSource>[];
    for (var sourceIndex = 0; sourceIndex < sources.length; sourceIndex += 1) {
      final source = sources[sourceIndex];
      if (!_isHlsSource(source)) {
        expanded.add(source);
        continue;
      }

      try {
        var remaining = effectiveDeadline?.difference(DateTime.now());
        if (!_routeStartupOwner.isCompletedSuccessfully &&
            (remaining == null ||
                _routeStartupOwner.remainingWorkBudget < remaining)) {
          remaining = _routeStartupOwner.remainingWorkBudget;
        }
        if (remaining != null && remaining <= Duration.zero) {
          if (!_routeStartupOwner.isCompletedSuccessfully) {
            throw const MobilePlaybackRouteStartupExpired();
          }
          DiagnosticLog.add(
            'native quality variants bounded reason=aggregate_deadline '
            'remainingSources=${sources.length - sourceIndex}',
          );
          expanded.addAll(sources.skip(sourceIndex));
          break;
        }
        final variants = remaining == null
            ? await _hlsVariantsFor(source)
            : await _hlsVariantsFor(source).timeout(remaining);
        if (variants.isNotEmpty) {
          final labels = variants.map(_qualityLabel).join(',');
          if (_manualLibVlcStrictForSource(source)) {
            final libVlcProvenVariants = variants
                .where(_hasCurrentLibVlcProofForSource)
                .toList(growable: false);
            final libVlcUnprovenVariants = variants
                .where(
                  (variant) => !_hasCurrentLibVlcProofForSource(variant),
                )
                .toList(growable: false);
            expanded.addAll(libVlcProvenVariants);
            expanded.add(source.copyWith(quality: 'Auto'));
            expanded.addAll(libVlcUnprovenVariants);
            DiagnosticLog.add(
              'native quality variants provider=${source.providerId} count=${variants.length} labels=$labels provenForLibVlc=${libVlcProvenVariants.length} order=libvlc-proof-then-adaptive-then-unproven',
            );
            continue;
          }
          expanded.addAll(variants);
          expanded.add(source.copyWith(quality: 'Auto'));
          DiagnosticLog.add(
            'native quality variants provider=${source.providerId} count=${variants.length} labels=$labels order=variants-first adaptive=auto',
          );
          continue;
        }
      } on TimeoutException {
        if (!_routeStartupWorkAvailable) {
          throw const MobilePlaybackRouteStartupExpired();
        }
        DiagnosticLog.add(
          'native quality variants bounded reason=aggregate_deadline '
          'remainingSources=${sources.length - sourceIndex}',
        );
        expanded.addAll(sources.skip(sourceIndex));
        break;
      } catch (error) {
        if (error is MobilePlaybackRouteStartupExpired ||
            !_routeStartupWorkAvailable) {
          throw const MobilePlaybackRouteStartupExpired();
        }
        DiagnosticLog.add(
          'native quality variants failed provider=${source.providerId} error=${_safeDiagnosticError(error)}',
        );
      }
      expanded.add(source);
    }

    final seen = <String>{};
    final unique = [
      for (final source in expanded)
        if (seen.add(
          '${source.providerId}|${source.quality ?? 'auto'}|${source.url}',
        ))
          source,
    ];
    if (unique.length > _publicIptvMaxExpandedSources &&
        unique.every(_isPublicIptvSource)) {
      DiagnosticLog.add(
        'native quality variants capped provider=public-iptv count=${unique.length} limit=$_publicIptvMaxExpandedSources',
      );
      return unique.take(_publicIptvMaxExpandedSources).toList();
    }
    return unique;
  }

  List<PlaybackSource> _prioritizePreferredQuality(
    List<PlaybackSource> sources,
  ) {
    final rankedSources = rankedNativePlaybackSources(
      sources,
      sourceClassAllowed: AppState.playbackSourceClassAllowedForNative,
      p2pConfig: _p2pPriorityConfigFromSettings(),
    );
    final recoveryCappedSources =
        _applyMedia3RecoveryQualityCeiling(rankedSources);
    if (recoveryCappedSources.length < 2) return recoveryCappedSources;
    if (_usingGlobalOverrides && _qualityPreferenceMode == 'higher') {
      return recoveryCappedSources;
    }
    if (_usingGlobalOverrides && _qualityPreferenceMode == 'dataSaver') {
      final saver = recoveryCappedSources.toList()
        ..sort(
          (a, b) => _dataSaverQualityRank(
            _qualityLabel(a),
          ).compareTo(_dataSaverQualityRank(_qualityLabel(b))),
        );
      return saver;
    }
    if (_usingGlobalOverrides && _qualityPreferenceMode == 'recommended') {
      final targetIndex = _recommendedQualityIndex(recoveryCappedSources);
      if (targetIndex <= 0) return recoveryCappedSources;
      return _moveQualityRankToFront(
        recoveryCappedSources,
        _qualityRank(_qualityLabel(recoveryCappedSources[targetIndex])),
      );
    }
    if (_savedAutoQualityUsesRecommended) {
      final targetIndex = _recommendedQualityIndex(recoveryCappedSources);
      if (targetIndex <= 0) return recoveryCappedSources;
      return _moveQualityRankToFront(
        recoveryCappedSources,
        _qualityRank(_qualityLabel(recoveryCappedSources[targetIndex])),
      );
    }
    final preferred = _preferredQuality;
    if (preferred == null ||
        preferred.isEmpty ||
        preferred == 'Auto' ||
        recoveryCappedSources.length < 2) {
      return recoveryCappedSources;
    }
    final preferredRank = _qualityRank(preferred);
    if (_resumeRecoveryExcludedQualityRanks.contains(preferredRank)) {
      DiagnosticLog.add(
        'native preferred quality fallback bypassed preferred=$preferred reason=resume_quality_excluded',
      );
      return recoveryCappedSources;
    }
    final index = recoveryCappedSources.indexWhere(
      (source) => _qualityLabel(source) == preferred,
    );
    var fallbackIndex = -1;
    var fallbackRank = -1;
    if (preferredRank > 0) {
      for (var i = 0; i < recoveryCappedSources.length; i++) {
        final rank = _qualityRank(_qualityLabel(recoveryCappedSources[i]));
        if (rank > 0 && rank <= preferredRank && rank > fallbackRank) {
          fallbackIndex = i;
          fallbackRank = rank;
        }
      }
    }
    final targetIndex = index >= 0 ? index : fallbackIndex;
    if (targetIndex <= 0) return recoveryCappedSources;
    if (index >= 0) {
      return _moveQualityLabelToFront(recoveryCappedSources, preferred);
    }
    return _moveQualityRankToFront(recoveryCappedSources, fallbackRank);
  }

  List<PlaybackSource> _applyMedia3RecoveryQualityCeiling(
    List<PlaybackSource> sources,
  ) {
    final ceilingRank = _media3RecoveryQualityCeilingRank;
    if (ceilingRank == null || ceilingRank <= 0 || sources.length < 2) {
      return sources;
    }
    final setAt = _media3RecoveryQualityCeilingSetAt;
    if (setAt == null ||
        DateTime.now().difference(setAt) > const Duration(minutes: 2)) {
      _clearMedia3RecoveryQualityCeiling(reason: 'expired');
      return sources;
    }
    final knownCapped = [
      for (final source in sources)
        if (_qualityRank(_qualityLabel(source)) > 0 &&
            _qualityRank(_qualityLabel(source)) <= ceilingRank &&
            !_resumeRecoveryExcludedQualityRanks.contains(
              _qualityRank(_qualityLabel(source)),
            ))
          source,
    ];
    final adaptiveFallback = [
      for (final source in sources)
        if (_isAdaptiveHlsAutoSource(source)) source,
    ];
    if (knownCapped.isNotEmpty) {
      final keptCount = knownCapped.length + adaptiveFallback.length;
      if (keptCount != sources.length) {
        DiagnosticLog.add(
          'native media3 recovery quality ceiling applied rank=$ceilingRank skipped=${sources.length - keptCount} kept=$keptCount adaptive=${adaptiveFallback.length} reason=${_media3RecoveryQualityCeilingReason ?? 'unknown'}',
        );
      }
      return <PlaybackSource>[...knownCapped, ...adaptiveFallback];
    }
    if (_resumeRecoveryExcludedQualityRanks.contains(ceilingRank)) {
      final fallback = [
        for (final source in sources)
          if (!_resumeRecoveryExcludedQualityRanks.contains(
            _qualityRank(_qualityLabel(source)),
          ))
            source,
      ];
      final higherFallback = fallback.any(
        (source) => _qualityRank(_qualityLabel(source)) > ceilingRank,
      );
      if (higherFallback) {
        DiagnosticLog.add(
          'native media3 recovery quality ceiling bypassed rank=$ceilingRank kept=${fallback.length} reason=ceiling_quality_excluded',
        );
        return fallback;
      }
    }
    if (_resumeRecoveryExcludedQualityRanks.isNotEmpty) {
      final fallback = [
        for (final source in sources)
          if (!_resumeRecoveryExcludedQualityRanks.contains(
            _qualityRank(_qualityLabel(source)),
          ))
            source,
      ];
      if (fallback.isNotEmpty) {
        DiagnosticLog.add(
          'native media3 recovery quality ceiling bypassed rank=$ceilingRank kept=${fallback.length} reason=all_capped_qualities_excluded',
        );
        return fallback;
      }
    }
    return sources;
  }

  List<PlaybackSource> _moveQualityLabelToFront(
    List<PlaybackSource> sources,
    String quality,
  ) {
    return [
      ...sources.where((source) => _qualityLabel(source) == quality),
      ...sources.where((source) => _qualityLabel(source) != quality),
    ];
  }

  List<PlaybackSource> _moveQualityRankToFront(
    List<PlaybackSource> sources,
    int rank,
  ) {
    return [
      ...sources.where((source) => _qualityRank(_qualityLabel(source)) == rank),
      ...sources.where((source) => _qualityRank(_qualityLabel(source)) != rank),
    ];
  }

  List<PlaybackSource> _preferStableHlsOrderingForAutoPass(
    List<PlaybackSource> sources,
    _QualityPass qualityPass, {
    required _NativePlaybackEngine engine,
  }) {
    if (sources.length < 2 || qualityPass.target != null) return sources;
    final knownHls = <PlaybackSource>[];
    final adaptive = <PlaybackSource>[];
    final other = <PlaybackSource>[];
    for (final source in sources) {
      if (_isAdaptiveHlsAutoSource(source)) {
        adaptive.add(source);
      } else if (_isHlsSource(source) &&
          _qualityRank(_qualityLabel(source)) > 0) {
        knownHls.add(source);
      } else {
        other.add(source);
      }
    }
    if (knownHls.isNotEmpty && adaptive.isNotEmpty) {
      knownHls.sort(
        (a, b) => _stableHlsAutoSortRank(
          _qualityLabel(a),
          engine,
        ).compareTo(_stableHlsAutoSortRank(_qualityLabel(b), engine)),
      );
      if (_useLowDriftMedia3HlsResumeOrdering(engine) && other.isNotEmpty) {
        DiagnosticLog.add(
          'native stable hls auto ordering known=${knownHls.length} adaptive=${adaptive.length} other=${other.length} reason=resume_non_hls_before_hls',
        );
        return <PlaybackSource>[...other, ...knownHls, ...adaptive];
      }
      DiagnosticLog.add(
        'native stable hls auto ordering known=${knownHls.length} adaptive=${adaptive.length} other=${other.length} reason=${_useLowDriftMedia3HlsResumeOrdering(engine) ? 'media3_resume_low_drift_fixed_quality_before_adaptive_auto' : 'fixed_quality_before_adaptive_auto'}',
      );
      return <PlaybackSource>[...knownHls, ...adaptive, ...other];
    }
    if (knownHls.length > 1 && _useLowDriftMedia3HlsResumeOrdering(engine)) {
      knownHls.sort(
        (a, b) => _stableHlsAutoSortRank(
          _qualityLabel(a),
          engine,
        ).compareTo(_stableHlsAutoSortRank(_qualityLabel(b), engine)),
      );
      DiagnosticLog.add(
        'native stable hls auto ordering known=${knownHls.length} adaptive=0 other=${other.length} reason=media3_resume_low_drift_fixed_quality',
      );
      if (other.isNotEmpty) {
        DiagnosticLog.add(
          'native stable hls auto ordering known=${knownHls.length} adaptive=0 other=${other.length} reason=resume_non_hls_before_hls',
        );
        return <PlaybackSource>[...other, ...knownHls];
      }
      return <PlaybackSource>[...knownHls, ...other];
    }
    if (adaptive.isEmpty) return sources;
    DiagnosticLog.add(
      'native adaptive hls auto prioritized count=${adaptive.length} fixed=${other.length} reason=auto_master_first',
    );
    return <PlaybackSource>[...adaptive, ...other];
  }

  bool _useLowDriftMedia3HlsResumeOrdering(_NativePlaybackEngine engine) {
    return (engine == _NativePlaybackEngine.exoplayer ||
            engine == _NativePlaybackEngine.libvlc) &&
        _hasSavedResumeProgressForRoute &&
        !_isLiveTvMode &&
        _qualityPassTargetForCurrentSettings() == null &&
        !_usingHigherAvailableFirst;
  }

  int _stableHlsAutoSortRank(String label, _NativePlaybackEngine engine) {
    if (!_useLowDriftMedia3HlsResumeOrdering(engine)) {
      return _recommendedQualitySortRank(label);
    }
    final rank = _qualityRank(label);
    const order = <int>[
      1080,
      720,
      800,
      674,
      534,
      480,
      452,
      360,
      1440,
      2160,
      4320,
      336,
      266,
      240,
    ];
    final index = order.indexOf(rank);
    return index >= 0 ? index : order.length;
  }

  int _recommendedQualitySortRank(String label) {
    final rank = _qualityRank(label);
    const order = <int>[
      720,
      1080,
      800,
      674,
      534,
      480,
      452,
      360,
      336,
      266,
      240,
    ];
    final index = order.indexOf(rank);
    return index >= 0 ? index : order.length;
  }

  bool _isAdaptiveHlsAutoSource(PlaybackSource source) {
    if (!_isHlsSource(source)) return false;
    final quality = (source.quality ?? '').trim().toLowerCase();
    return quality == 'auto' || quality == 'adaptive';
  }

  PlaybackSource? _bestAutoQualitySource(List<PlaybackSource> sources) {
    final rankedSources = rankedNativePlaybackSources(
      sources,
      sourceClassAllowed: AppState.playbackSourceClassAllowedForNative,
      p2pConfig: _p2pPriorityConfigFromSettings(),
    );
    if (rankedSources.isEmpty) return null;
    if (_usingGlobalOverrides && _qualityPreferenceMode == 'dataSaver') {
      return rankedSources.reduce(
        (a, b) => _dataSaverQualityRank(_qualityLabel(a)) <=
                _dataSaverQualityRank(_qualityLabel(b))
            ? a
            : b,
      );
    }
    if (_usingGlobalOverrides && _qualityPreferenceMode == 'recommended') {
      final index = _recommendedQualityIndex(rankedSources);
      return rankedSources[index < 0 ? 0 : index];
    }
    if (_savedAutoQualityUsesRecommended) {
      final index = _recommendedQualityIndex(rankedSources);
      return rankedSources[index < 0 ? 0 : index];
    }
    return rankedSources.first;
  }

  bool get _savedAutoQualityUsesRecommended {
    final preferred = _preferredQuality;
    return !_usingGlobalOverrides &&
        !_batterySaverPlaybackActive &&
        !_isP2pOnlySourceRoute &&
        (preferred == null || preferred.isEmpty || preferred == 'Auto');
  }

  int _recommendedQualityIndex(List<PlaybackSource> rankedSources) {
    final preferredRanks = <int>[
      720,
      1080,
      800,
      674,
      534,
      480,
      452,
      360,
      336,
      266,
      240,
    ];
    for (final wanted in preferredRanks) {
      final index = rankedSources.indexWhere(
        (source) => _qualityRank(_qualityLabel(source)) == wanted,
      );
      if (index >= 0) return index;
    }
    return 0;
  }

  Future<http.Response> _fetchHlsVariantManifest(
    PlaybackSource source,
  ) async {
    final uri = Uri.parse(source.url);
    for (var attempt = 0; attempt < 2; attempt += 1) {
      if (!_routeStartupWorkAvailable) {
        throw const MobilePlaybackRouteStartupExpired();
      }
      final client = http.Client();
      void cancelProbe() => client.close();
      _routeStartupOwner.cancellation.addListener(cancelProbe);
      try {
        return await client
            .get(uri, headers: source.headers)
            .timeout(_routeStartupTimeout(_hlsVariantManifestTimeout));
      } on TimeoutException {
        if (attempt > 0) rethrow;
        DiagnosticLog.add(
          'native quality variants retry provider=${source.providerId} reason=manifest_timeout',
        );
        if (!_routeStartupOwner
            .canChargeOptionalDelay(_hlsVariantManifestRetryDelay)) {
          throw const MobilePlaybackRouteStartupExpired();
        }
        await Future<void>.delayed(_hlsVariantManifestRetryDelay);
      } finally {
        _routeStartupOwner.cancellation.removeListener(cancelProbe);
        client.close();
      }
    }
    throw StateError('HLS variant manifest retry exhausted.');
  }

  Future<List<PlaybackSource>> _hlsVariantsFor(PlaybackSource source) async {
    final uri = Uri.parse(source.url);
    final response = await _fetchHlsVariantManifest(source);
    if (response.statusCode < 200 || response.statusCode >= 300) {
      return const <PlaybackSource>[];
    }

    final body = utf8.decode(response.bodyBytes, allowMalformed: true);
    if (!body.contains('#EXT-X-STREAM-INF')) return const <PlaybackSource>[];

    final lines = _hlsManifestLines(body);
    if (_hlsManifestHasSeparateAudioRenditions(lines)) {
      DiagnosticLog.add(
        'native quality variants skipped provider=${source.providerId} reason=separate_audio_renditions',
      );
      return const <PlaybackSource>[];
    }

    final variants = <PlaybackSource>[];
    var skippedCleartextVariants = 0;
    for (var index = 0; index < lines.length; index++) {
      final line = lines[index];
      if (!line.startsWith('#EXT-X-STREAM-INF')) continue;
      if (index + 1 >= lines.length) continue;
      final next = lines[index + 1];
      if (next.startsWith('#')) continue;

      final resolution = RegExp(r'RESOLUTION=(\d+)x(\d+)').firstMatch(line);
      final bandwidth = RegExp(r'BANDWIDTH=(\d+)').firstMatch(line);
      final height = resolution?.group(2);
      final mbps = bandwidth == null
          ? null
          : (int.tryParse(bandwidth.group(1) ?? '') ?? 0) / 1000000;
      final label = _normalizedHlsVariantQualityLabel(
        heightLabel: height,
        mbps: mbps,
        fallbackIndex: variants.length + 1,
      );
      final variantUri = uri.resolve(next);
      if (_isPublicIptvSource(source) && variantUri.scheme != 'https') {
        skippedCleartextVariants += 1;
        continue;
      }
      final masterGroupId = source.mirrorGroupId ??
          source.sourceId ??
          'hls:${source.providerId}:${source.url.hashCode}';
      variants.add(
        PlaybackSource(
          providerId: source.providerId,
          name: source.name,
          url: variantUri.toString(),
          type: source.type,
          quality: label,
          sourceClass: source.sourceClass,
          sourceId: source.sourceId ?? masterGroupId,
          mirrorGroupId: source.mirrorGroupId ?? masterGroupId,
          mirrorRank: source.mirrorRank,
          displayLabel: source.displayLabel,
          healthBucket: source.healthBucket,
          sourcePoolVersion: source.sourcePoolVersion,
          compatibility: source.compatibility,
          headers: source.headers,
          subtitles: source.subtitles,
          drm: source.drm,
        ),
      );
    }
    if (_isPublicIptvSource(source) && skippedCleartextVariants > 0) {
      DiagnosticLog.add(
        'native quality variants skipped cleartext provider=${source.providerId} count=$skippedCleartextVariants',
      );
    }

    return variants;
  }

  String _normalizedHlsVariantQualityLabel({
    required String? heightLabel,
    required double? mbps,
    required int fallbackIndex,
  }) {
    final height = int.tryParse(heightLabel ?? '');
    if (height != null && height > 0) {
      return '${_normalizedPlaybackQualityHeight(height)}p';
    }
    if (mbps != null && mbps > 0) return '${mbps.toStringAsFixed(1)} Mbps';
    return 'Variant $fallbackIndex';
  }

  bool _hlsManifestHasSeparateAudioRenditions(List<String> lines) {
    for (final line in lines) {
      final upper = line.toUpperCase();
      if (upper.startsWith('#EXT-X-MEDIA') && upper.contains('TYPE=AUDIO')) {
        return true;
      }
      if (upper.startsWith('#EXT-X-STREAM-INF') && upper.contains('AUDIO=')) {
        return true;
      }
    }
    return false;
  }

  Future<bool> _pauseForOptionSheet() async {
    final controller = _controller;
    if (controller == null || !controller.isInitialized) {
      if (mounted) setState(() => _optionSheetOpen = true);
      return false;
    }
    final wasPlaying = controller.isPlaying || _settingsPausedPlayback;
    _optionSheetPausedPlayback = wasPlaying;
    if (mounted && _settingsExpanded) {
      setState(() {
        _settingsExpanded = false;
        _settingsPausedPlayback = false;
        _optionSheetOpen = true;
      });
    } else if (mounted) {
      setState(() => _optionSheetOpen = true);
    }
    if (controller.isPlaying) {
      await controller.pause();
    }
    return wasPlaying;
  }

  bool _openOptionSheetWithoutPause() {
    final wasPlaying = _controller?.isPlaying == true;
    _optionSheetPausedPlayback = false;
    if (mounted && _settingsExpanded) {
      setState(() {
        _settingsExpanded = false;
        _settingsPausedPlayback = false;
        _optionSheetOpen = true;
      });
    } else if (mounted) {
      setState(() => _optionSheetOpen = true);
    }
    return wasPlaying;
  }

  Future<void> _resumeAfterOptionSheet(bool shouldResume) async {
    final optionSheetPausedPlayback = _optionSheetPausedPlayback;
    _optionSheetPausedPlayback = false;
    if (mounted && _optionSheetOpen) {
      setState(() => _optionSheetOpen = false);
    }
    final controller = _controller;
    if (shouldResume &&
        optionSheetPausedPlayback &&
        controller != null &&
        controller.isInitialized) {
      await controller.play();
    }
    if (mounted) _scheduleControlsHide();
  }

  void _clearOptionSheetOverlay() {
    _optionSheetPausedPlayback = false;
    if (!mounted || !_optionSheetOpen) return;
    setState(() => _optionSheetOpen = false);
  }

  Future<void> _restorePlaybackAfterExternalRoute() async {
    if (!mounted || _playerClosing || _openingSource) return;
    if (_controller?.isInitialized == true) {
      _restoringFromExternalRoute = false;
      if (_optionSheetOpen) {
        setState(() => _optionSheetOpen = false);
      }
      _scheduleControlsHide();
      return;
    }
    final source = _activeSource;
    if (source == null) {
      _restoringFromExternalRoute = false;
      if (_optionSheetOpen) {
        setState(() => _optionSheetOpen = false);
      }
      _scheduleControlsHide();
      return;
    }

    final resumePosition = _restoreResumePosition.inSeconds >= 3
        ? _restoreResumePosition
        : _lastKnownPlaybackPosition;
    DiagnosticLog.add(
      'native restore after external route provider=${source.providerId} position=${resumePosition.inSeconds}s',
    );
    setState(() {
      _loading = true;
      _controlsVisible = true;
      _optionSheetOpen = false;
      _settingsExpanded = false;
      _statusMessage = 'Restoring playback...';
    });
    final opened = await _openSource(
      source,
      resumePosition: resumePosition,
      statusMessage: 'Restoring playback...',
    );
    if (opened && !_restoreShouldResumePlayback) {
      await _controller?.pause();
    }
    if (!opened && mounted) {
      setState(() {
        _loading = false;
        _statusMessage = null;
      });
    }
    _restoringFromExternalRoute = false;
    _restoreShouldResumePlayback = false;
    _restoreResumePosition = Duration.zero;
    _scheduleControlsHide();
  }

  bool _syncSubtitleText() {
    final controller = _controller;
    if (controller == null ||
        !controller.isInitialized ||
        _subtitleCues.isEmpty) {
      if (_subtitleText != null) {
        _subtitleText = null;
        return true;
      }
      return false;
    }

    final position = _subtitlePlaybackPosition(controller) +
        Duration(milliseconds: (_subtitleDelaySeconds * 1000).round());
    String? nextText;
    for (final cue in _subtitleCues) {
      if (position >= cue.start && position <= cue.end) {
        nextText = cue.text;
        break;
      }
    }
    if (nextText != _subtitleText) {
      _subtitleText = nextText;
      return true;
    }
    return false;
  }

  Duration _subtitlePlaybackPosition(_NativePlaybackController controller) {
    return _resumeAnchoredPlaybackPosition(controller);
  }

  void _handleVerticalDrag(DragUpdateDetails details, double width) {
    if (_locked) return;
    final controller = _controller;
    final keepControlsVisible = _controlsVisible;
    final isLeftSide = details.localPosition.dx < width / 2;
    final delta = -details.delta.dy / 260;
    final nextBrightness = (_brightnessPreview + delta).clamp(0, 1).toDouble();
    final nextVolume = (_volumePreview + delta).clamp(0, 1).toDouble();
    setState(() {
      if (isLeftSide) {
        _brightnessPreview = nextBrightness;
        _gestureIcon = Icons.brightness_6_rounded;
        _gestureLabel = 'Brightness ${(_brightnessPreview * 100).round()}%';
      } else {
        _volumePreview = nextVolume;
        _gestureIcon = Icons.volume_up_rounded;
        _gestureLabel = 'Volume ${(_volumePreview * 100).round()}%';
      }
      _controlsVisible = keepControlsVisible;
    });
    if (isLeftSide) {
      AppState.updateNativePlayerBrightness(nextBrightness);
      _displayChannel.invokeMethod<void>(
          'setBrightness', {'value': nextBrightness}).catchError((_) {});
    } else {
      AppState.updateNativePlayerVolume(nextVolume);
      if (controller != null) {
        controller.setVolume(nextVolume);
      }
    }
    _scheduleControlsHide();
  }

  void _clearGestureOverlay() {
    Future<void>.delayed(const Duration(milliseconds: 650), () {
      if (mounted && !_playerClosing) setState(() => _gestureLabel = null);
    });
  }

  void _clearGestureHintState() {
    _gestureHintTimer?.cancel();
    _gestureHintScheduled = false;
    _gestureHintVisible = false;
  }

  void _scheduleGestureHintIfNeeded({
    required bool nativeControlsReady,
    required bool playbackStarted,
    required bool hudVisible,
    required bool compactPlayer,
  }) {
    final shouldShow = _shouldShowGestureHint(
      nativeControlsReady: nativeControlsReady,
      playbackStarted: playbackStarted,
      hudVisible: hudVisible,
      compactPlayer: compactPlayer,
    );
    if (_gestureHintVisible == shouldShow || _gestureHintScheduled) {
      return;
    }
    _gestureHintScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) {
        _gestureHintScheduled = false;
        return;
      }
      final shouldShow = _shouldShowGestureHint(
        nativeControlsReady: nativeControlsReady,
        playbackStarted: _playbackHasStartedForGestureHint(),
        hudVisible: _controlsVisible,
        compactPlayer: compactPlayer,
      );
      setState(() {
        _gestureHintScheduled = false;
        _gestureHintVisible = shouldShow;
      });
    });
  }

  bool _shouldShowGestureHint({
    required bool nativeControlsReady,
    required bool playbackStarted,
    required bool hudVisible,
    required bool compactPlayer,
  }) {
    return !_loading &&
        _playbackWaitMessage == null &&
        playbackStarted &&
        hudVisible &&
        nativeControlsReady &&
        !compactPlayer &&
        !_locked &&
        !_settingsExpanded &&
        !_optionSheetOpen &&
        !_pictureInPictureActive &&
        !_systemPipHandoffActive &&
        !_resumeDialogOpen &&
        !_playerClosing;
  }

  bool _playbackHasStartedForGestureHint({Duration? position}) {
    final controller = _controller;
    if (controller == null || !controller.isInitialized) return false;
    if (!controller.isPlaying) return false;
    final effectivePosition = position ??
        _bestKnownProgressPosition(controller, _fallbackControlDuration());
    return effectivePosition >= const Duration(seconds: 2);
  }

  bool get _skipSegmentsSupported => !_isLiveTvMode;

  _PlayerSkipSegment? _activeSkipSegment(
    Duration position,
    Duration duration, {
    bool allowFallback = true,
  }) {
    if (!_skipSegmentsSupported) return null;
    final remoteSegment = activePlaybackSkipSegment(
      _skipSegments,
      position,
      duration,
    );
    if (remoteSegment != null) {
      return _PlayerSkipSegment(
        label: remoteSegment.label,
        target: remoteSegment.targetFor(duration),
      );
    }
    if (!allowFallback ||
        !allowFixedSkipSegmentFallback(
          season: _skipSegmentSeason,
          episode: _skipSegmentEpisode,
        )) {
      return null;
    }
    if (duration.inMinutes < 15) return null;
    final seconds = position.inSeconds;
    final totalSeconds = duration.inSeconds;
    if (seconds >= 0 && seconds <= 80) {
      final fallbackTarget = defaultFixedIntroSkipTarget();
      final target = fallbackTarget < Duration(seconds: totalSeconds - 30)
          ? fallbackTarget
          : Duration(seconds: totalSeconds - 30);
      if (target > position + const Duration(seconds: 5)) {
        return _PlayerSkipSegment(label: 'Skip intro', target: target);
      }
    }
    final remainingSeconds = totalSeconds - seconds;
    if (remainingSeconds <= 105 && remainingSeconds > 8) {
      return _PlayerSkipSegment(
        label: 'Skip outro',
        target: Duration(seconds: math.max(0, totalSeconds - 2)),
      );
    }
    return null;
  }

  Future<void> _skipToSegment(
    _PlayerSkipSegment segment, {
    bool automatic = false,
  }) async {
    final controller = _controller;
    if (controller == null || !controller.isInitialized || _locked) return;
    final controlsWereVisible = _controlsVisible;
    final shouldPlay = controller.isPlaying;
    try {
      _lastWatchdogPosition = segment.target;
      _resetTransientPlaybackDebounce();
      final duration = _bestKnownProgressDuration(controller);
      final current = _bestKnownProgressPosition(controller, duration);
      final sameController = await _seekControllerToPlaybackPosition(
        controller,
        segment.target,
        fromPosition: current,
        reason: automatic ? 'auto_skip_segment' : 'skip_segment',
        markManualSeek: true,
      );
      if (!sameController) return;
      _markManualSeekForIntegrity(
        current,
        segment.target,
        reason: automatic ? 'auto_skip_segment' : 'skip_segment',
      );
      await _resumePlaybackAfterSeek(controller, shouldPlay: shouldPlay);
    } catch (error) {
      DiagnosticLog.add(
        'native skip segment seek failed reason=${_safeDiagnosticError(error)}',
      );
      return;
    }
    if (!mounted || _playerClosing || _controller != controller) return;
    setState(() => _controlsVisible = automatic ? controlsWereVisible : true);
    _scheduleControlsHide();
  }

  Future<void> _close([String? result]) async {
    _hideControlsTimer?.cancel();
    if (mounted) {
      setState(() {
        _allowPop = true;
        _controlsVisible = false;
        _settingsExpanded = false;
        _clearGestureHintState();
      });
    } else {
      _allowPop = true;
      _controlsVisible = false;
      _settingsExpanded = false;
      _clearGestureHintState();
    }
    if (_playerClosing) {
      await _forcePopPlayerRoute(result ?? 'closed');
      return;
    }
    _playerClosing = true;
    _systemPipHandoffActive = false;
    unawaited(_setAndroidAutoPipOnUserLeave(false));
    _stopStallWatchdog();
    DiagnosticLog.add(
      'native close saving progress result=${result ?? 'closed'} hasController=${_controller != null}',
    );
    _sendPlaybackFeedback('closed');
    if (result != 'completed' &&
        (_controller != null ||
            (_lastKnownPlaybackDuration.inSeconds > 0 &&
                _lastKnownPlaybackPosition.inSeconds >= 3))) {
      _saveNativeProgress(force: true);
    }
    final detachLibVlcRelease = _detachLibVlcControllerForAsyncRelease(
      'route_close',
    );
    if (!detachLibVlcRelease) {
      await _disposeCurrentController(
        awaitLibVlcRelease: true,
        saveProgress: false,
      );
    } else if (mounted) {
      setState(() {});
    }
    final stopBridge = _stopP2pBridgeForPolicy('route_close');
    if (detachLibVlcRelease) {
      unawaited(stopBridge);
    } else {
      await stopBridge;
    }
    await _forcePopPlayerRoute(result ?? 'closed');
  }

  Future<void> _forcePopPlayerRoute(String result) async {
    if (!mounted || _playerPopIssued) return;
    _playerPopIssued = true;
    if (!_allowPop && mounted) {
      setState(() => _allowPop = true);
    }
    await Future<void>.delayed(Duration.zero);
    if (!mounted) return;
    final navigator = Navigator.of(context);
    if (_optionSheetOpen && navigator.canPop()) {
      navigator.pop();
      if (mounted) setState(() => _optionSheetOpen = false);
      await Future<void>.delayed(Duration.zero);
      if (!mounted) return;
    }
    if (navigator.canPop()) {
      navigator.pop(result);
    }
  }

  Future<void> _requestClose([String? result]) async {
    if (_nativeProvidersExhausted || _controller == null) {
      await _close(result);
      return;
    }
    if (_isLiveTvMode) {
      DiagnosticLog.add(
        'native exit confirmation skipped reason=live-tv-route',
      );
      await _close(result);
      return;
    }
    if (!AppState.playerBehaviorSettings.value.confirmBeforeLeaving) {
      await _close(result);
      return;
    }
    _exitConfirmationOpen = true;
    final shouldResume = await _pauseForExitConfirmation();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Leave playback?'),
        content: const Text(
          'Playback will stop and your progress will be saved.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('Stay'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text('Leave'),
          ),
        ],
      ),
    );
    _exitConfirmationOpen = false;
    if (confirmed == true) {
      await _close(result);
    } else {
      await _resumeAfterExitConfirmation(shouldResume);
    }
  }

  Future<bool> _pauseForExitConfirmation() async {
    final controller = _controller;
    if (controller == null || !controller.isInitialized) return false;
    final wasPlaying = controller.isPlaying;
    if (!wasPlaying) return false;
    DiagnosticLog.add('native exit confirmation paused playback');
    try {
      await controller.pause().timeout(const Duration(milliseconds: 700));
    } catch (error) {
      DiagnosticLog.add(
        'native exit confirmation pause failed error=${_safeDiagnosticError(error)}',
      );
    }
    return true;
  }

  Future<void> _resumeAfterExitConfirmation(bool shouldResume) async {
    final controller = _controller;
    if (!shouldResume ||
        _playerClosing ||
        controller == null ||
        !controller.isInitialized) {
      return;
    }
    DiagnosticLog.add('native exit confirmation cancelled; resuming playback');
    try {
      _userPaused = false;
      await controller.play();
    } catch (error) {
      DiagnosticLog.add(
        'native exit confirmation resume failed error=${_safeDiagnosticError(error)}',
      );
    }
  }

  Future<Duration> _resumePositionFor(Duration duration) async {
    if (_completionCloseStarted || _playerClosing) return Duration.zero;

    final saved = _savedResumePositionFor(duration);
    if (saved <= Duration.zero) return Duration.zero;

    final startBehavior = AppState.playerBehaviorSettings.value.startBehavior;
    if (startBehavior == 'restart') return Duration.zero;
    if (startBehavior == 'resume') return saved;
    if (_resumePromptHandled) {
      return _resumePromptAccepted ? saved : Duration.zero;
    }
    _resumePromptHandled = true;
    _resumePromptAccepted = await _confirmResumePlayback(saved) ?? false;
    return _resumePromptAccepted ? saved : Duration.zero;
  }

  Duration _savedResumePositionFor(Duration duration) {
    if (_completionCloseStarted || _playerClosing) return Duration.zero;

    final item = _progressItem;
    final key = _playbackKey;
    if (item == null || key == null) return Duration.zero;

    final entry = AppState.progressFor(item, playbackKey: key);
    if (entry == null || entry.watchedSeconds <= 0) return Duration.zero;

    final saved = Duration(seconds: entry.watchedSeconds);
    if (duration.inSeconds > 0) {
      final maxResume = duration - const Duration(minutes: 2);
      if (maxResume <= Duration.zero || saved >= maxResume)
        return Duration.zero;
    }
    return saved;
  }

  Duration _automaticResumePositionFor(
    Duration duration, {
    bool promptUnavailable = false,
  }) {
    final saved = _savedResumePositionFor(duration);
    if (saved <= Duration.zero) return Duration.zero;
    final startBehavior = AppState.playerBehaviorSettings.value.startBehavior;
    if (startBehavior == 'restart') return Duration.zero;
    if (startBehavior == 'resume') return saved;
    if (promptUnavailable) return saved;
    if (_resumePromptHandled) {
      return _resumePromptAccepted ? saved : Duration.zero;
    }
    return Duration.zero;
  }

  Duration _preOpenPreferredResumePosition(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    final directHls = source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source);
    final directMp4 = mobileIsKnownDirectMp4Source(source);
    final supportsPreOpenResume = (directHls &&
            (engine == _NativePlaybackEngine.exoplayer ||
                engine == _NativePlaybackEngine.libvlc)) ||
        (directMp4 &&
            (engine == _NativePlaybackEngine.exoplayer ||
                engine == _NativePlaybackEngine.libvlc));
    if (!supportsPreOpenResume) {
      return _automaticResumePositionFor(Duration.zero);
    }
    final saved = _savedResumePositionFor(Duration.zero);
    if (saved <= Duration.zero) return Duration.zero;
    if (_preferSavedResumeOnInitialOpen) return saved;
    final startBehavior = AppState.playerBehaviorSettings.value.startBehavior;
    if (startBehavior == 'restart') return Duration.zero;
    if (startBehavior == 'resume') return saved;
    if (_resumePromptHandled) {
      return _resumePromptAccepted ? saved : Duration.zero;
    }
    return saved;
  }

  bool _shouldRevealPlayerBeforeResumePrompt(Duration duration) {
    if (_resumePromptHandled) return false;
    if (AppState.playerBehaviorSettings.value.startBehavior != 'ask') {
      return false;
    }
    return _savedResumePositionFor(duration) > Duration.zero;
  }

  bool _resumePromptCanOpenForController(_NativePlaybackController controller) {
    if (!controller.isInitialized || controller.hasError) return false;
    if (controller.duration <= Duration.zero) return false;
    if (controller.size == Size.zero) return false;
    return true;
  }

  Duration _fallbackControlDuration() {
    final controllerDuration = _controller?.duration ?? Duration.zero;
    if (controllerDuration > Duration.zero &&
        !_durationLooksLikeShortVodPlaceholder(controllerDuration)) {
      return controllerDuration;
    }
    if (_lastKnownPlaybackDuration > Duration.zero) {
      return _lastKnownPlaybackDuration;
    }
    if (_libVlcContinuousTsActive) return Duration.zero;
    final item = _progressItem;
    final key = _playbackKey;
    if (item == null || key == null) return Duration.zero;
    final entry = AppState.progressFor(item, playbackKey: key);
    final seconds = entry?.durationSeconds ?? 0;
    if (seconds <= 0) return Duration.zero;
    return Duration(seconds: seconds);
  }

  int? _fallbackProgressDurationSeconds() {
    final duration = _fallbackControlDuration();
    return duration.inSeconds > 0 ? duration.inSeconds : null;
  }

  String _headerCountBucket(int count) {
    if (count <= 0) return 'none';
    if (count <= 3) return '1_to_3';
    if (count <= 6) return '4_to_6';
    return '7_plus';
  }

  String _countDiagnosticBucket(int count) {
    if (count <= 0) return 'none';
    if (count == 1) return '1';
    if (count < 5) return '2_to_4';
    if (count < 25) return '5_to_24';
    if (count < 100) return '25_to_99';
    if (count < 500) return '100_to_499';
    return '500_plus';
  }

  String _durationDiagnosticBucket(Duration duration) {
    final minutes = duration.inMinutes;
    if (minutes <= 0) return 'unknown';
    if (minutes < 30) return 'under_30m';
    if (minutes < 60) return '30_to_59m';
    if (minutes < 120) return '60_to_119m';
    if (minutes < 180) return '120_to_179m';
    return '180m_plus';
  }

  void _scheduleDeferredResumeSeek(Duration position, String providerId,
      _NativePlaybackController controller,
      {bool requiresVisualProof = false}) {
    _cancelDeferredResumeSeek();
    _deferredResumeSeekPosition = position;
    _deferredResumeSeekProviderId = providerId;
    _deferredResumeSeekAttempts = 0;
    _deferredResumeSeekRequiresVisualProof = requiresVisualProof;
    _deferredResumeSeekTimer = Timer.periodic(
      const Duration(milliseconds: 500),
      (_) => unawaited(_tryDeferredResumeSeek(controller)),
    );
    unawaited(_tryDeferredResumeSeek(controller));
  }

  void _cancelDeferredResumeSeek() {
    _deferredResumeSeekTimer?.cancel();
    _deferredResumeSeekTimer = null;
    _deferredResumeSeekPosition = null;
    _deferredResumeSeekProviderId = null;
    _deferredResumeSeekAttempts = 0;
    _deferredResumeSeekInFlight = false;
    _deferredResumeSeekRequiresVisualProof = false;
  }

  Future<void> _tryDeferredResumeSeek(
    _NativePlaybackController controller,
  ) async {
    if (_deferredResumeSeekInFlight) return;
    if (_playerClosing || _controller != controller) {
      _cancelDeferredResumeSeek();
      return;
    }
    final position = _deferredResumeSeekPosition;
    final providerId = _deferredResumeSeekProviderId;
    if (position == null || providerId == null) return;

    _deferredResumeSeekAttempts += 1;
    final nativeClockUnavailable =
        controller.duration <= Duration.zero && controller.size == Size.zero;
    final canTryLibVlcMetadataLessSeek =
        controller.engine == _NativePlaybackEngine.libvlc &&
            controller.isPlaying &&
            _deferredResumeSeekAttempts >= 2;
    final media3VisualProofSatisfied = controller.hasRenderedVideoFrame &&
        controller.size != Size.zero &&
        controller.duration > Duration.zero;
    final media3DirectHlsNeedsVisualBeforeMetadataLessSeek =
        (_deferredResumeSeekRequiresVisualProof ||
                _shouldWaitForMedia3ResumeSeekVisualProof(
                  controller,
                  position,
                )) &&
            !media3VisualProofSatisfied;
    final canTryMedia3MetadataLessSeek =
        controller.engine == _NativePlaybackEngine.exoplayer &&
            controller.isPlaying &&
            _deferredResumeSeekAttempts >= 2 &&
            !media3DirectHlsNeedsVisualBeforeMetadataLessSeek;
    final canTryMetadataLessSeek =
        canTryLibVlcMetadataLessSeek || canTryMedia3MetadataLessSeek;
    if (nativeClockUnavailable && !canTryMetadataLessSeek) {
      if (_deferredResumeSeekAttempts == 8 ||
          _deferredResumeSeekAttempts == 16 ||
          _deferredResumeSeekAttempts == 24) {
        DiagnosticLog.add(
          'native resume seek waiting provider=$providerId position=${position.inSeconds}s attempts=$_deferredResumeSeekAttempts',
        );
      }
      final maxAttempts = (_resumeSeekRetryWindow.inMilliseconds / 500).ceil();
      if (_deferredResumeSeekAttempts < maxAttempts) return;
      DiagnosticLog.add(
        'native resume seek abandoned provider=$providerId position=${position.inSeconds}s reason=metadata clock unavailable',
      );
      _cancelDeferredResumeSeek();
      return;
    }
    if (nativeClockUnavailable && canTryMetadataLessSeek) {
      DiagnosticLog.add(
        'native resume seek trying metadata-less ${controller.engine.id} provider=$providerId position=${position.inSeconds}s attempts=$_deferredResumeSeekAttempts',
      );
    }
    if (media3DirectHlsNeedsVisualBeforeMetadataLessSeek) {
      if (_deferredResumeSeekAttempts == 2 ||
          _deferredResumeSeekAttempts == 8 ||
          _deferredResumeSeekAttempts == 16) {
        DiagnosticLog.add(
          'native resume seek waiting provider=$providerId position=${position.inSeconds}s attempts=$_deferredResumeSeekAttempts reason=media3_first_frame_pending',
        );
      }
      final maxAttempts = (_resumeSeekRetryWindow.inMilliseconds / 500).ceil();
      if (_deferredResumeSeekAttempts < maxAttempts) return;
      DiagnosticLog.add(
        'native resume seek abandoned provider=$providerId position=${position.inSeconds}s reason=media3_first_frame_unavailable action=preserve_resume_anchor',
      );
      _cancelDeferredResumeSeek();
      return;
    }

    _deferredResumeSeekInFlight = true;
    try {
      final seekApplied = await _seekToResumePosition(
        position,
        providerId,
        controller,
      );
      if (seekApplied) {
        _deferredResumeSeekTimer?.cancel();
        _deferredResumeSeekTimer = null;
        DiagnosticLog.add(
          'native resume seek proof armed provider=$providerId position=${position.inSeconds}s',
        );
      }
    } finally {
      _deferredResumeSeekInFlight = false;
    }
  }

  Future<_ResumeSeekProofResult> _waitForDeferredResumeSeekProof(
    _NativePlaybackController controller,
    String providerId,
    Duration position,
  ) async {
    final deadline = DateTime.now().add(
      controller.engine == _NativePlaybackEngine.exoplayer
          ? _resumeSeekRetryWindow
          : const Duration(seconds: 3),
    );
    final lowerBound = position - const Duration(seconds: 3);
    final upperBound = position + const Duration(seconds: 20);
    var stableProofSamples = 0;
    const requiredStableProofSamples = 2;
    while (mounted &&
        !_playerClosing &&
        _controller == controller &&
        DateTime.now().isBefore(deadline)) {
      final observed = controller.position;
      final healthyDecoderSample = controller.isPlaying &&
          !controller.isBuffering &&
          !controller.hasError;
      final media3VisualProofSatisfied = controller.hasRenderedVideoFrame &&
          controller.size != Size.zero &&
          controller.duration > Duration.zero;
      final media3VisualProofRequired =
          (_deferredResumeSeekRequiresVisualProof ||
                  _shouldWaitForMedia3ResumeSeekVisualProof(
                    controller,
                    position,
                  )) &&
              !media3VisualProofSatisfied;
      final visualProofSatisfied =
          !media3VisualProofRequired || media3VisualProofSatisfied;
      if (observed >= lowerBound &&
          observed <= upperBound &&
          healthyDecoderSample &&
          visualProofSatisfied) {
        stableProofSamples += 1;
        if (stableProofSamples >= requiredStableProofSamples) {
          DiagnosticLog.add(
            'native resume seek proof observed provider=$providerId position=${position.inSeconds}s observed=${observed.inSeconds}s samples=$stableProofSamples',
          );
          _lastKnownPlaybackPosition = observed;
          _rememberCrediblePlaybackAnchor(
            observed,
            reason: 'resume_seek_proved',
          );
          _lastCadencePosition = observed;
          _lastCadenceSampleAt = DateTime.now();
          _resetPlaybackCadenceCorrection();
          _resumeProgressAnchorPosition = Duration.zero;
          _resumeProgressAnchorLogSecond = -1;
          _cancelDeferredResumeSeek();
          return _ResumeSeekProofResult.proved;
        }
      } else {
        stableProofSamples = 0;
      }
      if (observed > upperBound) {
        DiagnosticLog.add(
          'native resume seek proof rejected provider=$providerId position=${position.inSeconds}s observed=${observed.inSeconds}s reason=observed_too_far_ahead',
        );
        return _ResumeSeekProofResult.rejected;
      }
      if (_deferredResumeSeekPosition == null) {
        _scheduleDeferredResumeSeek(position, providerId, controller);
      }
      await Future<void>.delayed(const Duration(milliseconds: 250));
    }
    return _ResumeSeekProofResult.timeout;
  }

  Future<bool> _waitForSourceSwitchStartupProof(
    _NativePlaybackController controller,
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) async {
    final patientMedia3ResumeStartupProof =
        _shouldDelayMedia3ResumeSeekUntilVisualProof(
      source,
      engine,
      _resumeProgressAnchorPosition,
    );
    final deadline = DateTime.now().add(
      patientMedia3ResumeStartupProof
          ? const Duration(seconds: 14)
          : _libVlcContinuousTsStartupProofBudget(source, engine),
    );
    var lastPosition = controller.position;
    var stableSamples = 0;
    while (mounted &&
        !_playerClosing &&
        _controller == controller &&
        DateTime.now().isBefore(deadline)) {
      if (engine == _NativePlaybackEngine.libvlc &&
          _isHlsSource(source) &&
          _libVlcContinuousTsUpstreamErrors > 0 &&
          !_libVlcContinuousTsStartupLeadReady) {
        DiagnosticLog.add(
          'native source switch startup proof ended provider=${source.providerId} engine=${engine.id} action=reject_candidate reason=libvlc_continuous_ts_startup_transport_failed',
        );
        return false;
      }
      final position = controller.position;
      final continuousTsPlaybackReady =
          engine == _NativePlaybackEngine.libvlc &&
              _hasSustainedLibVlcContinuousTsPlaybackProof(controller);
      final visuallyReady = controller.isInitialized &&
          controller.isPlaying &&
          !controller.hasError &&
          (controller.hasRenderedVideoFrame || continuousTsPlaybackReady) &&
          (controller.size != Size.zero || continuousTsPlaybackReady);
      final clockReady = controller.duration > Duration.zero ||
          _hasSustainedLibVlcContinuousTsPlaybackProof(controller);
      final resumeAnchoredSwitch =
          _resumeProgressAnchorPosition >= const Duration(seconds: 30);
      final movedSinceLastSample =
          position > lastPosition + const Duration(milliseconds: 250);
      final advanced = movedSinceLastSample ||
          _sourceCredibleWatchSeconds > 0 ||
          (!resumeAnchoredSwitch && position >= const Duration(seconds: 1));
      if (visuallyReady && clockReady && advanced) {
        stableSamples += 1;
        if (stableSamples >= 2) {
          DiagnosticLog.add(
            'native source switch startup proof observed provider=${source.providerId} engine=${engine.id} position=${position.inSeconds}s samples=$stableSamples moved=$movedSinceLastSample resumeAnchored=$resumeAnchoredSwitch',
          );
          _lastKnownPlaybackPosition = position;
          _lastCadencePosition = position;
          _lastCadenceSampleAt = DateTime.now();
          _resetPlaybackCadenceCorrection();
          return true;
        }
      } else {
        stableSamples = 0;
      }
      lastPosition = position;
      await Future<void>.delayed(const Duration(milliseconds: 300));
    }
    return false;
  }

  Duration _libVlcContinuousTsStartupProofBudget(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (engine == _NativePlaybackEngine.libvlc && _isHlsSource(source)) {
      return const Duration(seconds: 45);
    }
    if (engine == _NativePlaybackEngine.libvlc) {
      return const Duration(seconds: 10);
    }
    return const Duration(seconds: 5);
  }

  bool _requiresSustainedMedia3DirectHlsOpenProof(
    PlaybackSource source,
    _NativePlaybackEngine engine,
  ) {
    if (engine != _NativePlaybackEngine.exoplayer) return false;
    if (_isLiveTvMode || _isPublicIptvSource(source)) return false;
    return source.sourceClass == PlaybackSourceClass.direct &&
        _isHlsSource(source);
  }

  Future<bool> _waitForSustainedMedia3DirectHlsOpenProof(
      _NativePlaybackController controller, PlaybackSource source,
      {Duration resumePosition = Duration.zero}) async {
    final resumeAnchorProof = resumePosition >= const Duration(seconds: 30);
    final proofDeadline = resumeAnchorProof
        ? const Duration(seconds: 16)
        : const Duration(seconds: 40);
    final deadline = DateTime.now().add(proofDeadline);
    final proofStartedAt = DateTime.now();
    DateTime? firstReadyAt;
    var previousAt = DateTime.now();
    var previousPosition = controller.position;
    var stableSamples = 0;
    var bufferingSamples = 0;
    var missingVisualPlayingSamples = 0;
    var visualStartupSamples = 0;
    var toleratedResumeStartupDrifts = 0;
    var toleratedStartupAttachDrifts = 0;
    DateTime? noVisualStartedAt;
    if (resumeAnchorProof) {
      DiagnosticLog.add(
        'native media3 direct hls startup proof resume budget provider=${source.providerId} quality=${_qualityLabel(source)} anchor=${resumePosition.inSeconds}s timeout=${proofDeadline.inSeconds}s',
      );
    }
    while (mounted &&
        !_playerClosing &&
        _controller == controller &&
        DateTime.now().isBefore(deadline)) {
      final now = DateTime.now();
      final position = controller.position;
      if (!controller.isInitialized || controller.hasError) {
        return false;
      }
      final visuallyReady = controller.isPlaying &&
          controller.hasRenderedVideoFrame &&
          controller.duration > Duration.zero &&
          controller.size != Size.zero &&
          !_activeSourceHasZeroClockMetadata;
      if (visuallyReady) {
        missingVisualPlayingSamples = 0;
        firstReadyAt ??= now;
        visualStartupSamples += 1;
        final wallDeltaMs = now.difference(previousAt).inMilliseconds;
        final positionDeltaMs =
            position.inMilliseconds - previousPosition.inMilliseconds;
        if (wallDeltaMs >= 400 && positionDeltaMs > 0) {
          final speed = math.max(_playbackSpeed, 1.0);
          final allowedDeltaMs = (wallDeltaMs * speed * 1.80 + 1600).round();
          if (!controller.isBuffering && positionDeltaMs > allowedDeltaMs) {
            final ratio = positionDeltaMs / wallDeltaMs;
            final resumeSeekSettlingWindow = resumeAnchorProof &&
                now.difference(proofStartedAt) <= const Duration(seconds: 4) &&
                position >= resumePosition &&
                toleratedResumeStartupDrifts < 3;
            if (resumeSeekSettlingWindow) {
              toleratedResumeStartupDrifts += 1;
              DiagnosticLog.add(
                'native media3 direct hls startup proof tolerated resume seek settling provider=${source.providerId} observed=${position.inSeconds}s previous=${previousPosition.inSeconds}s ratio=${ratio.toStringAsFixed(2)} tolerated=$toleratedResumeStartupDrifts reason=resume_startup_seek_settling',
              );
            } else if (now.difference(proofStartedAt) <=
                    const Duration(seconds: 14) &&
                toleratedStartupAttachDrifts < 1) {
              toleratedStartupAttachDrifts += 1;
              stableSamples = 0;
              DiagnosticLog.add(
                'native media3 direct hls startup proof tolerated platform attach drift provider=${source.providerId} observed=${position.inSeconds}s previous=${previousPosition.inSeconds}s ratio=${ratio.toStringAsFixed(2)} tolerated=$toleratedStartupAttachDrifts action=observe_candidate reason=startup_platform_attach_settling',
              );
            } else if (!resumeAnchorProof &&
                now.difference(proofStartedAt) <= const Duration(seconds: 16) &&
                controller.hasRenderedVideoFrame &&
                controller.size != Size.zero &&
                visualStartupSamples >= 3) {
              stableSamples = 0;
              DiagnosticLog.add(
                'native media3 direct hls startup proof deferred early clock drift provider=${source.providerId} observed=${position.inSeconds}s previous=${previousPosition.inSeconds}s ratio=${ratio.toStringAsFixed(2)} visualSamples=$visualStartupSamples action=defer_to_runtime_cadence_guard reason=startup_visual_proof_clock_settling',
              );
            } else {
              DiagnosticLog.add(
                'native media3 direct hls startup proof rejected provider=${source.providerId} observed=${position.inSeconds}s previous=${previousPosition.inSeconds}s ratio=${ratio.toStringAsFixed(2)} action=reject_candidate reason=startup_clock_drift',
              );
              return false;
            }
          }
        }
        if (controller.isBuffering) {
          bufferingSamples += 1;
          stableSamples = 0;
        } else {
          stableSamples += 1;
        }
        final readyFor = now.difference(firstReadyAt);
        if (readyFor >= const Duration(seconds: 3) &&
            visualStartupSamples >= 6 &&
            controller.hasRenderedVideoFrame &&
            controller.duration > Duration.zero &&
            controller.size != Size.zero &&
            position >= const Duration(milliseconds: 500)) {
          DiagnosticLog.add(
            'native media3 direct hls startup visual proof observed provider=${source.providerId} quality=${_qualityLabel(source)} position=${position.inSeconds}s visualSamples=$visualStartupSamples buffering=$bufferingSamples readyFor=${readyFor.inSeconds}s action=${resumeAnchorProof ? 'defer_resume_seek_to_runtime_proof' : 'defer_clock_to_runtime_cadence_guard'}',
          );
          _lastKnownPlaybackPosition = position;
          _lastCadencePosition = position;
          _lastCadenceSampleAt = now;
          _resetPlaybackCadenceCorrection();
          return true;
        }
        if (readyFor >= const Duration(seconds: 10) && stableSamples >= 8) {
          DiagnosticLog.add(
            'native media3 direct hls startup proof observed provider=${source.providerId} quality=${_qualityLabel(source)} position=${position.inSeconds}s stable=$stableSamples buffering=$bufferingSamples readyFor=${readyFor.inSeconds}s',
          );
          _lastKnownPlaybackPosition = position;
          _lastCadencePosition = position;
          _lastCadenceSampleAt = now;
          _resetPlaybackCadenceCorrection();
          return true;
        }
      } else {
        stableSamples = 0;
        visualStartupSamples = 0;
        noVisualStartedAt ??= now;
        final noVisualFor = now.difference(noVisualStartedAt);
        final stalledWithoutVisual =
            position <= previousPosition + const Duration(milliseconds: 250);
        if (!resumeAnchorProof &&
            noVisualFor >= const Duration(seconds: 8) &&
            !controller.hasRenderedVideoFrame &&
            (controller.isBuffering ||
                !controller.isPlaying ||
                stalledWithoutVisual)) {
          DiagnosticLog.add(
            'native media3 direct hls startup proof rejected provider=${source.providerId} quality=${_qualityLabel(source)} position=${position.inSeconds}s buffering=${controller.isBuffering} playing=${controller.isPlaying} stalled=$stalledWithoutVisual elapsed=${noVisualFor.inSeconds}s action=reject_candidate reason=startup_no_visual_stalled_clock',
          );
          return false;
        }
        final noUsableProgress =
            position < const Duration(seconds: 1) || controller.isBuffering;
        if (!resumeAnchorProof &&
            noVisualFor >= const Duration(seconds: 12) &&
            !controller.hasRenderedVideoFrame &&
            noUsableProgress) {
          DiagnosticLog.add(
            'native media3 direct hls startup proof rejected provider=${source.providerId} quality=${_qualityLabel(source)} position=${position.inSeconds}s buffering=${controller.isBuffering} playing=${controller.isPlaying} elapsed=${noVisualFor.inSeconds}s action=reject_candidate reason=startup_no_visual_progress',
          );
          return false;
        }
        if (controller.isPlaying &&
            !controller.isBuffering &&
            controller.duration > Duration.zero &&
            position >= const Duration(seconds: 5) &&
            (!controller.hasRenderedVideoFrame ||
                controller.size == Size.zero)) {
          missingVisualPlayingSamples += 1;
          if (missingVisualPlayingSamples >= 8) {
            DiagnosticLog.add(
              'native media3 direct hls startup proof rejected provider=${source.providerId} quality=${_qualityLabel(source)} position=${position.inSeconds}s firstFrame=${controller.hasRenderedVideoFrame} size=${controller.size.width.toStringAsFixed(0)}x${controller.size.height.toStringAsFixed(0)} action=reject_candidate reason=startup_audio_without_visual',
            );
            return false;
          }
        } else {
          missingVisualPlayingSamples = 0;
        }
      }
      previousAt = now;
      previousPosition = position;
      await Future<void>.delayed(const Duration(milliseconds: 500));
    }
    return false;
  }

  Future<bool> _seekToResumePosition(
    Duration position,
    String providerId,
    _NativePlaybackController controller,
  ) async {
    var target = position;
    final duration = controller.duration;
    if (duration > const Duration(seconds: 20) &&
        target >= duration - const Duration(seconds: 20)) {
      target = duration - const Duration(seconds: 20);
    }
    if (target <= Duration.zero) return false;
    DiagnosticLog.add(
      'native seeking start provider=$providerId position=${target.inSeconds}s',
    );
    try {
      await _seekControllerToPlaybackPosition(
        controller,
        target,
        reason: 'resume_start',
        allowContinuousTsReopen: false,
      ).timeout(const Duration(seconds: 4));
      if (controller.engine == _NativePlaybackEngine.libvlc &&
          controller.duration <= Duration.zero) {
        _resumeProgressAnchorPosition = target;
        _resumeProgressAnchorLogSecond = -1;
      }
      DiagnosticLog.add(
        'native resume seek applied provider=$providerId position=${target.inSeconds}s',
      );
      _anchorNativeRecoveryProgress(target, reason: 'resume_seek_applied');
      if (controller.engine == _NativePlaybackEngine.exoplayer) {
        _media3ResumeSeekSettleAnchor = target;
        _media3ResumeSeekSettleUntil =
            DateTime.now().add(_resumeSeekRetryWindow);
        _media3ResumeSeekSettleDrifts = 0;
        _lastCadencePosition = target;
        _lastCadenceSampleAt = DateTime.now();
        DiagnosticLog.add(
          'native media3 resume seek settle armed provider=$providerId position=${target.inSeconds}s timeout=${_resumeSeekRetryWindow.inSeconds}s',
        );
      }
      return true;
    } catch (error) {
      DiagnosticLog.add(
        'native seek start ignored provider=$providerId error=${_safeDiagnosticError(error)}',
      );
      return false;
    }
  }

  void _toggleControlsFromSurfaceTap() {
    if (_resumeDialogOpen) return;
    final ready = _nativeControlsReady(_controller);
    if (!ready) {
      DiagnosticLog.add(
        'native hud surface tap ignored reason=controls_not_ready controlsVisible=$_controlsVisible loading=$_loading opening=$_openingSource wait=${_playbackWaitMessage != null}',
      );
      return;
    }
    _hideControlsTimer?.cancel();
    _lastControllerUiRebuildAt = null;
    if (_locked) {
      setState(() {
        _controlsVisible = true;
        _advanceHudRevealGeneration();
        _clearGestureHintState();
      });
      _scheduleControlsHide();
      return;
    }
    final nextVisible = !_controlsVisible;
    setState(() {
      _controlsVisible = nextVisible;
      if (nextVisible) {
        _advanceHudRevealGeneration();
      } else {
        _clearGestureHintState();
      }
    });
    DiagnosticLog.add(
      'native hud surface tap toggle applied controlsVisible=$_controlsVisible ready=$ready sources=${_activeSources.length}',
    );
    if (nextVisible) {
      _scheduleControlsHide();
    }
  }

  bool _handleForwardedNativeControlTap({
    required double x,
    required double y,
    required double width,
    required double height,
  }) {
    if (!_nativeControlsReady(_controller) ||
        _optionSheetOpen ||
        _settingsExpanded ||
        width <= 0 ||
        height <= 0) {
      return false;
    }
    final nx = (x / width).clamp(0.0, 1.0);
    final ny = (y / height).clamp(0.0, 1.0);
    final inBottomControlBand = ny >= 0.72 && ny <= 0.94;
    if (!inBottomControlBand) return false;
    final controlsWereVisible = _controlsVisible;
    if (!controlsWereVisible) {
      _hideControlsTimer?.cancel();
      _lastControllerUiRebuildAt = null;
      setState(() {
        _controlsVisible = true;
        _advanceHudRevealGeneration();
        _clearGestureHintState();
      });
    }
    if (_activeSources.length > 1 && nx >= 0.56 && nx <= 0.80) {
      DiagnosticLog.add(
        'native media3 forwarded tap routed action=sources controlsVisible=$controlsWereVisible nx=${nx.toStringAsFixed(2)} ny=${ny.toStringAsFixed(2)} sources=${_activeSources.length}',
      );
      unawaited(_showSourceSheet());
      return true;
    }
    if (nx > 0.80 && nx <= 0.91) {
      DiagnosticLog.add(
        'native media3 forwarded tap routed action=settings controlsVisible=$controlsWereVisible nx=${nx.toStringAsFixed(2)} ny=${ny.toStringAsFixed(2)}',
      );
      _toggleSettingsPack();
      return true;
    }
    if (!controlsWereVisible) _scheduleControlsHide();
    return false;
  }

  void _handlePlayerSurfaceTap() {
    DiagnosticLog.add(
      'native hud surface tap received controlsVisible=$_controlsVisible ready=${_nativeControlsReady(_controller)} sources=${_activeSources.length} settings=$_settingsExpanded sheet=$_optionSheetOpen',
    );
    _toggleControlsFromSurfaceTap();
  }

  Future<void> _handleMedia3PlayerChannelCall(MethodCall call) async {
    if (call.method != 'surfaceTap') return;
    final args = call.arguments as Map<Object?, Object?>?;
    final viewId = (args?['viewId'] as num?)?.toInt();
    final media3 = _controller?.media3;
    if (media3 == null || viewId == null || media3.attachedViewId != viewId) {
      DiagnosticLog.add(
        'native media3 surface tap ignored reason=stale_view viewId=$viewId active=${media3?.attachedViewId}',
      );
      return;
    }
    DiagnosticLog.add(
      'native media3 surface tap forwarded viewId=$viewId controlsVisible=$_controlsVisible ready=${_nativeControlsReady(_controller)}',
    );
    final x = (args?['x'] as num?)?.toDouble();
    final y = (args?['y'] as num?)?.toDouble();
    final width = (args?['width'] as num?)?.toDouble();
    final height = (args?['height'] as num?)?.toDouble();
    if (x != null &&
        y != null &&
        width != null &&
        height != null &&
        _handleForwardedNativeControlTap(
          x: x,
          y: y,
          width: width,
          height: height,
        )) {
      return;
    }
    _handlePlayerSurfaceTap();
  }

  bool _resumeStartupSeekProofPending(_NativePlaybackController controller) {
    if (_resumeProgressAnchorPosition < const Duration(seconds: 3)) {
      return false;
    }
    if (!controller.isInitialized || controller.hasError) return false;
    return controller.position <
        _resumeProgressAnchorPosition - const Duration(seconds: 10);
  }

  bool _shouldDelayMedia3ResumeSeekUntilVisualProof(
    PlaybackSource source,
    _NativePlaybackEngine engine,
    Duration position,
  ) {
    if (engine != _NativePlaybackEngine.exoplayer) return false;
    if (position < const Duration(seconds: 30)) return false;
    if (_isLiveTvMode || widget.liveMode || _isPublicIptvSource(source)) {
      return false;
    }
    return source.sourceClass == PlaybackSourceClass.p2p ||
        (source.sourceClass == PlaybackSourceClass.direct &&
            _isHlsSource(source));
  }

  bool _shouldWaitForMedia3ResumeSeekVisualProof(
    _NativePlaybackController controller,
    Duration position,
  ) {
    final source = _activeSource;
    if (source == null || controller.hasRenderedVideoFrame) return false;
    return _shouldDelayMedia3ResumeSeekUntilVisualProof(
      source,
      controller.engine,
      position,
    );
  }

  bool _shouldRejectUnprovedMedia3ResumeStartup(
    PlaybackSource source,
    _NativePlaybackController controller,
    Duration resumePosition,
  ) {
    if (controller.engine != _NativePlaybackEngine.exoplayer) return false;
    if (resumePosition < const Duration(seconds: 5)) return false;
    if (_isLiveTvMode || widget.liveMode || _isPublicIptvSource(source)) {
      return false;
    }
    if (source.sourceClass != PlaybackSourceClass.direct) {
      return false;
    }
    final missingVisualProof = !controller.hasRenderedVideoFrame ||
        controller.size == Size.zero ||
        controller.duration <= Duration.zero;
    final earlyRuntimeRecovery = resumePosition < const Duration(seconds: 30) &&
        _hasRecentRuntimeFailureForSource(source);
    if (earlyRuntimeRecovery && missingVisualProof) return true;
    if (resumePosition < const Duration(seconds: 30)) return false;
    if (missingVisualProof) return true;
    final farBelowAnchor =
        controller.position < resumePosition - const Duration(seconds: 10);
    if (farBelowAnchor) return true;
    final nearResumeAnchor =
        controller.position >= resumePosition - const Duration(seconds: 10);
    if (nearResumeAnchor && (controller.isPlaying || controller.isBuffering)) {
      return false;
    }
    if (!controller.isPlaying && !controller.isBuffering) return true;
    if (!controller.hasRenderedVideoFrame && !controller.isBuffering) {
      return true;
    }
    return false;
  }

  bool _hasRecentRuntimeFailureForSource(PlaybackSource source) {
    final failedAt = _lastRuntimeSourceFailureAt;
    if (failedAt == null) return false;
    if (DateTime.now().difference(failedAt) > const Duration(seconds: 45)) {
      return false;
    }
    final failedProvider = _lastRuntimeSourceFailureProviderId;
    if (failedProvider == null || failedProvider.isEmpty) return true;
    return failedProvider == source.providerId;
  }

  Future<bool?> _confirmResumePlayback(Duration saved) async {
    if (!mounted) return Future<bool?>.value(true);
    final minutes = saved.inMinutes;
    final label = minutes <= 0 ? 'less than 1 minute' : '$minutes min';
    var dialogClosing = false;
    void closeResumeDialog(BuildContext dialogContext, bool resume) {
      if (dialogClosing) return;
      dialogClosing = true;
      if (!dialogContext.mounted) return;
      Navigator.of(dialogContext).pop(resume);
    }

    _hideControlsTimer?.cancel();
    setState(() {
      _resumeDialogOpen = true;
      _resumeDialogAcceptedAwaitingProof = false;
      _controlsVisible = false;
      _settingsExpanded = false;
      _optionSheetOpen = false;
    });
    final confirmed = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (context) => AlertDialog(
        title: const Text('Resume playback?'),
        content: Text('Continue from $label, or start from the beginning?'),
        actions: [
          TextButton(
            onPressed: () => closeResumeDialog(context, false),
            child: const Text('Start over'),
          ),
          FilledButton(
            onPressed: () => closeResumeDialog(context, true),
            child: const Text('Resume'),
          ),
        ],
      ),
    );
    if (confirmed == null) {
      DiagnosticLog.add(
        'native resume prompt dismissed action=start_over reason=back_or_system_dismiss',
      );
    }
    if (!mounted) return confirmed;
    final controller = _controller;
    final waitForLibVlcProof = confirmed == true &&
        controller?.engine == _NativePlaybackEngine.libvlc &&
        !_hasLibVlcVisualPlaybackProof(controller!);
    setState(() {
      _resumeDialogOpen = false;
      _resumeDialogAcceptedAwaitingProof = waitForLibVlcProof;
      _controlsVisible = confirmed == true && !waitForLibVlcProof;
      _playbackWaitMessage = waitForLibVlcProof ? 'Resuming playback...' : null;
      _playbackWaitMessagePausedPlayback = false;
    });
    if (confirmed == true && !waitForLibVlcProof) {
      _scheduleControlsHide();
    }
    return confirmed;
  }

  bool _shouldLogProgressSaveSkip(
    String reason, {
    required bool force,
  }) {
    final now = DateTime.now();
    final lastAt = _lastProgressSaveSkipLogAt;
    if (_lastProgressSaveSkipLogReason == reason &&
        lastAt != null &&
        now.difference(lastAt) < const Duration(seconds: 1)) {
      return false;
    }
    _lastProgressSaveSkipLogReason = reason;
    _lastProgressSaveSkipLogAt = now;
    return true;
  }

  void _saveNativeProgress({
    bool force = false,
    bool completionObserved = false,
  }) {
    final item = _progressItem;
    final key = _playbackKey;
    final controller = _controller;
    if (item == null || key == null) {
      if (force) {
        DiagnosticLog.add(
          'native progress save skipped reason=missing_progress_target itemPresent=${item != null} playbackKeyPresent=${key != null}',
        );
      }
      return;
    }
    final coordinatorGeneration = _mobileLibVlcCoordinator?.generation ?? -1;
    if (_mobileLibVlcSeekPreparing &&
        _mobileLibVlcSeekOwnerGeneration == coordinatorGeneration) {
      if (force) {
        _saveNativePreferencesOnly(reason: 'seek_candidate_unproved');
      }
      DiagnosticLog.add(
        'native progress save deferred reason=seek_candidate_unproved '
        'surfaceGeneration=$coordinatorGeneration force=$force',
      );
      return;
    }

    final hasInitializedController =
        controller != null && controller.isInitialized;
    final hasHealthyController =
        hasInitializedController && !controller.hasError;
    final duration = _bestKnownProgressDuration(controller);
    final rawPosition = _bestKnownProgressPosition(controller, duration);
    if (_manualLibVlcSelectionProofPending) {
      if (force) {
        _saveNativePreferencesOnly(
          reason: 'libvlc_candidate_switch_unproved',
        );
      }
      DiagnosticLog.add(
        'native progress save skipped '
        'reason=libvlc_candidate_switch_unproved '
        'anchor=${_manualLibVlcSelectionProgressAnchor.inSeconds}s '
        'force=$force completionObserved=$completionObserved',
      );
      return;
    }
    if (_manualLibVlcSelectionRetainedClockRecoveryPending) {
      final anchor = _manualLibVlcSelectionProgressAnchor;
      final lowerBound = anchor - const Duration(seconds: 3);
      final upperBound = anchor + const Duration(seconds: 45);
      final retainedClockRecovered = hasHealthyController &&
          controller.isPlaying &&
          !controller.isBuffering &&
          rawPosition >= lowerBound &&
          rawPosition <= upperBound;
      if (!retainedClockRecovered) {
        if (force) {
          _saveNativePreferencesOnly(
            reason: 'libvlc_retained_session_clock_unproved',
          );
        }
        if (_shouldLogProgressSaveSkip(
          'libvlc_retained_session_clock_unproved',
          force: force,
        )) {
          DiagnosticLog.add(
            'native progress save skipped '
            'reason=libvlc_retained_session_clock_unproved '
            'raw=${rawPosition.inSeconds}s anchor=${anchor.inSeconds}s '
            'playing=${controller?.isPlaying == true} '
            'buffering=${controller?.isBuffering == true} force=$force',
          );
        }
        return;
      }
      _manualLibVlcSelectionRetainedClockRecoveryPending = false;
      _manualLibVlcSelectionProgressAnchor = Duration.zero;
      _rememberCrediblePlaybackAnchor(
        rawPosition,
        reason: 'libvlc_retained_session_clock_recovered',
      );
      DiagnosticLog.add(
        'native libvlc retained session clock recovered '
        'reason=libvlc_retained_session_clock_recovered '
        'position=${rawPosition.inSeconds}s anchor=${anchor.inSeconds}s',
      );
    }
    final stablePosition = _stableProgressClockPosition(
      rawPosition,
      reason: force ? 'forced_progress_save' : 'progress_save',
    );
    final resumeSeekStillPending = controller != null &&
        _resumeProgressAnchorPosition >= const Duration(seconds: 5) &&
        rawPosition <
            _resumeProgressAnchorPosition - const Duration(seconds: 10) &&
        !completionObserved;
    if (resumeSeekStillPending) {
      if (force) {
        _saveNativePreferencesOnly(
            reason: 'resume_seek_pending_progress_guard');
      }
      DiagnosticLog.add(
        'native progress save skipped reason=resume_seek_pending_progress_guard raw=${rawPosition.inSeconds}s anchor=${_resumeProgressAnchorPosition.inSeconds}s force=$force',
      );
      return;
    }
    final position = _rendererRecoveryProgressSavePosition(
      rawPosition: rawPosition,
      stablePosition: stablePosition,
      force: force,
      completionObserved: completionObserved,
    );
    final controllerDurationForSanity = controller?.duration ?? Duration.zero;
    if (_durationLooksLikeShortVodPlaceholder(controllerDurationForSanity)) {
      if (force) {
        _saveNativePreferencesOnly(reason: 'short_vod_placeholder_clock');
      }
      DiagnosticLog.add(
        'native progress save skipped reason=short_vod_placeholder_clock duration=${controllerDurationForSanity.inSeconds}s expected=${_expectedVodDurationForSanity().inSeconds}s position=${position.inSeconds}s completionObserved=$completionObserved routeLive=$_isLiveTvMode',
      );
      return;
    }
    final anchoredRendererRecoveryProgress = position != stablePosition &&
        rawPosition - position > const Duration(seconds: 2);
    final heldSuspiciousClock =
        rawPosition - position > const Duration(seconds: 2);
    final tailCompletion = completionObserved &&
        controller != null &&
        _shouldCompletePlaybackAtTail(
          controller,
          positionOverride: rawPosition,
        );
    final recoveryAnchor = _resumeProgressAnchorPosition;
    final media3RecoveryClockUntrusted = _recoveringFromMedia3RendererDrift &&
        recoveryAnchor >= const Duration(seconds: 3) &&
        rawPosition - recoveryAnchor > const Duration(seconds: 2);
    if (media3RecoveryClockUntrusted) {
      if (_shouldLogProgressSaveSkip(
        'media3_recovery_clock_untrusted',
        force: force,
      )) {
        DiagnosticLog.add(
          'native progress save skipped reason=media3_recovery_clock_untrusted raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s anchor=${recoveryAnchor.inSeconds}s force=$force',
        );
      }
      return;
    }
    if (_media3RendererClockIsUnproven(controller)) {
      if (_shouldLogProgressSaveSkip(
        'media3_renderer_unproven_clock',
        force: force,
      )) {
        DiagnosticLog.add(
          'native progress save skipped reason=media3_renderer_unproven_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s force=$force',
        );
      }
      return;
    }
    final resumeAnchorBufferingClockUntrusted = controller != null &&
        controller.isBuffering &&
        !completionObserved &&
        _resumeProgressAnchorPosition >= const Duration(seconds: 30) &&
        rawPosition >= _resumeProgressAnchorPosition &&
        rawPosition - _resumeProgressAnchorPosition <=
            const Duration(seconds: 45);
    if (resumeAnchorBufferingClockUntrusted) {
      if (force) {
        _saveNativePreferencesOnly(
          reason: 'resume_anchor_buffering_clock',
        );
      }
      if (_shouldLogProgressSaveSkip(
        'resume_anchor_buffering_clock',
        force: force,
      )) {
        DiagnosticLog.add(
          'native progress save skipped reason=resume_anchor_buffering_clock raw=${rawPosition.inSeconds}s anchor=${_resumeProgressAnchorPosition.inSeconds}s force=$force',
        );
      }
      return;
    }
    if (_media3DirectHlsExtendedProgressProofIsPending(controller) &&
        !completionObserved) {
      final suspiciousRawClock = _isSuspiciousProgressClockJump(
        rawPosition,
        reason: 'media3_direct_hls_extended_progress_proof',
        log: true,
      );
      if (_playbackCadenceClockUnstable ||
          suspiciousRawClock ||
          (!force && rawPosition - position > const Duration(seconds: 2))) {
        if (force) {
          _saveNativePreferencesOnly(
            reason: 'media3_direct_hls_extended_progress_proof',
          );
        }
        DiagnosticLog.add(
          'native progress save skipped reason=media3_direct_hls_extended_progress_proof raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s force=$force unstable=$_playbackCadenceClockUnstable suspicious=$suspiciousRawClock',
        );
        return;
      }
    }
    if (_playbackCadenceClockUnstable &&
        completionObserved &&
        !tailCompletion) {
      DiagnosticLog.add(
        'native completion downgraded reason=unstable_playback_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s',
      );
      completionObserved = false;
    }
    if (heldSuspiciousClock && completionObserved && !tailCompletion) {
      DiagnosticLog.add(
        'native completion downgraded reason=suspicious_player_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s',
      );
      completionObserved = false;
    }
    if (_playbackCadenceClockUnstable &&
        !completionObserved &&
        !anchoredRendererRecoveryProgress) {
      DiagnosticLog.add(
        'native progress save skipped reason=unstable_playback_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s force=$force',
      );
      return;
    }
    if (heldSuspiciousClock &&
        (!force || !completionObserved) &&
        !anchoredRendererRecoveryProgress) {
      DiagnosticLog.add(
        'native progress save skipped reason=suspicious_player_clock raw=${rawPosition.inSeconds}s stable=${position.inSeconds}s',
      );
      return;
    }
    final nativeClockUnavailable = hasInitializedController &&
        controller.duration <= Duration.zero &&
        (controller.engine == _NativePlaybackEngine.libvlc ||
            controller.engine == _NativePlaybackEngine.exoplayer);
    final supportsFallbackClock = nativeClockUnavailable &&
        (controller.engine == _NativePlaybackEngine.libvlc ||
            controller.engine == _NativePlaybackEngine.exoplayer);
    if (supportsFallbackClock &&
        _resumeProgressAnchorPosition > Duration.zero) {
      if (force &&
          position.inSeconds < _resumeProgressAnchorPosition.inSeconds) {
        DiagnosticLog.add(
          'native progress save skipped reason=fallback_clock_waiting_resume_anchor engine=${controller.engine.id} anchor=${_resumeProgressAnchorPosition.inSeconds}s position=${position.inSeconds}s',
        );
      }
      if (position.inSeconds < _resumeProgressAnchorPosition.inSeconds) return;
    }
    if (supportsFallbackClock && position.inSeconds < 1) {
      if (!controller.isPlaying) {
        if (force) {
          DiagnosticLog.add(
            'native progress save skipped reason=fallback_clock_not_playing engine=${controller.engine.id}',
          );
        }
        return;
      }
      if (_loading || _playbackWaitMessage != null) {
        if (force) {
          DiagnosticLog.add(
            'native progress save skipped reason=fallback_clock_waiting engine=${controller.engine.id} loading=$_loading waitMessage=${_playbackWaitMessage != null}',
          );
        }
        return;
      }
      if (!_progressFallbackClockEnabled) {
        if (force) {
          DiagnosticLog.add(
            'native progress save skipped reason=fallback_clock_disabled engine=${controller.engine.id}',
          );
        }
        return;
      }
      final startedAt = _nativeWallClockStartedAt;
      if (startedAt == null) {
        if (force) {
          DiagnosticLog.add(
            'native progress save skipped reason=missing_wall_clock engine=${controller.engine.id}',
          );
        }
        return;
      }
      final wallClockSeconds = DateTime.now().difference(startedAt).inSeconds;
      final watchedSeconds = wallClockSeconds;
      if (watchedSeconds < 1 && !force) return;
      final deltaSeconds = _lastSavedSecond < 0
          ? watchedSeconds
          : watchedSeconds - _lastSavedSecond;
      if (deltaSeconds <= 0) {
        if (force) {
          DiagnosticLog.add(
            'native progress save skipped reason=no_fallback_delta engine=${controller.engine.id} watched=${watchedSeconds}s last=$_lastSavedSecond',
          );
        }
        return;
      }
      if (!force && deltaSeconds < _nativeProgressSaveIntervalSeconds) return;
      _lastSavedSecond = watchedSeconds;
      final nativePreferences = _currentNativePreferences();
      DiagnosticLog.add(
        'native progress saved with fallback clock engine=${controller.engine.id} watched=${watchedSeconds}s wall=${wallClockSeconds}s delta=${deltaSeconds}s',
      );
      _markRuntimeSourceRecovered(
        engine: controller.engine,
        position: Duration(seconds: watchedSeconds),
        reason: 'fallback_progress_save',
      );
      AppState.recordPlaybackProgress(
        item: item,
        playbackKey: key,
        title: _title,
        subtitle: _progressSubtitle,
        durationSeconds: duration.inSeconds > 0
            ? duration.inSeconds
            : _fallbackProgressDurationSeconds(),
        watchedSeconds: deltaSeconds,
        completionObserved: completionObserved,
        trustedCompletionObserved: false,
        generation: _progressGeneration,
        nativePreferences: nativePreferences,
      );
      _rememberVerifiedSource(controller, Duration(seconds: watchedSeconds));
      return;
    }
    if (duration.inSeconds <= 0 || position.inSeconds < 1) {
      if (force) {
        _saveNativePreferencesOnly(reason: 'progress_clock_unavailable');
        DiagnosticLog.add(
          'native progress save skipped reason=invalid_clock duration=${duration.inSeconds}s position=${position.inSeconds}s initialized=$hasInitializedController healthyController=$hasHealthyController routeLive=$_isLiveTvMode',
        );
      }
      return;
    }
    _creditPlaybackIntegrityPosition(position, reason: 'progress_save');
    if (!force &&
        (position.inSeconds - _lastSavedSecond).abs() <
            _nativeProgressSaveIntervalSeconds) {
      return;
    }
    _lastSavedSecond = position.inSeconds;
    final nativePreferences = _currentNativePreferences();
    final endedCompletion = completionObserved && controller?.isEnded == true;
    final trustedCompletionObserved = completionObserved;
    final credibleCompletionObserved = completionObserved &&
        (trustedCompletionObserved ||
            _hasCredibleCompletionForNativeEnd(
              durationSeconds: duration.inSeconds,
              positionSeconds: position.inSeconds,
              ended: endedCompletion,
            ));
    final effectivePosition =
        completionObserved && credibleCompletionObserved ? duration : position;
    var savedPosition = _resumeSafeProgressPosition(
      effectivePosition,
      duration,
      completionObserved: credibleCompletionObserved,
    );
    savedPosition = preserveMobileLibVlcAnchor(
      current: _resumeProgressAnchorPosition,
      candidate: savedPosition,
      explicitSeek: false,
    );
    final usesContinuousTsAbsoluteTimeline =
        controller?.engine == _NativePlaybackEngine.libvlc &&
            _libVlcContinuousTsActive;
    var absoluteProgressFloor = Duration.zero;
    if (usesContinuousTsAbsoluteTimeline) {
      final coordinatorGeneration = _mobileLibVlcCoordinator?.generation ?? -1;
      final seekOwnsGeneration =
          _mobileLibVlcSeekOwnerGeneration == coordinatorGeneration;
      if (seekOwnsGeneration) {
        absoluteProgressFloor = _mobileLibVlcSeekAbsoluteFloor;
      }
      final activeTimelinePosition =
          _activeMobileLibVlcSessionTimeline?.absolutePlaybackPosition ??
              Duration.zero;
      if ((!_mobileLibVlcSeekPreparing || !seekOwnsGeneration) &&
          activeTimelinePosition > absoluteProgressFloor) {
        absoluteProgressFloor = activeTimelinePosition;
      }
    }
    savedPosition = preserveMobileLibVlcAbsoluteProgressFloor(
      proposedPosition: savedPosition,
      authoritativeAnchor: absoluteProgressFloor,
      relayLocalDuration: controller?.duration ?? Duration.zero,
      continuousTsAbsoluteTimeline: usesContinuousTsAbsoluteTimeline,
    );
    if (completionObserved) {
      DiagnosticLog.add(
        'native completion trust observed trustedCompletion=$trustedCompletionObserved credibleCompletion=$credibleCompletionObserved credibleWatched=${_credibleWatchSeconds}s position=${position.inSeconds}s duration=${duration.inSeconds}s',
      );
    }
    if (savedPosition != effectivePosition) {
      DiagnosticLog.add(
        'native progress near-end capped for resume position=${effectivePosition.inSeconds}s saved=${savedPosition.inSeconds}s duration=${duration.inSeconds}s reason=incomplete_near_end completionObserved=$completionObserved trustedCompletion=$trustedCompletionObserved credibleCompletion=$credibleCompletionObserved credibleWatched=${_credibleWatchSeconds}s',
      );
    }
    DiagnosticLog.add(
      'native progress saved with player clock engine=${controller?.engine.id ?? 'cached'} watched=${savedPosition.inSeconds}s duration=${duration.inSeconds}s force=$force',
    );
    if (controller != null) {
      _markRuntimeSourceRecovered(
        engine: controller.engine,
        position: savedPosition,
        reason: 'player_progress_save',
      );
    }
    if (controller != null) {
      _rememberVerifiedSource(controller, savedPosition);
    }

    AppState.setPlaybackProgress(
      item: item,
      playbackKey: key,
      title: _title,
      subtitle: _progressSubtitle,
      durationSeconds: duration.inSeconds,
      watchedSeconds: savedPosition.inSeconds,
      credibleWatchedSeconds: _credibleWatchSeconds,
      completionObserved: completionObserved,
      trustedCompletionObserved: trustedCompletionObserved,
      generation: _progressGeneration,
      nativePreferences: nativePreferences,
    );
  }

  bool _hasCredibleCompletionForNativeEnd({
    required int durationSeconds,
    required int positionSeconds,
    required bool ended,
  }) {
    if (AppState.hasCredibleCompletionEvidence(
      durationSeconds: durationSeconds,
      credibleWatchedSeconds: _credibleWatchSeconds,
    )) {
      return true;
    }
    if (!ended || durationSeconds <= 0) return false;
    final nearEnd = positionSeconds / durationSeconds >= 0.95;
    if (!nearEnd) return false;
    return _credibleWatchSeconds >= 60;
  }

  Duration _resumeSafeProgressPosition(
    Duration position,
    Duration duration, {
    required bool completionObserved,
  }) {
    if (completionObserved ||
        duration <= Duration.zero ||
        position < const Duration(seconds: 3)) {
      return position;
    }
    final progress = position.inMilliseconds / duration.inMilliseconds;
    if (progress < 0.95) return position;

    final percentCapMs = (duration.inMilliseconds * 0.92).round();
    final tailCapMs =
        duration.inMilliseconds - const Duration(minutes: 3).inMilliseconds;
    final preferredCapMs =
        tailCapMs > 0 ? math.min(percentCapMs, tailCapMs) : percentCapMs;
    final capMs = math.max(
      const Duration(seconds: 3).inMilliseconds,
      preferredCapMs,
    );
    if (position.inMilliseconds <= capMs) return position;
    return Duration(milliseconds: capMs);
  }

  NativePlayerPreferences _currentNativePreferences() {
    return NativePlayerPreferences(
      quality: _preferredQuality ?? 'Auto',
      speed: _playbackSpeed,
      subtitleId: _activeSubtitle?.id,
      subtitleDelaySeconds: _subtitleDelaySeconds,
      subtitleDelayCustomized: _subtitleDelayCustomized,
      subtitleFontSize: _subtitleFontSize,
      subtitleBackgroundOpacity: _subtitleBackgroundOpacity,
      subtitleBackgroundColor: _subtitleBackgroundColor.value,
      subtitleBackgroundRadius: _subtitleBackgroundRadius,
      subtitleTextColor: _subtitleTextColor.value,
      subtitleBottomOffset: _subtitleBottomOffset,
      videoFitMode: _fitMode.name,
    );
  }

  void _saveNativePreferencesOnly({required String reason}) {
    final item = _progressItem;
    final key = _playbackKey;
    if (item == null || key == null) {
      DiagnosticLog.add(
        'native preferences save skipped reason=missing_progress_target trigger=$reason itemPresent=${item != null} playbackKeyPresent=${key != null}',
      );
      return;
    }
    AppState.updateNativePlayerPreferences(
      item: item,
      playbackKey: key,
      title: _title,
      subtitle: _progressSubtitle,
      generation: _progressGeneration,
      nativePreferences: _currentNativePreferences(),
    );
    DiagnosticLog.add('native preferences saved reason=$reason key=[redacted]');
  }

  void _scheduleControlsHide() {
    _hideControlsTimer?.cancel();
    if (!_controlsVisible ||
        _resumeDialogOpen ||
        _pictureInPictureActive ||
        !_nativeControlsReady(_controller) ||
        _settingsExpanded) {
      return;
    }
    final timeout =
        AppState.playerBehaviorSettings.value.controlsTimeoutSeconds;
    _hideControlsTimer = Timer(Duration(seconds: timeout), () {
      if (!mounted) return;
      setState(() {
        _controlsVisible = false;
        _settingsExpanded = false;
        _clearGestureHintState();
      });
    });
  }

  void _ensureControlsAutoHide({required String reason}) {
    if (!_controlsVisible || _hideControlsTimer?.isActive == true) return;
    if (_settingsExpanded ||
        _optionSheetOpen ||
        _resumeDialogOpen ||
        _loading ||
        _playbackWaitMessage != null) {
      return;
    }
    final controller = _controller;
    if (controller == null ||
        !controller.isInitialized ||
        !controller.isPlaying ||
        !_nativeControlsReady(controller)) {
      return;
    }
    DiagnosticLog.add(
      'native controls auto-hide scheduled reason=$reason engine=${controller.engine.id}',
    );
    _scheduleControlsHide();
  }

  int get _nativeProgressSaveIntervalSeconds {
    final source = _activeSource;
    if (source?.sourceClass == PlaybackSourceClass.p2p) return 15;
    return 5;
  }

  bool _nativeControlsReady(
    _NativePlaybackController? controller, {
    bool allowSeekPreparation = false,
  }) {
    if (controller == null ||
        !controller.isInitialized ||
        controller.hasError ||
        (_loading && !allowSeekPreparation) ||
        _openingSource ||
        _recoveringFromStall ||
        _resolverTemporarilyBlocked ||
        _playbackWaitMessage != null ||
        _activeSource == null) {
      return false;
    }
    if (controller.engine == _NativePlaybackEngine.libvlc) {
      return true;
    }
    if (_activeSourceHasZeroClockMetadata) {
      return false;
    }
    final hasUsableClock = controller.duration > Duration.zero;
    final hasVideoSurface = controller.size != Size.zero;
    return hasUsableClock && hasVideoSurface;
  }

  void _emitHudMountSignal(NativeHudMountSignalEvent? event) {
    if (event != null) DiagnosticLog.add(event.diagnostic);
  }

  void _advanceHudRevealGeneration() {
    _hudRevealGeneration += 1;
    _hudTransportMountOwner =
        NativeHudTransportMountOwner(_hudRevealGeneration);
  }

  void _handleHudTransportAnimationCompleted(
    NativeHudTransportMountOwner owner,
    NativeHudTransportSlot slot,
  ) {
    if (!mounted ||
        _playerClosing ||
        !identical(owner, _hudTransportMountOwner) ||
        owner.generation != _hudRevealGeneration) {
      return;
    }
    owner.markAnimationCompleted(slot);
    if (!owner.animationCompleted) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted ||
          _playerClosing ||
          !identical(owner, _hudTransportMountOwner) ||
          owner.generation != _hudRevealGeneration) {
        return;
      }
      final visible = _controlsVisible &&
          !_loading &&
          !_openingSource &&
          !_recoveringFromStall &&
          _playbackWaitMessage == null;
      _emitHudMountSignal(
        _hudMountSignalGate.completePostFrame(
          generation: owner.generation,
          visible: visible,
          animationCompleted: owner.animationCompleted,
          leftSkipMounted: nativeHudTransportRenderObjectReady(
            activePlayerBoundsKey: owner.activePlayerBoundsKey,
            controlKey: owner.leftSkipKey,
          ),
          centerControlMounted: nativeHudTransportRenderObjectReady(
            activePlayerBoundsKey: owner.activePlayerBoundsKey,
            controlKey: owner.centerPlayPauseKey,
          ),
          rightSkipMounted: nativeHudTransportRenderObjectReady(
            activePlayerBoundsKey: owner.activePlayerBoundsKey,
            controlKey: owner.rightSkipKey,
          ),
          playerVerified: _nativeControlsReady(_controller),
          loading: _loading,
        ),
      );
    });
  }

  void _scheduleHudMountSignalAfterFrame({
    required bool playerVerified,
    required bool controlsIncluded,
  }) {
    final generation = _hudRevealGeneration;
    final visible = _controlsVisible && controlsIncluded && playerVerified;
    final owner = _hudTransportMountOwner;
    if (!visible) {
      owner.resetAnimationCompletion();
      _emitHudMountSignal(_hudMountSignalGate.hide(generation));
      return;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted ||
          _playerClosing ||
          generation != _hudRevealGeneration ||
          !identical(owner, _hudTransportMountOwner)) {
        return;
      }
      if (!_controlsVisible) {
        owner.resetAnimationCompletion();
        _emitHudMountSignal(_hudMountSignalGate.hide(generation));
        return;
      }
      _emitHudMountSignal(
        _hudMountSignalGate.beginVisibleGeneration(generation),
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;
    final stagedControllers = _stagedMobileLibVlcControllers.entries
        .where(
          (entry) =>
              entry.key == _mobileLibVlcCoordinator?.generation &&
              !identical(entry.value, controller),
        )
        .map((entry) => entry.value)
        .toList(growable: false);
    final mountedLibVlcControllers = <_NativePlaybackController>[
      if (controller != null &&
          controller.engine == _NativePlaybackEngine.libvlc &&
          !stagedControllers.contains(controller))
        controller,
      ...stagedControllers,
    ];
    final visibleLibVlcController =
        _mobileLibVlcSeekPreparing && stagedControllers.isNotEmpty
            ? stagedControllers.last
            : controller;
    final initialized = controller?.isInitialized == true;
    final nativeControlsReady = _nativeControlsReady(
      controller,
      allowSeekPreparation: _mobileLibVlcSeekPreparing,
    );
    final controlsSuppressed = _resumeDialogOpen;
    final controlsDimmed = !controlsSuppressed &&
        (_settingsExpanded || (_optionSheetOpen && !_loading));
    final hudTransportMountOwner = _hudTransportMountOwner;
    return PopScope(
      canPop: _allowPop,
      onPopInvokedWithResult: (didPop, __) {
        if (didPop) {
          _exitPlayerMode();
          return;
        }
        if (_resumeDialogOpen) {
          DiagnosticLog.add(
            'native resume prompt back intercepted action=start_over',
          );
          final navigator = Navigator.of(context, rootNavigator: true);
          if (navigator.canPop()) {
            navigator.pop(false);
          }
          return;
        }
        unawaited(
          _nativeProvidersExhausted || controller == null
              ? _close('closed')
              : _requestClose(),
        );
      },
      child: Scaffold(
        backgroundColor: Colors.black,
        body: LayoutBuilder(
          builder: (context, constraints) {
            final compactPlayer = _pictureInPictureActive ||
                constraints.maxWidth <= 360 ||
                constraints.maxHeight <= 240;
            final fallbackDuration = _fallbackControlDuration();
            final fallbackPosition = _bestKnownProgressPosition(
              controller,
              fallbackDuration,
            );
            final playbackStarted = _playbackHasStartedForGestureHint(
              position: fallbackPosition,
            );
            _scheduleGestureHintIfNeeded(
              nativeControlsReady: nativeControlsReady,
              playbackStarted: playbackStarted,
              hudVisible: _controlsVisible,
              compactPlayer: compactPlayer,
            );
            final skipSegment = _activeSkipSegment(
              fallbackPosition,
              fallbackDuration,
            );
            final seekControlsReady = !_loading || _mobileLibVlcSeekPreparing;
            final controlsIncluded = seekControlsReady &&
                _playbackWaitMessage == null &&
                !controlsSuppressed &&
                nativeControlsReady &&
                !_pictureInPictureActive;
            _scheduleHudMountSignalAfterFrame(
              playerVerified: nativeControlsReady,
              controlsIncluded: controlsIncluded,
            );
            final surfaceInteractionEnabled = !_loading &&
                !controlsSuppressed &&
                nativeControlsReady &&
                !_pictureInPictureActive &&
                !_settingsExpanded &&
                !_optionSheetOpen;
            final surfaceGesturesEnabled =
                surfaceInteractionEnabled && !compactPlayer && !_locked;
            return GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: surfaceInteractionEnabled ? _handlePlayerSurfaceTap : null,
              onVerticalDragUpdate: surfaceGesturesEnabled
                  ? (details) => _handleVerticalDrag(
                        details,
                        constraints.maxWidth,
                      )
                  : null,
              onVerticalDragEnd:
                  surfaceGesturesEnabled ? (_) => _clearGestureOverlay() : null,
              child: Stack(
                fit: StackFit.expand,
                children: [
                  const ColoredBox(color: Colors.black),
                  for (final surfaceController in mountedLibVlcControllers)
                    KeyedSubtree(
                      key: ValueKey<int>(identityHashCode(surfaceController)),
                      child: ExcludeSemantics(
                        excluding: !identical(surfaceController, controller),
                        child: IgnorePointer(
                          ignoring: !identical(surfaceController, controller),
                          child: Opacity(
                            opacity: identical(
                              surfaceController,
                              visibleLibVlcController,
                            )
                                ? 1
                                : 0.01,
                            child: _VideoSurface(
                              controller: surfaceController,
                              fitMode: _fitMode,
                            ),
                          ),
                        ),
                      ),
                    ),
                  if (_mobileLibVlcSeekNeedsVisibleFallback)
                    const _NativeSeekPreparationSurface(),
                  if (controller != null &&
                      controller.engine != _NativePlaybackEngine.libvlc &&
                      (initialized || controller.requiresPlatformViewWarmup))
                    _VideoSurface(controller: controller, fitMode: _fitMode),
                  if (_loading && !initialized)
                    _NativePlayerLoading(
                      title: _title,
                      logoUrl: _logoUrl,
                      backgroundUrl: _progressItem?.background,
                      backdropStyle: AppState
                          .playerBehaviorSettings.value.loadingBackdropStyle,
                      message: _statusMessage,
                      onBack: () {
                        unawaited(
                          _nativeProvidersExhausted || controller == null
                              ? _close('closed')
                              : _requestClose(),
                        );
                      },
                      onRetry: _nativeProvidersExhausted
                          ? () {
                              _beginLibVlcLaunchGeneration(
                                reason: 'explicit_retry',
                              );
                              _failureCloseGeneration += 1;
                              _providerIndex = 0;
                              _sourceIndex = 0;
                              _enginePassIndex = 0;
                              _qualityPassIndex = 0;
                              _libvlcUnavailableForSession = false;
                              _liveTvAutoRetryAttempted = false;
                              _skipUnsupportedHighEfficiencyForSession = false;
                              _nativeSourceClassSkipCounts.clear();
                              _providerResolveFutures.clear();
                              _failedSourceAttempts.clear();
                              _media3TerminalFailedUrlsForSession.clear();
                              _blackVideoRecoveredUrls.clear();
                              final status = _enginePassStatusFor(
                                _enginePassesForCurrentSettings(),
                              );
                              _logPlaybackStatus(
                                status,
                                reason: 'retry_sources',
                              );
                              setState(() {
                                _loading = true;
                                _controlsVisible = true;
                                _nativeProvidersExhausted = false;
                                _statusMessage = status;
                              });
                              unawaited(_openNextAvailableSource());
                            }
                          : null,
                      onChooseSource:
                          _nativeProvidersExhausted && _activeSources.length > 1
                              ? () => unawaited(_showSourceSheet())
                              : null,
                    ),
                  if (_loading && initialized && !_mobileLibVlcSeekPreparing)
                    _NativeRefreshOverlay(
                      message: _statusMessage ?? 'Refreshing...',
                      onBack: () => unawaited(_requestClose()),
                    ),
                  if (_mobileLibVlcSeekPreparing && initialized)
                    _NativePlaybackStatusOverlay(
                      label: _statusMessage ?? 'Seeking...',
                    ),
                  if (!_loading && _playbackWaitMessage != null)
                    _NativePlaybackStatusOverlay(label: _playbackWaitMessage!),
                  if (!nativeControlsReady &&
                      !_loading &&
                      !controlsSuppressed &&
                      !_pictureInPictureActive)
                    SafeArea(
                      child: Align(
                        alignment: Alignment.topLeft,
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: _PlayerRoundButton(
                            icon: Icons.arrow_back_rounded,
                            semanticLabel: 'Close player',
                            onPressed: () => unawaited(_requestClose()),
                          ),
                        ),
                      ),
                    ),
                  if (_subtitleText != null && seekControlsReady)
                    _SubtitleOverlay(
                      text: _subtitleText!,
                      fontSize: _subtitleFontSize,
                      backgroundOpacity: _subtitleBackgroundOpacity,
                      backgroundColor: _subtitleBackgroundColor,
                      backgroundRadius: _subtitleBackgroundRadius,
                      textColor: _subtitleTextColor,
                      bottomOffset:
                          (_pictureInPictureActive || _systemPipHandoffActive)
                              ? 8
                              : _subtitleBottomOffset,
                      compactMode: compactPlayer,
                    ),
                  if (controlsDimmed)
                    Positioned.fill(
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTap: _settingsExpanded && !_loading
                            ? _toggleSettingsPack
                            : null,
                        child: AnimatedOpacity(
                          opacity: controlsDimmed ? 1 : 0,
                          duration: const Duration(milliseconds: 180),
                          child: IgnorePointer(
                            child: ColoredBox(
                              color: Colors.black.withValues(alpha: 0.52),
                            ),
                          ),
                        ),
                      ),
                    ),
                  if (seekControlsReady &&
                      _playbackWaitMessage == null &&
                      !controlsSuppressed &&
                      nativeControlsReady &&
                      !_pictureInPictureActive)
                    KeyedSubtree(
                      key: hudTransportMountOwner.activePlayerBoundsKey,
                      child: _AnimatedPlayerControls(
                        key: ValueKey<int>(_hudRevealGeneration),
                        visible: _controlsVisible && nativeControlsReady,
                        child: _NativePlayerControls(
                          title: _title,
                          accentColor: _playerAccent(context),
                          controlsVisible:
                              _controlsVisible && nativeControlsReady,
                          nextEpisodeLabel: _nextEpisodeLabel,
                          controller: controller,
                          bufferedPositionOverride:
                              _libVlcContinuousTsBufferedPosition,
                          fallbackDuration: fallbackDuration,
                          fallbackPosition: fallbackPosition,
                          skipSegment: skipSegment,
                          locked: _locked,
                          liveMode: _isLiveTvMode,
                          buffering: initialized &&
                              controller!.isBuffering &&
                              !_recoveringFromStall,
                          onBack: () {
                            unawaited(_requestClose());
                          },
                          onNextEpisode: _nextEpisodeLabel == null
                              ? null
                              : () {
                                  DiagnosticLog.add(
                                    'native next episode pressed label="$_nextEpisodeLabel"',
                                  );
                                  unawaited(_openNextEpisodeInPlace());
                                },
                          onPlayPause: _togglePlayback,
                          seekStepSeconds: _seekStepSeconds.round(),
                          onSeekBackward: () => _seekBy(
                            Duration(seconds: -_seekStepSeconds.round()),
                          ),
                          onSeekForward: () => _seekBy(
                            Duration(seconds: _seekStepSeconds.round()),
                          ),
                          onSeekToFraction: _seekToFraction,
                          onSkipSegment: skipSegment == null
                              ? null
                              : () => unawaited(_skipToSegment(skipSegment)),
                          onToggleLock: _toggleLock,
                          onEnterPip: _handlePictureInPictureButton,
                          onOpenCast: _openScreencast,
                          pipSupported: _canEnterSystemPictureInPicture(),
                          sourceSelectionAvailable: _activeSources.length > 1,
                          onSourcePressed: _showSourceSheet,
                          sourceActionLabel: _sourceActionLabel(),
                          sourceIndicator: _sourceIndicatorLabel(),
                          qualityLabel: _qualityControlLabel(
                            _usingGlobalOverrides,
                            _qualityPreferenceMode,
                            _preferredQuality,
                          ),
                          onQualityPressed: _showQualitySheet,
                          speedLabel: _speedLabel(_playbackSpeed),
                          onSpeedPressed: _showSpeedSheet,
                          fitMode: _fitMode,
                          onFitPressed: _showFitSheet,
                          onReloadPressed: _reloadCurrentSource,
                          settingsExpanded: _settingsExpanded,
                          limitedSettingsMode: _usingGlobalOverrides,
                          onToggleSettings: _toggleSettingsPack,
                          subtitlesAvailable: _subtitles.isNotEmpty,
                          subtitlesEnabled: _activeSubtitle != null,
                          onSubtitlePressed: _showSubtitleSheet,
                          compactMode: compactPlayer,
                          pictureInPictureActive: _pictureInPictureActive,
                          hudTransportMountOwner: hudTransportMountOwner,
                          onHudTransportControlShown: (slot) =>
                              _handleHudTransportAnimationCompleted(
                            hudTransportMountOwner,
                            slot,
                          ),
                        ),
                      ),
                    ),
                  if (_gestureLabel != null)
                    _GestureOverlay(icon: _gestureIcon, label: _gestureLabel!),
                  if (!_loading && !controlsSuppressed)
                    AnimatedSwitcher(
                      duration: const Duration(milliseconds: 220),
                      reverseDuration: const Duration(milliseconds: 180),
                      child: _controlsVisible && _gestureHintVisible
                          ? const _GestureHintOverlay(
                              key: ValueKey('gesture-hint'),
                            )
                          : const SizedBox.shrink(
                              key: ValueKey('gesture-hint-hidden'),
                            ),
                    ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

class _NowPlayingTitleReveal extends StatefulWidget {
  const _NowPlayingTitleReveal({
    required this.rawTitle,
    required this.accentColor,
    required this.visible,
    required this.compact,
  });

  final String rawTitle;
  final Color accentColor;
  final bool visible;
  final bool compact;

  @override
  State<_NowPlayingTitleReveal> createState() => _NowPlayingTitleRevealState();
}

class _NowPlayingTitleRevealState extends State<_NowPlayingTitleReveal> {
  Timer? _titleTimer;
  bool _labelVisible = false;
  bool _titleVisible = false;

  @override
  void initState() {
    super.initState();
    _syncVisibility();
  }

  @override
  void didUpdateWidget(covariant _NowPlayingTitleReveal oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.visible != widget.visible ||
        oldWidget.rawTitle != widget.rawTitle) {
      _syncVisibility();
    }
  }

  @override
  void dispose() {
    _titleTimer?.cancel();
    super.dispose();
  }

  void _syncVisibility() {
    _titleTimer?.cancel();
    if (!widget.visible) {
      _labelVisible = false;
      _titleVisible = false;
      return;
    }
    _labelVisible = true;
    _titleVisible = false;
    _titleTimer = Timer(const Duration(milliseconds: 120), () {
      if (!mounted) return;
      setState(() => _titleVisible = true);
    });
  }

  @override
  Widget build(BuildContext context) {
    final split = _splitNowPlayingTitle(widget.rawTitle);
    final titleStyle = Theme.of(context).textTheme.titleLarge?.copyWith(
      color: Colors.white,
      fontWeight: FontWeight.w900,
      fontSize: widget.compact ? 15 : 18,
      height: 1.08,
      shadows: [
        Shadow(
          color: Colors.black.withValues(alpha: 0.72),
          blurRadius: 8,
        ),
        Shadow(
          color: Colors.black.withValues(alpha: 0.36),
          blurRadius: 2,
          offset: const Offset(0, 1),
        ),
      ],
    );
    return IgnorePointer(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          _NowPlayingRevealLine(
            visible: _labelVisible,
            delayOffset: -0.12,
            child: Text(
              'NOW PLAYING',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.center,
              style: TextStyle(
                color: widget.accentColor,
                fontSize: widget.compact ? 8 : 10,
                fontWeight: FontWeight.w900,
                height: 1.0,
                shadows: [
                  Shadow(
                    color: Colors.black.withValues(alpha: 0.65),
                    blurRadius: 8,
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 3),
          _NowPlayingRevealLine(
            visible: _titleVisible,
            delayOffset: 0.12,
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Flexible(
                  child: Text(
                    split.title,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    textAlign: TextAlign.center,
                    style: titleStyle,
                  ),
                ),
                if (split.episodeLabel != null) ...[
                  const SizedBox(width: 7),
                  Text(
                    split.episodeLabel!,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: titleStyle?.copyWith(
                      color: Colors.white.withValues(alpha: 0.82),
                      fontSize: widget.compact ? 12 : 14,
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _NowPlayingRevealLine extends StatelessWidget {
  const _NowPlayingRevealLine({
    required this.visible,
    required this.delayOffset,
    required this.child,
  });

  final bool visible;
  final double delayOffset;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    return AnimatedOpacity(
      opacity: visible ? 1 : 0,
      duration: const Duration(milliseconds: 180),
      curve: Curves.easeOutCubic,
      child: AnimatedSlide(
        offset: visible ? Offset.zero : Offset(0, delayOffset),
        duration: const Duration(milliseconds: 220),
        curve: Curves.easeOutCubic,
        child: child,
      ),
    );
  }
}

({String title, String? episodeLabel}) _splitNowPlayingTitle(String rawTitle) {
  final title = rawTitle.trim();
  if (title.isEmpty) return (title: 'Now playing', episodeLabel: null);
  final match =
      RegExp(r'\s+(S\d+\s*E\d+)$', caseSensitive: false).firstMatch(title);
  if (match == null) return (title: title, episodeLabel: null);
  final episodeLabel = match.group(1)?.replaceAll(RegExp(r'\s+'), ' ');
  final cleanTitle = title.substring(0, match.start).trim();
  if (cleanTitle.isEmpty || episodeLabel == null) {
    return (title: title, episodeLabel: null);
  }
  return (title: cleanTitle, episodeLabel: episodeLabel.toUpperCase());
}

String _speedLabel(double value) {
  if ((value - 1).abs() < 0.001) return '1x';
  return '${value.toStringAsFixed(value % 1 == 0 ? 0 : 2).replaceAll(RegExp(r'0$'), '').replaceAll(RegExp(r'\.$'), '')}x';
}

String _speedMenuLabel(String label) {
  return label == '1x' ? '1x (Normal)' : label;
}

String _subtitleDelayLabel(double seconds) {
  if (seconds.abs() < 0.01) return '0s';
  final sign = seconds > 0 ? '+' : '';
  final value = seconds % 1 == 0
      ? seconds.toStringAsFixed(0)
      : seconds.toStringAsFixed(1);
  return '$sign${value}s';
}

String _subtitlePositionLabel(double bottomOffset) {
  if (bottomOffset <= 34) return 'Low';
  if (bottomOffset >= 72) return 'High';
  return 'Mid';
}

String _fitModeLabel(VideoFitMode mode) {
  return switch (mode) {
    VideoFitMode.fit => 'Fit',
    VideoFitMode.fill => 'Fill',
    VideoFitMode.wide => 'Wide',
    VideoFitMode.stretch => 'Stretch',
  };
}

String _qualityLabel(PlaybackSource? source) {
  return _displayQualityLabel(playbackQualityLabel(source));
}

String _displayQualityLabel(String quality) {
  final trimmed = quality.trim();
  if (trimmed.isEmpty) return 'Auto';
  final lower = trimmed.toLowerCase();
  if (lower == 'auto' || lower == 'unknown') return 'Auto';
  return trimmed.replaceAllMapped(
    RegExp(r'(\d+)\s*p\b', caseSensitive: false),
    (match) {
      final rawHeight = int.tryParse(match.group(1) ?? '');
      if (rawHeight == null || rawHeight <= 0) return match.group(0)!;
      return '${_normalizedPlaybackQualityHeight(rawHeight)}P';
    },
  );
}

int _normalizedPlaybackQualityHeight(int height) {
  if (height >= 120 && height <= 170) return 144;
  if (height >= 220 && height <= 285) return 240;
  if (height >= 320 && height <= 390) return 360;
  if (height >= 430 && height <= 505) return 480;
  if (height >= 520 && height <= 570) return 480;
  if (height >= 640 && height <= 820) return 720;
  if (height >= 1000 && height <= 1120) return 1080;
  if (height >= 1320 && height <= 1500) return 1440;
  if (height >= 1900 && height <= 2250) return 2160;
  if (height >= 3900 && height <= 4450) return 4320;
  return height;
}

String _qualityControlLabel(
  bool usingGlobalOverrides,
  String qualityPreferenceMode,
  String? preferredQuality,
) {
  if (!usingGlobalOverrides) {
    return preferredQuality ?? 'Auto';
  }
  return switch (qualityPreferenceMode) {
    'higher' => 'Higher quality',
    'dataSaver' => 'Data saver',
    'advanced' => preferredQuality ?? 'Auto',
    _ => 'Recommended',
  };
}

int _qualityRank(String label) {
  return playbackQualityRank(label);
}

int _dataSaverQualityRank(String label) {
  final rank = _qualityRank(label);
  return rank > 0 ? rank : 9999;
}

P2pPriorityConfig _p2pPriorityConfigFromSettings() {
  final behavior = AppState.playerBehaviorSettings.value;
  return P2pPriorityConfig(
    enabled: behavior.p2pSourcePrioritiesEnabled,
    mode: behavior.p2pPriorityMode,
    resultsPerQuality: behavior.p2pResultsPerQuality,
    preferredAudioLanguageMode: behavior.p2pPreferredAudioLanguageMode,
    avoidRiskyFormats: behavior.p2pAvoidRiskyFormats,
    sizeLimitMb: behavior.p2pSizeLimitMb,
  );
}

int _nativeSourceClassRank(PlaybackSource source) {
  return switch (source.sourceClass) {
    PlaybackSourceClass.direct => 0,
    PlaybackSourceClass.debrid => 0,
    PlaybackSourceClass.p2p => 1,
    PlaybackSourceClass.external =>
      AppState.playbackSourceClassAllowedForNative(source.sourceClass) ? 2 : 3,
    PlaybackSourceClass.unsupported => 3,
  };
}

class _P2pLocalStreamReady {
  const _P2pLocalStreamReady({this.totalBytes});

  final int? totalBytes;
}

class _P2pLocalStreamNotReadyException implements Exception {
  const _P2pLocalStreamNotReadyException({required this.deadSwarm});

  final bool deadSwarm;

  @override
  String toString() => deadSwarm
      ? 'P2P local stream is still buffering: no peers yet.'
      : 'P2P local stream is still buffering.';
}

int _p2pTrackerCount(PlaybackSource source) {
  return P2pStreamDescriptor.fromSyntheticUrl(source.url)?.trackers.length ?? 0;
}

List<_DisplaySourceEntry> _displaySourceEntries(List<PlaybackSource> sources) {
  return groupVisiblePlaybackSources(sources)
      .map(
        (group) => _DisplaySourceEntry(
          primary: group.primary,
          variants: group.variants,
        ),
      )
      .toList(growable: false);
}

(int, int) _displaySourceProgress(
  List<PlaybackSource> sources,
  int sourceIndex,
) {
  return visiblePlaybackSourceProgress(sources, sourceIndex);
}

int? _nextSourceIndexInCurrentVisibleGroup(
  List<PlaybackSource> sources,
  int sourceIndex,
) {
  if (sources.isEmpty || sourceIndex < 0 || sourceIndex >= sources.length)
    return null;
  final currentUrl = sources[sourceIndex].url;
  if (currentUrl.isEmpty) return null;
  final groups = groupVisiblePlaybackSources(sources);
  final visibleIndex = groups.indexWhere(
    (group) => group.variants.any((source) => source.url == currentUrl),
  );
  if (visibleIndex < 0) return null;
  final variants = groups[visibleIndex].variants;
  final variantIndex = variants.indexWhere(
    (source) => source.url == currentUrl,
  );
  if (variantIndex < 0 || variantIndex + 1 >= variants.length) return null;
  for (final source in variants.skip(variantIndex + 1)) {
    if (!_nativeSourceClassIsPlayable(source)) continue;
    final nextSourceIndex = sources.indexWhere(
      (candidate) => candidate.url == source.url,
    );
    if (nextSourceIndex >= 0) return nextSourceIndex;
  }
  return null;
}

int? _nextSourceIndexAfterCurrentVisibleGroup(
  List<PlaybackSource> sources,
  int sourceIndex,
) {
  if (sources.isEmpty || sourceIndex < 0 || sourceIndex >= sources.length)
    return null;
  final currentUrl = sources[sourceIndex].url;
  if (currentUrl.isEmpty) return null;
  final groups = groupVisiblePlaybackSources(sources);
  final visibleIndex = groups.indexWhere(
    (group) => group.variants.any((source) => source.url == currentUrl),
  );
  if (visibleIndex < 0 || visibleIndex + 1 >= groups.length) return null;
  for (final group in groups.skip(visibleIndex + 1)) {
    final playableSource = _nativePlayableSourceForEntry(
      _DisplaySourceEntry(primary: group.primary, variants: group.variants),
    );
    if (playableSource == null) continue;
    final nextSourceIndex = sources.indexWhere(
      (source) => source.url == playableSource.url,
    );
    if (nextSourceIndex >= 0) return nextSourceIndex;
  }
  return null;
}

String _sourceDisplayLabel(
  PlaybackSource source, {
  required int index,
  required int total,
}) {
  final quality = _qualityLabel(source);
  final parts = <String>['Source ${index + 1}'];
  if (total > 1) parts[0] = 'Source ${index + 1}/$total';
  if (quality != 'Auto') parts.add(quality);
  final sourceClassLabel = _sourceClassDisplayLabel(source);
  if (sourceClassLabel != null) parts.add(sourceClassLabel);
  return parts.join(' - ');
}

String? _sourceClassDisplayLabel(PlaybackSource source) {
  return switch (source.sourceClass) {
    PlaybackSourceClass.direct => null,
    PlaybackSourceClass.debrid => 'Cached',
    PlaybackSourceClass.external => 'External',
    PlaybackSourceClass.p2p => 'P2P',
    PlaybackSourceClass.unsupported => 'Unsupported',
  };
}

String _sourceTransportDisplayLabel(PlaybackSource? source) {
  if (source == null) return 'Stream';
  if (mobileIsHlsSourceDescriptor(source)) return 'HLS';
  final type = (source.type ?? '').trim().toLowerCase();
  final url = source.url.trim().toLowerCase();
  if (type == 'mp4' ||
      type == 'video/mp4' ||
      type == 'application/mp4' ||
      url.contains('.mp4')) {
    return 'MP4';
  }
  return 'Stream';
}

String _sourceTransportGroupDisplayLabel(
  Iterable<PlaybackSource> sources,
) {
  final labels = sources.map(_sourceTransportDisplayLabel).toSet();
  if (labels.isEmpty) return 'Stream';
  if (labels.length == 1) return labels.first;
  return 'Mixed formats';
}

bool _nativeSourceClassIsPlayable(PlaybackSource source) {
  return AppState.playbackSourceClassAllowedForNative(source.sourceClass);
}

PlaybackSource? _nativePlayableSourceForEntry(_DisplaySourceEntry entry) {
  for (final source in entry.variants) {
    if (_nativeSourceClassIsPlayable(source)) return source;
  }
  return null;
}

List<PlaybackSource> _nativePlayableSources(List<PlaybackSource> sources) {
  return sources.where(_nativeSourceClassIsPlayable).toList(growable: false);
}

String _sourceClassDisabledReason(PlaybackSource source) {
  final behavior = AppState.playerBehaviorSettings.value;
  return switch (source.sourceClass) {
    PlaybackSourceClass.external =>
      'External source - native playback cannot open this yet.',
    PlaybackSourceClass.p2p => !P2pLocalStreamBridge.instance.isAvailable
        ? 'P2P source - Advanced P2P support is not installed yet.'
        : !behavior.p2pPlaybackConsentAccepted
            ? 'P2P source - review advanced consent before playback.'
            : !behavior.p2pPlaybackEnabled
                ? 'P2P source - advanced playback is off.'
                : 'P2P source - waiting for approved runtime proof.',
    PlaybackSourceClass.unsupported =>
      'Unsupported source type for this build.',
    PlaybackSourceClass.direct ||
    PlaybackSourceClass.debrid =>
      'Native playback supported.',
  };
}

String? _sourceLanguageLabel(PlaybackSource source) {
  return playbackSourceLanguageLabel(source);
}

String _providerLabel(String? providerId) {
  final normalized = (providerId ?? '').trim().toLowerCase();
  if (normalized.startsWith('addon-')) return 'stream add-on';
  return switch (normalized) {
    'public-iptv' => 'Live TV',
    '' => 'playback option',
    _ => 'playback option',
  };
}

bool _isPublicIptvSource(PlaybackSource source) {
  return source.providerId.trim().toLowerCase() == 'public-iptv';
}

class _AnimatedPlayerControls extends StatefulWidget {
  const _AnimatedPlayerControls({
    super.key,
    required this.visible,
    required this.child,
  });

  final bool visible;
  final Widget child;

  @override
  State<_AnimatedPlayerControls> createState() =>
      _AnimatedPlayerControlsState();
}

class _AnimatedPlayerControlsState extends State<_AnimatedPlayerControls> {
  Timer? _chromeHideTimer;
  late bool _chromeVisible;

  @override
  void initState() {
    super.initState();
    _chromeVisible = widget.visible;
  }

  @override
  void didUpdateWidget(covariant _AnimatedPlayerControls oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.visible == oldWidget.visible) return;
    _chromeHideTimer?.cancel();
    if (widget.visible) {
      setState(() => _chromeVisible = true);
      return;
    }
    _chromeHideTimer = Timer(const Duration(milliseconds: 240), () {
      if (!mounted || widget.visible) return;
      setState(() => _chromeVisible = false);
    });
  }

  @override
  void dispose() {
    _chromeHideTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final curve = _chromeVisible ? Curves.easeOutCubic : Curves.easeInCubic;
    final duration = Duration(milliseconds: _chromeVisible ? 140 : 180);
    return IgnorePointer(
      ignoring: !widget.visible,
      child: AnimatedOpacity(
        opacity: _chromeVisible ? 1 : 0,
        duration: duration,
        curve: curve,
        child: widget.child,
      ),
    );
  }
}

class _StagedHudControlReveal extends StatefulWidget {
  const _StagedHudControlReveal({
    required this.visible,
    required this.delay,
    required this.hideDelay,
    required this.beginOffset,
    required this.child,
    this.onShown,
  });

  final bool visible;
  final Duration delay;
  final Duration hideDelay;
  final Offset beginOffset;
  final Widget child;
  final VoidCallback? onShown;

  @override
  State<_StagedHudControlReveal> createState() =>
      _StagedHudControlRevealState();
}

class _StagedHudControlRevealState extends State<_StagedHudControlReveal> {
  Timer? _revealTimer;
  bool _visible = false;

  @override
  void initState() {
    super.initState();
    _scheduleVisibility(widget.visible);
  }

  @override
  void didUpdateWidget(covariant _StagedHudControlReveal oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.visible == oldWidget.visible) return;
    _scheduleVisibility(widget.visible);
  }

  void _scheduleVisibility(bool visible) {
    _revealTimer?.cancel();
    final delay = visible ? widget.delay : widget.hideDelay;
    _revealTimer = Timer(delay, () {
      if (!mounted) return;
      if (widget.visible != visible) return;
      setState(() => _visible = visible);
    });
  }

  @override
  void dispose() {
    _revealTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ExcludeSemantics(
      excluding: !widget.visible || !_visible,
      child: IgnorePointer(
        ignoring: !widget.visible || !_visible,
        child: AnimatedOpacity(
          opacity: _visible ? 1 : 0,
          duration: const Duration(milliseconds: 180),
          curve: Curves.easeOutCubic,
          onEnd: () {
            if (_visible && widget.visible) widget.onShown?.call();
          },
          child: AnimatedSlide(
            offset: _visible ? Offset.zero : widget.beginOffset,
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOutCubic,
            child: AnimatedScale(
              scale: _visible ? 1 : 0.88,
              duration: const Duration(milliseconds: 180),
              curve: Curves.easeOutBack,
              child: widget.child,
            ),
          ),
        ),
      ),
    );
  }
}

class _VideoSurface extends StatelessWidget {
  const _VideoSurface({
    required this.controller,
    required this.fitMode,
  });

  final _NativePlaybackController controller;
  final VideoFitMode fitMode;

  @override
  Widget build(BuildContext context) {
    final size = controller.size;
    final width = size.width > 0 ? size.width : 16.0;
    final height = size.height > 0 ? size.height : 9.0;
    final displayAspectRatio = _displayAspectRatioFor(controller);
    final player = _NativePlaybackSurface(
      controller: controller,
      aspectRatio: displayAspectRatio,
    );

    return switch (fitMode) {
      VideoFitMode.fit => LayoutBuilder(
          builder: (context, constraints) {
            final viewportWidth = constraints.maxWidth;
            final viewportHeight = constraints.maxHeight;
            if (viewportWidth <= 0 || viewportHeight <= 0) {
              return const SizedBox.shrink();
            }
            var fitHeight = viewportHeight;
            final viewportRatio = viewportWidth / viewportHeight;
            final platformMedia3 = controller.media3 != null;
            if (platformMedia3 && viewportRatio > displayAspectRatio + 0.08) {
              fitHeight = viewportHeight * 0.82;
            }
            final fitWidth = math.min(
              viewportWidth,
              fitHeight * displayAspectRatio,
            );
            final resolvedHeight = fitWidth / displayAspectRatio;
            return Center(
              child: SizedBox(
                width: fitWidth,
                height: resolvedHeight,
                child: player,
              ),
            );
          },
        ),
      VideoFitMode.fill => SizedBox.expand(
          child: ClipRect(
            child: FittedBox(
              fit: BoxFit.cover,
              child: SizedBox(width: width, height: height, child: player),
            ),
          ),
        ),
      VideoFitMode.wide => Center(
          child: ClipRect(
            child: AspectRatio(
              aspectRatio: 16 / 9,
              child: FittedBox(
                fit: BoxFit.cover,
                child: SizedBox(width: width, height: height, child: player),
              ),
            ),
          ),
        ),
      VideoFitMode.stretch => SizedBox.expand(child: player),
    };
  }
}

double _displayAspectRatioFor(_NativePlaybackController controller) {
  final size = controller.size;
  if (size.width > 0 && size.height > 0) {
    return size.width / size.height;
  }
  final raw = controller.aspectRatio;
  if (raw.isFinite && raw > 1.05) return raw;
  return 16 / 9;
}

class _NativePlaybackSurface extends StatelessWidget {
  const _NativePlaybackSurface({
    required this.controller,
    required this.aspectRatio,
  });

  final _NativePlaybackController controller;
  final double aspectRatio;

  @override
  Widget build(BuildContext context) {
    final video = controller.video;
    if (video != null) return VideoPlayer(video);
    final media3 = controller.media3;
    if (media3 != null) {
      return IgnorePointer(
        child: AndroidView(
          key: ValueKey<int>(identityHashCode(media3)),
          viewType: 'app.juicr.flutter/media3_player',
          creationParams: media3.creationParams,
          creationParamsCodec: const StandardMessageCodec(),
          onPlatformViewCreated: media3.attachView,
        ),
      );
    }
    final vlc = controller.vlc;
    if (vlc != null) {
      controller.markPlatformSurfaceBuilt();
      return VlcPlayer(
        key: ValueKey<int>(identityHashCode(vlc)),
        controller: vlc,
        aspectRatio: aspectRatio,
        placeholder: const ColoredBox(color: Colors.black),
        virtualDisplay: true,
        onPlatformViewCreated: (viewId) {
          DiagnosticLog.add(
            'native libvlc lifecycle stage=platform_view_callback',
          );
          unawaited(
            vlc.onPlatformViewCreated(viewId).then((_) {
              DiagnosticLog.add(
                'native libvlc lifecycle stage=platform_view_bound',
              );
            }).catchError((Object error) {
              DiagnosticLog.add(
                'native libvlc lifecycle stage=platform_view_bind_failed '
                'error=${_safeDiagnosticError(error)}',
              );
            }),
          );
        },
      );
    }
    return const SizedBox.shrink();
  }
}

