class _MiniPipSeekBar extends StatelessWidget {
  const _MiniPipSeekBar({
    required this.progress,
    required this.bufferedProgress,
    required this.initialized,
    required this.onSeekToFraction,
    required this.currentText,
    required this.durationText,
    required this.fontSize,
    required this.trackHeight,
    required this.thumbRadius,
  });

  final double progress;
  final double? bufferedProgress;
  final bool initialized;
  final ValueChanged<double> onSeekToFraction;
  final String currentText;
  final String durationText;
  final double fontSize;
  final double trackHeight;
  final double thumbRadius;

  @override
  Widget build(BuildContext context) {
    final effectiveProgress = progress.clamp(0.0, 1.0).toDouble();
    final effectiveBufferedProgress = bufferedProgress?.clamp(
      effectiveProgress,
      1.0,
    );
    final trackTop = thumbRadius;
    final labelTop = thumbRadius * 2 + 4;
    final height = labelTop + fontSize + 3;

    void seekFromLocal(Offset localPosition, BoxConstraints constraints) {
      if (!initialized || constraints.maxWidth <= 0) {
        return;
      }
      onSeekToFraction((localPosition.dx / constraints.maxWidth).clamp(0, 1));
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        final trackWidth = constraints.maxWidth;
        return GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTapDown: (details) =>
              seekFromLocal(details.localPosition, constraints),
          onHorizontalDragUpdate: (details) =>
              seekFromLocal(details.localPosition, constraints),
          child: SizedBox(
            height: height,
            child: Stack(
              clipBehavior: Clip.none,
              children: [
                Positioned(
                  left: 0,
                  right: 0,
                  top: trackTop,
                  child: Container(
                    height: trackHeight,
                    decoration: BoxDecoration(
                      color: _playerUnbufferedTrackColor,
                      borderRadius: BorderRadius.circular(trackHeight),
                    ),
                  ),
                ),
                if (effectiveBufferedProgress != null)
                  Positioned(
                    left: 0,
                    width: trackWidth * effectiveBufferedProgress,
                    top: trackTop,
                    child: Container(
                      height: trackHeight,
                      decoration: BoxDecoration(
                        color: _playerBufferedTrackColor,
                        borderRadius: BorderRadius.circular(trackHeight),
                      ),
                    ),
                  ),
                Positioned(
                  left: 0,
                  width: trackWidth * effectiveProgress,
                  top: trackTop,
                  child: Container(
                    height: trackHeight,
                    decoration: BoxDecoration(
                      color: _playerAccent(context),
                      borderRadius: BorderRadius.circular(trackHeight),
                    ),
                  ),
                ),
                Positioned(
                  left: 0,
                  top: labelTop,
                  child: _MiniPipTimeText(
                    text: currentText,
                    fontSize: fontSize,
                  ),
                ),
                Positioned(
                  right: 0,
                  top: labelTop,
                  child: _MiniPipTimeText(
                    text: durationText,
                    fontSize: fontSize,
                    alignRight: true,
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

