  final VoidCallback onQualityPressed;
  final String speedLabel;
  final VoidCallback onSpeedPressed;
  final VideoFitMode fitMode;
  final VoidCallback onFitPressed;
  final VoidCallback onReloadPressed;
  final bool settingsExpanded;
  final bool limitedSettingsMode;
  final VoidCallback onToggleSettings;
  final bool subtitlesAvailable;
  final bool subtitlesEnabled;
  final VoidCallback onSubtitlePressed;
  final bool compactMode;
  final bool pictureInPictureActive;
  final NativeHudTransportMountOwner hudTransportMountOwner;
  final ValueChanged<NativeHudTransportSlot> onHudTransportControlShown;

  @override
  Widget build(BuildContext context) {
    final initialized = controller?.isInitialized == true;
    final playing = controller?.isPlaying == true;
    final controllerPosition =
        initialized ? controller!.position : Duration.zero;
    final position = fallbackPosition > controllerPosition
        ? fallbackPosition
        : controllerPosition;
    final controllerDuration =
        initialized ? controller!.duration : Duration.zero;
    final duration = controllerDuration > Duration.zero
        ? controllerDuration
        : fallbackDuration;
    final progress = duration.inMilliseconds <= 0
        ? 0.0
        : position.inMilliseconds / duration.inMilliseconds;
    final watchedProgress = progress.clamp(0, 1).toDouble();
    final bufferedProgress = controller == null
        ? null
        : _trustedBufferedProgress(
            controller: controller!,
            bufferedPositionOverride: bufferedPositionOverride,
            duration: duration,
            watchedProgress: watchedProgress,
          );
    final padding = MediaQuery.paddingOf(context);

    if (compactMode) {
      return _CompactNativePlayerControls(
        controlsVisible: controlsVisible,
        initialized: initialized,
        playing: playing,
        liveMode: liveMode,
        position: position,
        duration: duration,
        progress: watchedProgress,
        bufferedProgress: bufferedProgress,
        seekStepSeconds: seekStepSeconds,
        onBack: onBack,
        onFullscreen: onEnterPip,
        onPlayPause: onPlayPause,
        onSeekBackward: onSeekBackward,
        onSeekForward: onSeekForward,
        onSeekToFraction: onSeekToFraction,
        pictureInPictureActive: pictureInPictureActive,
      );
    }

    return Stack(
      fit: StackFit.expand,
      children: [
        const _ControlGradient(alignment: Alignment.topCenter),
        const _ControlGradient(alignment: Alignment.bottomCenter),
        if (!locked)
          Positioned.fill(
            child: Stack(
              children: [
                if (!liveMode)
                  Align(
                    alignment: const Alignment(-0.50, 0),
                    child: _StagedHudControlReveal(
                      visible: controlsVisible,
                      delay: const Duration(milliseconds: 120),
                      hideDelay: Duration.zero,
                      beginOffset: const Offset(-0.14, 0),
                      onShown: () => onHudTransportControlShown(
                        NativeHudTransportSlot.leftSkip,
                      ),
                      child: KeyedSubtree(
                        key: hudTransportMountOwner.leftSkipKey,
                        child: _SeekButton(
                          forward: false,
                          seconds: seekStepSeconds,
                          onPressed: onSeekBackward,
                        ),
                      ),
                    ),
                  ),
                Align(
                  alignment: Alignment.center,
                  child: _StagedHudControlReveal(
                    visible: controlsVisible,
                    delay: Duration.zero,
                    hideDelay: const Duration(milliseconds: 120),
                    beginOffset: Offset.zero,
                    onShown: () => onHudTransportControlShown(
                      NativeHudTransportSlot.centerPlayPause,
                    ),
                    child: KeyedSubtree(
                      key: hudTransportMountOwner.centerPlayPauseKey,
                      child: _MainPlayButton(
                        playing: playing,
                        enabled: initialized,
                        onPressed: onPlayPause,
                      ),
                    ),
                  ),
                ),
                if (!liveMode)
                  Align(
                    alignment: const Alignment(0.50, 0),
                    child: _StagedHudControlReveal(
                      visible: controlsVisible,
                      delay: const Duration(milliseconds: 120),
                      hideDelay: Duration.zero,
                      beginOffset: const Offset(0.14, 0),
                      onShown: () => onHudTransportControlShown(
                        NativeHudTransportSlot.rightSkip,
                      ),
                      child: KeyedSubtree(
                        key: hudTransportMountOwner.rightSkipKey,
                        child: _SeekButton(
                          forward: true,
                          seconds: seekStepSeconds,
                          onPressed: onSeekForward,
                        ),
                      ),
                    ),
                  ),
              ],
            ),
          ),
        Positioned(
          top: padding.top + 8,
          left: 0,
          right: 0,
          child: SizedBox(
            height: 44,
            child: Stack(
              alignment: Alignment.center,
              children: [
                if (!locked)
                  Align(
                    alignment: Alignment.centerLeft,
                    child: Padding(
                      padding: EdgeInsets.only(left: padding.left + 12),
                      child: _PlayerRoundButton(
                        icon: Icons.arrow_back_rounded,
                        semanticLabel: 'Close player',
                        onPressed: onBack,
                      ),
                    ),
                  ),
                if (!locked)
                  LayoutBuilder(
                    builder: (context, headerConstraints) {
                      final titleMaxWidth = math.max(
                        96.0,
                        math.min(
                          headerConstraints.maxWidth * 0.48,
                          headerConstraints.maxWidth - 180,
                        ),
                      );
                      return Center(
                        child: ConstrainedBox(
                          constraints: BoxConstraints(maxWidth: titleMaxWidth),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Flexible(
                                child: _NowPlayingTitleReveal(
                                  rawTitle: title,
                                  accentColor: accentColor,
                                  visible: controlsVisible,
                                  compact: false,
                                ),
                              ),
                              if (buffering) ...[
                                const SizedBox(width: 10),
                                const _InlineBufferingBadge(),
                              ],
                            ],
                          ),
                        ),
                      );
                    },
                  ),
                if (!locked &&
                    nextEpisodeLabel != null &&
                    onNextEpisode != null)
                  Align(
                    alignment: Alignment.centerRight,
                    child: Padding(
                      padding: EdgeInsets.only(right: padding.right + 12),
                      child: _NextEpisodeButton(
                        label: nextEpisodeLabel!,
                        onPressed: onNextEpisode!,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
        if (initialized && !locked)
          Positioned(
            right: padding.right + 150,
            bottom: padding.bottom + 102,
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 230),
              reverseDuration: const Duration(milliseconds: 160),
              switchInCurve: Curves.easeOutCubic,
              switchOutCurve: Curves.easeInCubic,
              transitionBuilder: (child, animation) {
                return FadeTransition(
                  opacity: animation,
                  child: SlideTransition(
                    position: Tween<Offset>(
                      begin: const Offset(0, 0.08),
                      end: Offset.zero,
                    ).animate(animation),
                    child: ScaleTransition(
                      scale: Tween<double>(
                        begin: 0.96,
                        end: 1,
                      ).animate(animation),
                      alignment: Alignment.bottomRight,
                      child: child,
                    ),
                  ),
                );
              },
              child: settingsExpanded
                  ? _SettingsActionMenu(
                      key: const ValueKey('settings-expanded'),
                      limitedMode: limitedSettingsMode,
                      liveMode: liveMode,
                      qualityLabel: qualityLabel,
                      onQualityPressed: onQualityPressed,
                      speedLabel: speedLabel,
                      onSpeedPressed: onSpeedPressed,
                      fitMode: fitMode,
                      onFitPressed: onFitPressed,
                      onReloadPressed: onReloadPressed,
                      subtitlesAvailable: subtitlesAvailable,
                      subtitlesEnabled: subtitlesEnabled,
                      onSubtitlePressed: onSubtitlePressed,
                    )
                  : const SizedBox(
                      key: ValueKey('settings-collapsed'),
                      width: 0,
                      height: 0,
                    ),
            ),
          ),
        if (initialized)
          SafeArea(
            child: Align(
              alignment: Alignment.bottomCenter,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(22, 0, 22, 12),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (!locked)
                      Padding(
                        padding: const EdgeInsets.only(bottom: 4),
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.center,
                          children: [
                            Expanded(
                              child: Align(
                                alignment: Alignment.centerLeft,
                                child: skipSegment != null &&
                                        onSkipSegment != null &&
                                        !liveMode
                                    ? _SkipSegmentButton(
                                        label: skipSegment!.label,
                                        onPressed: onSkipSegment!,
                                      )
                                    : const SizedBox.shrink(),
                              ),
                            ),
                            Row(
                              crossAxisAlignment: CrossAxisAlignment.center,
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                _StagedHudControlReveal(
                                  visible: controlsVisible,
                                  delay: const Duration(milliseconds: 240),
                                  hideDelay: Duration.zero,
                                  beginOffset: const Offset(0, 0.10),
                                  child: _SourceActionButton(
                                    onPressed: onSourcePressed,
                                    enabled: sourceSelectionAvailable,
                                    label: sourceActionLabel,
                                    detailLabel: sourceIndicator,
                                  ),
                                ),
                                const SizedBox(width: 8),
                                _StagedHudControlReveal(
                                  visible: controlsVisible,
                                  delay: const Duration(milliseconds: 180),
                                  hideDelay: const Duration(milliseconds: 60),
                                  beginOffset: const Offset(0, 0.10),
                                  child: _SettingsControlPack(
                                    expanded: settingsExpanded,
                                    onToggleSettings: onToggleSettings,
                                  ),
                                ),
                                const SizedBox(width: 8),
                                _StagedHudControlReveal(
                                  visible: controlsVisible,
                                  delay: const Duration(milliseconds: 120),
                                  hideDelay: const Duration(milliseconds: 120),
                                  beginOffset: const Offset(0, 0.10),
                                  child: _PlayerRoundButton(
                                    icon: Icons.cast_rounded,
                                    semanticLabel: 'Cast',
                                    onPressed: onOpenCast,
                                    size: 44,
                                  ),
                                ),
                                const SizedBox(width: 8),
                                _StagedHudControlReveal(
                                  visible: controlsVisible,
                                  delay: const Duration(milliseconds: 60),
                                  hideDelay: const Duration(milliseconds: 180),
                                  beginOffset: const Offset(0, 0.10),
                                  child: _PlayerRoundButton(
                                    icon: Icons.picture_in_picture_alt_rounded,
                                    semanticLabel: 'Picture in picture',
                                    onPressed: onEnterPip,
                                    enabled: pipSupported,
                                    size: 44,
                                  ),
                                ),
                                const SizedBox(width: 8),
                                _StagedHudControlReveal(
                                  visible: controlsVisible,
                                  delay: Duration.zero,
                                  hideDelay: const Duration(milliseconds: 240),
                                  beginOffset: const Offset(0, 0.10),
                                  child: _PlayerRoundButton(
                                    icon: Icons.lock_open_rounded,
                                    semanticLabel: 'Lock controls',
                                    onPressed: onToggleLock,
                                    size: 44,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      )
                    else
                      Align(
                        alignment: Alignment.centerRight,
                        child: Padding(
                          padding: const EdgeInsets.only(right: 2, bottom: 4),
                          child: _PlayerRoundButton(
                            icon: Icons.lock_rounded,
                            semanticLabel: 'Unlock controls',
                            onPressed: onToggleLock,
                            size: 44,
                          ),
                        ),
                      ),
                    if (!locked && !liveMode)
                      Row(
                        children: [
                          Text(
                            _formatDuration(position),
                            style: const TextStyle(
                              color: Colors.white,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          Expanded(
                            child: SliderTheme(
                              data: SliderTheme.of(context).copyWith(
                                trackHeight: 6,
                                trackShape:
                                    const _UniformBufferedSliderTrackShape(),
                                thumbShape: SliderComponentShape.noThumb,
                                overlayShape: const RoundSliderOverlayShape(
                                  overlayRadius: 15,
                                ),
                                activeTrackColor: _playerAccent(context),
                                inactiveTrackColor: _playerUnbufferedTrackColor,
                                secondaryActiveTrackColor:
                                    _playerBufferedTrackColor,
                                overlayColor: _playerAccentOverlay(
                                  context,
                                  0.20,
                                ),
                              ),
                              child: Slider(
                                value: watchedProgress,
                                secondaryTrackValue: bufferedProgress,
                                onChanged:
                                    initialized ? onSeekToFraction : null,
                              ),
                            ),
                          ),
                          Text(
                            _formatDuration(duration),
                            style: const TextStyle(
                              color: Colors.white,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ],
                      ),
                  ],
                ),
              ),
            ),
          ),
      ],
    );
  }
}

class _UniformBufferedSliderTrackShape extends RoundedRectSliderTrackShape {
  const _UniformBufferedSliderTrackShape();

  @override
  void paint(
    PaintingContext context,
    Offset offset, {
    required RenderBox parentBox,
    required SliderThemeData sliderTheme,
    required Animation<double> enableAnimation,
    required TextDirection textDirection,
    required Offset thumbCenter,
    Offset? secondaryOffset,
    bool isDiscrete = false,
    bool isEnabled = false,
    double additionalActiveTrackHeight = 2,
  }) {
    super.paint(
      context,
      offset,
      parentBox: parentBox,
      sliderTheme: sliderTheme,
      enableAnimation: enableAnimation,
      textDirection: textDirection,
      thumbCenter: thumbCenter,
      secondaryOffset: secondaryOffset,
      isDiscrete: isDiscrete,
      isEnabled: isEnabled,
      additionalActiveTrackHeight: 0,
    );
  }
}

