  Future<void> _showDelaySheet() async {
    await showModalBottomSheet<void>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (context) {
        final colorScheme = Theme.of(context).colorScheme;
        return SafeArea(
          child: Align(
            alignment: Alignment.bottomCenter,
            child: Container(
              margin: const EdgeInsets.all(14),
              padding: const EdgeInsets.fromLTRB(14, 8, 14, 14),
              decoration: BoxDecoration(
                color: colorScheme.surface,
                borderRadius: JuicrVisual.bottomSheetFloatingBorderRadius,
                boxShadow: JuicrVisual.softShadow(
                  colorScheme,
                  alpha: 0.16,
                  blur: 24,
                  y: 10,
                ),
              ),
              child: StatefulBuilder(
                builder: (context, setSheetState) {
                  final label = _subtitleDelayLabel(_delaySeconds);
                  return Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Container(
                        width: 42,
                        height: 4,
                        margin: const EdgeInsets.only(bottom: 14),
                        decoration: BoxDecoration(
                          color: colorScheme.onSurface.withValues(alpha: 0.28),
                          borderRadius: BorderRadius.circular(99),
                        ),
                      ),
                      Row(
                        children: [
                          Expanded(
                            child: Text(
                              'Subtitle sync',
                              style: Theme.of(context)
                                  .textTheme
                                  .titleMedium
                                  ?.copyWith(
                                    fontWeight: FontWeight.w900,
                                    fontSize: 15,
                                  ),
                            ),
                          ),
                          Text(
                            label,
                            style: TextStyle(
                              color: colorScheme.primary,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 8),
                      Slider(
                        value: _delaySeconds,
                        min: -10,
                        max: 10,
                        divisions: 40,
                        label: label,
                        onChanged: (value) {
                          final rounded = (value * 2).round() / 2;
                          setState(() => _delaySeconds = rounded);
                          setSheetState(() {});
                          widget.onDelayChanged(rounded);
                        },
                      ),
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(
                            '-10s',
                            style: TextStyle(
                              color: colorScheme.onSurfaceVariant,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          TextButton(
                            onPressed: () {
                              setState(
                                () =>
                                    _delaySeconds = widget.defaultDelaySeconds,
                              );
                              setSheetState(() {});
                              widget.onDelayResetToDefault();
                            },
                            child: const Text('Use default'),
                          ),
                          Text(
                            '+10s',
                            style: TextStyle(
                              color: colorScheme.onSurfaceVariant,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ],
                      ),
                    ],
                  );
                },
              ),
            ),
          ),
        );
      },
    );
  }

