                        const SizedBox(height: 8),
                        _SubtitlePreview(
                          text: 'Subtitle preview\nTwo-line cues stay stacked.',
                          fontSize: _fontSize,
                          backgroundOpacity: _backgroundOpacity,
                          backgroundColor: _backgroundColor,
                          backgroundRadius: _backgroundRadius,
                          textColor: _textColor,
                        ),
                        const SizedBox(height: 10),
                        _SubtitleSlider(
                          label: 'Text size',
                          value: _fontSize,
                          min: 13,
                          max: 24,
                          divisions: 11,
                          valueLabel: '${_fontSize.round()}',
                          onChanged: (value) {
                            setState(() => _fontSize = value);
                            setSheetState(() {});
                            widget.onFontSizeChanged(value);
                          },
                        ),
                        const SizedBox(height: 6),
                        _SubtitleSlider(
                          label: 'Position',
                          value: _bottomOffset,
                          min: 18,
                          max: 96,
                          divisions: 26,
                          valueLabel: _subtitlePositionLabel(_bottomOffset),
                          onChanged: (value) {
                            final rounded = value.roundToDouble();
                            setState(() => _bottomOffset = rounded);
                            setSheetState(() {});
                            widget.onBottomOffsetChanged(rounded);
                          },
                        ),
                        const SizedBox(height: 6),
                        _SubtitleSlider(
                          label: 'Roundness',
                          value:
                              _backgroundRadius >= 999 ? 32 : _backgroundRadius,
                          min: 0,
                          max: 32,
                          divisions: 8,
                          valueLabel: _backgroundRadius >= 999
                              ? 'Full'
                              : _backgroundRadius.round().toString(),
                          onChanged: (value) {
                            final radius = value >= 32 ? 999.0 : value;
                            setState(() => _backgroundRadius = radius);
                            setSheetState(() {});
                            widget.onBackgroundRadiusChanged(radius);
                          },
                        ),
                        const SizedBox(height: 6),
                        _SubtitleColorPicker(
                          title: 'Background',
                          selectedColor: _backgroundOpacity <= 0
                              ? Colors.transparent
                              : _backgroundColor,
                          colors: const [
                            Colors.transparent,
                            Colors.black,
                            Color(0xFF2B2933),
                            Color(0xFF281B54),
                          ],
                          onSelected: (color) {
                            final opacity = color == Colors.transparent
                                ? 0.0
                                : color.opacity < 1
                                    ? color.opacity
                                    : 0.74;
                            setState(() {
                              _backgroundColor = color == Colors.transparent
                                  ? Colors.black
                                  : color.withAlpha(255);
                              _backgroundOpacity = opacity;
                            });
                            setSheetState(() {});
                            widget.onBackgroundColorChanged(_backgroundColor);
                            widget.onBackgroundOpacityChanged(opacity);
                          },
                        ),
                        const SizedBox(height: 8),
                        _SubtitleColorPicker(
                          title: 'Text color',
                          selectedColor: _textColor,
                          colors: const [
                            Colors.white,
                            Color(0xFFFFF2A6),
                            Color(0xFF9EE7FF),
                            Color(0xFF111111),
                          ],
                          onSelected: (color) {
                            setState(() => _textColor = color);
                            setSheetState(() {});
                            widget.onTextColorChanged(color);
                          },
                        ),
                      ],
                    ),
                  );
                },
              ),
            ),
          ),
        );
      },
    );
  }
}

