          child: Wrap(
            alignment: WrapAlignment.end,
            spacing: 8,
            runSpacing: 8,
            children: [
              for (final color in colors)
                _SubtitleColorDot(
                  color: color,
                  selected: color.value == selectedColor.value,
                  semanticLabel: '$title preset color',
