class _LoadingTitleWheel extends StatelessWidget {
  const _LoadingTitleWheel({
    required this.controller,
    required this.title,
    this.logoUrl,
  });

  final Animation<double> controller;
  final String title;
  final String? logoUrl;

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;
    final style = textTheme.displayMedium?.copyWith(
          color: Colors.white,
          fontSize: 68,
          fontWeight: FontWeight.w900,
          height: 0.82,
          letterSpacing: -1.6,
        ) ??
        const TextStyle(
          color: Colors.white,
          fontSize: 68,
          fontWeight: FontWeight.w900,
          height: 0.82,
          letterSpacing: -1.6,
        );

    return AnimatedBuilder(
      animation: controller,
      builder: (context, child) {
        final progress = controller.value;
        final pulse = 0.985 + (math.sin(progress * math.pi * 2) + 1) * 0.006;
        final shimmerStart = -1.2 + progress * 2.4;

        final logo = logoUrl?.trim();
        return Transform.scale(
          scale: pulse,
          child: logo != null && logo.isNotEmpty
              ? ConstrainedBox(
                  constraints: const BoxConstraints(
                    maxWidth: 380,
                    maxHeight: 160,
                  ),
                  child: Image.network(
                    logo,
                    fit: BoxFit.contain,
                    errorBuilder: (_, __, ___) => _LoadingFallbackTitle(
                      title: title,
                      style: style,
                      shimmerStart: shimmerStart,
                    ),
                  ),
                )
              : _LoadingFallbackTitle(
                  title: title,
                  style: style,
                  shimmerStart: shimmerStart,
                ),
        );
      },
    );
  }
}

class _LoadingFallbackTitle extends StatelessWidget {
  const _LoadingFallbackTitle({
    required this.title,
    required this.style,
    required this.shimmerStart,
  });

  final String title;
  final TextStyle style;
  final double shimmerStart;

  @override
  Widget build(BuildContext context) {
    final accent = _playerAccent(context);
    return ShaderMask(
      blendMode: BlendMode.srcIn,
      shaderCallback: (bounds) {
        return LinearGradient(
          begin: Alignment(shimmerStart, -0.4),
          end: Alignment(shimmerStart + 0.9, 0.4),
          colors: [
            const Color(0x99FFFFFF),
            Colors.white,
            accent,
            Colors.white,
            const Color(0x99FFFFFF),
          ],
          stops: const [0, 0.36, 0.5, 0.64, 1],
        ).createShader(bounds);
      },
      child: Text(
        title.toUpperCase(),
        textAlign: TextAlign.center,
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
        style: style,
      ),
    );
  }
}

