class _SeekButton extends StatefulWidget {
  const _SeekButton({
    required this.forward,
    required this.seconds,
    required this.onPressed,
  });

  final bool forward;
  final int seconds;
  final VoidCallback onPressed;

  @override
  State<_SeekButton> createState() => _SeekButtonState();
}

class _SeekButtonState extends State<_SeekButton>
    with SingleTickerProviderStateMixin {
  late final AnimationController _spinController;
  late final Animation<double> _turns;

  @override
  void initState() {
    super.initState();
    _spinController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 420),
    );
    final direction = widget.forward ? 1.0 : -1.0;
    _turns = CurvedAnimation(
      parent: _spinController,
      curve: Curves.easeOutCubic,
    ).drive(Tween<double>(begin: 0, end: direction));
  }

  @override
  void dispose() {
    _spinController.dispose();
    super.dispose();
  }

  void _handlePressed() {
    if (!juicrMotionDisabled(context)) {
      _spinController.forward(from: 0);
    }
    widget.onPressed();
  }

  @override
  Widget build(BuildContext context) {
    final label = widget.forward
        ? 'Skip forward ${widget.seconds} seconds'
        : 'Skip back ${widget.seconds} seconds';
    return Semantics(
      button: true,
      label: label,
      child: ExcludeSemantics(
        child: SizedBox.square(
          dimension: 76,
          child: IconButton(
            tooltip: label,
            onPressed: _handlePressed,
            iconSize: 42,
            color: Colors.white,
            style: IconButton.styleFrom(
              backgroundColor: Colors.black45,
              shape: const CircleBorder(),
            ),
            icon: Stack(
              alignment: Alignment.center,
              children: [
                RotationTransition(
                  turns: _turns,
                  child: Icon(
                    widget.forward
                        ? Icons.rotate_right_rounded
                        : Icons.rotate_left_rounded,
                  ),
                ),
                Padding(
                  padding: EdgeInsets.only(
                    top: 2,
                    left: widget.forward ? 2 : 0,
                    right: widget.forward ? 0 : 2,
                  ),
                  child: Text(
                    '${widget.seconds}',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 11,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

