class _GestureHintRailState extends State<_GestureHintRail> {
  Timer? _iconRevealTimer;
  bool _iconVisible = false;

  @override
  void initState() {
    super.initState();
    _iconRevealTimer = Timer(const Duration(milliseconds: 120), () {
      if (!mounted) return;
      setState(() => _iconVisible = true);
    });
  }

  @override
  void dispose() {
    _iconRevealTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Semantics(
      label: '${widget.label} gesture hint',
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(
            Icons.keyboard_arrow_up_rounded,
            color: Colors.white,
            size: 22,
          ),
          const SizedBox(height: 4),
          AnimatedOpacity(
            opacity: _iconVisible ? 1 : 0,
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOut,
            child: AnimatedScale(
              scale: _iconVisible ? 1 : 0.86,
              duration: const Duration(milliseconds: 180),
              curve: Curves.easeOutBack,
              child: Container(
                width: 52,
                height: 52,
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.46),
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withValues(alpha: 0.30),
                      blurRadius: 14,
                      offset: const Offset(0, 6),
                    ),
                  ],
                ),
                child: Icon(widget.icon, color: Colors.white, size: 24),
              ),
            ),
          ),
          const SizedBox(height: 4),
          const Icon(
            Icons.keyboard_arrow_down_rounded,
            color: Colors.white,
            size: 22,
          ),
        ],
      ),
    );
  }
}

String _formatDuration(Duration duration) {
  final totalSeconds = duration.inSeconds;
  final hours = totalSeconds ~/ 3600;
  final minutes = (totalSeconds % 3600) ~/ 60;
  final seconds = totalSeconds % 60;
  if (hours > 0) {
    return '$hours:${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
  }
  return '$minutes:${seconds.toString().padLeft(2, '0')}';
}

class _SubtitleCue {
  const _SubtitleCue({
    required this.start,
    required this.end,
    required this.text,
  });

  final Duration start;
  final Duration end;
  final String text;
}

List<_SubtitleCue> _parseWebVtt(String input) {
  final normalized = input
      .replaceAll('\uFEFF', '')
      .replaceAll('\r\n', '\n')
      .replaceAll('\r', '\n')
      .replaceAll(r'\N', '\n')
      .replaceAll('&nbsp;', ' ')
      .replaceAll('&amp;', '&')
      .replaceAll('&lt;', '<')
      .replaceAll('&gt;', '>');
  final directCues = _parseSubtitleBlocks(normalized.split('\n\n'));
  if (directCues.isNotEmpty) return directCues;

  final compactBlocks = RegExp(
    r'((?:\d+\s*\n)?\d{1,2}:\d{2}:\d{2}[,.]\d{1,3}\s*-->\s*\d{1,2}:\d{2}:\d{2}[,.]\d{1,3}[\s\S]*?)(?=\n\s*\d+\s*\n\s*\d{1,2}:\d{2}:\d{2}[,.]\d{1,3}\s*-->|\z)',
  )
      .allMatches(normalized)
      .map((match) => match.group(1) ?? '')
      .where((block) => block.trim().isNotEmpty)
      .toList();
  return _parseSubtitleBlocks(compactBlocks);
}

List<_SubtitleCue> _parseSubtitleBlocks(List<String> blocks) {
  final cues = <_SubtitleCue>[];

  for (final block in blocks) {
    final lines = block
        .split('\n')
        .map((line) => line.trim())
        .where(
          (line) =>
              line.isNotEmpty &&
              !line.startsWith('WEBVTT') &&
              !line.startsWith('NOTE'),
        )
        .toList();
    if (lines.isEmpty) continue;

    final timingIndex = lines.indexWhere((line) => line.contains('-->'));
    if (timingIndex < 0) continue;

    final parts = lines[timingIndex].split('-->');
    if (parts.length < 2) continue;

    final start = _parseSubtitleTime(parts[0]);
    final end = _parseSubtitleTime(parts[1].trim().split(RegExp(r'\s+')).first);
    if (start == null || end == null || end <= start) continue;

    final text = lines
        .skip(timingIndex + 1)
        .join('\n')
        .replaceAll(RegExp(r'\{\\[^}]+\}'), '')
        .replaceAll(RegExp(r'<[^>]+>'), '')
        .trim();
    if (text.isEmpty) continue;

    cues.add(_SubtitleCue(start: start, end: end, text: text));
  }

  return cues;
}

Duration? _parseSubtitleTime(String raw) {
  final clean = raw.trim().replaceAll(',', '.');
  final parts = clean.split(':');
  if (parts.length < 2 || parts.length > 3) return null;

  final secondsPart = parts.last.split('.');
  final seconds = int.tryParse(secondsPart.first);
  final millis = secondsPart.length > 1
      ? int.tryParse(secondsPart[1].padRight(3, '0').substring(0, 3)) ?? 0
      : 0;
  final minutes = int.tryParse(parts[parts.length - 2]);
  final hours = parts.length == 3 ? int.tryParse(parts.first) : 0;
  if (seconds == null || minutes == null || hours == null) return null;

  return Duration(
    hours: hours,
    minutes: minutes,
    seconds: seconds,
    milliseconds: millis,
  );
}

bool _isTemporaryResolverBlock(Object error) {
  final text = error.toString().toLowerCase();
  return error is StreamApiTemporaryBlockException ||
      text.contains('streamapitemporaryblockexception') ||
      text.contains('temporary_block') ||
      text.contains('rate limit') ||
      text.contains('retry after') ||
      text.contains('temporarily blocked') ||
      text.contains('taking longer than usual') ||
      text.contains('too many requests');
}

class _ControlGradient extends StatelessWidget {
  const _ControlGradient({required this.alignment});

  final Alignment alignment;

  @override
  Widget build(BuildContext context) {
    final isTop = alignment == Alignment.topCenter;

    return Align(
      alignment: alignment,
      child: IgnorePointer(
        child: Container(
          height: 64,
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: isTop ? Alignment.topCenter : Alignment.bottomCenter,
              end: isTop ? Alignment.bottomCenter : Alignment.topCenter,
              colors: [
                Colors.black.withValues(alpha: 0.30),
                Colors.black.withValues(alpha: 0.06),
                Colors.transparent,
              ],
              stops: const [0, 0.46, 1],
            ),
          ),
        ),
      ),
    );
  }
}
